(window.GIM_TS=window.GIM_TS||{})["Zevachim.7"]={"from":168,"a":[["\u0003יכול\u0004 אתה לפרש ש\u0003יחלוץ\u0004 (יוציא) הכהן תחילה את ה\u0003גידין ועצמות\u0004 מן הקרבן, \u0003ו\u0004רק אחר כך \u0003יעלה\u0004 את ה\u0003בשר\u0004 בלבד \u0003לגבי\u0004 (אצל) ה\u0003מזבח?\u0004 \u0003תלמוד לומר: \"והקטיר הכהן את הכל\u0004 המזבחה\" (ויקרא א, ט), ואף את הגידים והעצמות. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יעשה איפוא בגידים ובעצמות? אם היו \u0003מחוברין\u0004 — \u0003יעלו, ואם\u0004 \u0003פירשו, אפילו הן בראש המזבח\u0004 — \u0003ירדו. ומעירים:\u0004","\u0003מאן תנא דשמעת ליה דאמר\u0004 \u0005[מיהו התנא ששמעת אותו שהוא אומר]:\u0006 \u0003פירשו ירדו?\u0004 דעת \u0003רבי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"והקטיר הכהן את הכל המזבחה\"\u0004 (ויקרא א, ט) — הרי לשון זו (\"הכל\") באה \u0003לרבות\u0004 להקרבה אף את \u0003העצמות והגידין והקרנים והטלפים,\u0004 ו\u0003אפילו פירשו\u0004 מגוף הקרבן.","\u0003ואלא מה אני מקיים \"ועשית עלתיך הבשר והדם\"\u0004 (דברים יב, כז), שמשמעו דווקא בשר ודם ולא עצמות וגידים? כתוב זה בא \u0003לומר לך\u0004 הלכה אחרת: \u0003עיכולי עולה\u0004 חתיכות בשר שאחזה בהם האש, ופקעו משם, \u0003אתה מחזיר\u0004 לאש, \u0003ואי אתה מחזיר עיכולי גידין ועצמות.\u0004","ואילו \u0003רבי אומר, כתוב אחד אומר: \"והקטיר הכהן את הכל המזבחה\"\u0004 — הרי זה \u0003ריבה\u0004 אף גידים ועצמות, \u0003וכתוב אחד אומר: \"ועשית עלתיך הבשר והדם\"\u0004 — הרי זה \u0003מיעט\u0004 כל דבר חוץ מבשר ודם, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יעשה איפוא בגידים ועצמות? אם היו \u0003מחוברין\u0004 לזבח — \u0003יעלו, פירשו\u0004 ממנו, \u0003אפילו הן בראש המזבח\u0004 — \u0003ירדו.\u0004","שנינו במשנה שדברים שאינם עומדים כלל להקרבה, כגון עצמות וגידים, בזמן שהם מחוברים לקרבן יעלו, ואם \u0003פירשו לא יעלו [וכו']. אמר ר' זירא: לא שנו אלא שפירשו\u0004 מן הזבח \u0003כלפי מטה\u0004 כלומר, חוץ למזבח, שנתרחקו בכך מן המערכה. \u0003אבל\u0004 אם פירשו מן הזבח \u0003כלפי מעלה\u0004 שנתקרבו אל המערכה — \u0003קרובי הוא דאקריבו\u0004 \u0005[התקרבו]\u0006 יותר \u0003לעיכול\u0004 (להקרבה), ויעלו. ותמהים: \u0003ואפילו פירשו\u0004 יקרבו?! והרי אמרנו כי רק כשהם מחוברים יעלו!","\u0003אמר רבה, הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 זו כוונת הדברים: \u0003לא שנו,\u0004 כלומר, לא הוצרכנו לומר שעצמות וגידים שפירשו לא יעלו \u0003אלא\u0004 במקרה \u0003שפירשו לאחר זריקה\u0004 של הדם, כיון שבשעה שנזרק הדם והותר הקרבן בהקרבה היו מחוברים לבשר, וראויים ליקרב עמו. \u0003אבל\u0004 אם \u0003פירשו\u0004 מן הזבח \u0003קודם זריקה,\u0004 אין צורך לומר שלא יעלו, אלא כיון שאינם ראויים באותה שעה להקרבה, \u0003אתאי\u0004 \u0005[באה]\u0006 ה\u0003זריקה ושריתינהו\u0004 \u0005[והתירה אותם]\u0006 כפי שהתירה את עור העולה לכהנים, והריהם מותרים לכל שימוש שהוא, ו\u0003אפילו למעבד מינייהו קתא דסכיני\u0004 \u0005[לעשות מהן\u0006 מן העצמות והקרנים \u0005קתות של סכינים].\u0006","ומסבירים: \u0003סבר לה כי הא\u0004 \u0005[סבור הוא כמו\u0006 שיטה \u0005זו]\u0006 ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל: נאמר \"לו יהיה\" בעולה\u0004 (\"עור העולה אשר הקריב לכהן לו יהיה\", ויקרא ז, ח), \u0003ונאמר\u0004 \"הכהן אשר יכפר בו \u0003לו יהיה\"\u0004 (ויקרא ז, ז) \u0003באשם,\u0004 ללמד בגזירה שווה: \u0003מה אשם\u0004 — לאחר זריקת הדם \u0003עצמותיו מותרין\u0004 לכהן לכל שימוש, שהרי רק אימוריו קרבים, וכל שאר הזבח ניתן לכהנים, \u0003אף עולה\u0004 — \u0003עצמות\u0004 (שאינן מחוברות) \u0003מותרין.\u0004","ומעירים: הביטוי \"לו יהיה\" שממנו נלמדה הגזירה השווה הינו \u0003מופני\u0004 \u0005[מופנה]\u0006 שאינו נצרך לעניינו, ונאמר איפוא רק לשם הדרשה. וכלל הוא שגזירה שווה שכזו אין מקשים עליה. \u0003דאי לא מופני\u0004 \u0005[ש\u0006כן \u0005אם אינו מופנה],\u0006 \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך]\u0006 ולהקשות על ההשוואה שבין אשם ועולה, ולומר: \u0003מה לאשם שכן בשרו מותר,\u0004 ולכן גם עצמותיו מותרים. ואין ללמוד מכאן לעולה שבשרה כולו עולה למזבח! ומהו אותו כתוב מופנה — \u0003\"לו יהיה\"\u0004 האמור לגבי עולה \u0003יתירא כתיב\u0004 \u0005[יתר\u0006 הוא \u0005כתוב],\u0006 שדי היה במה שנאמר \"עור העולה אשר הקריב לכהן\", ואין צורך לחזור ולומר \"לו יהיה\", אלא מופנה הוא לגזירה שווה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אדא בר אהבה\u0004 ממה ששנינו בברייתא: \u0003עצמות\u0004 של \u0003קדשים\u0004 כלומר, קדשי קדשים העומדים לאכילה, כגון חטאת ואשם, \u0003לפני\u0004 ה\u0003זריקה\u0004 של הדם — \u0003מועלין בהן\u0004 כלומר, יש בהם דין מעילה, כדין בשר קדשי קדשים קודם זריקה,","\u0003לאחר זריקה\u0004 — \u0003אין מועלין בהן,\u0004 שהרי אינם עומדים להקרבה. \u0003ו\u0004אילו עצמות \u0003של עולה\u0004 — \u0003מועלין בהן לעולם,\u0004 והרי זה שלא כרבה, שאמר שאם פירשו עצמות העולה קודם זריקה הריהם מותרים בהנאה!","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003ושל עולה,\u0004 אם \u0003פירשו לפני זריקה\u0004 ונזרק הדם — \u0003אין מועלין בהן,\u0004 אם פירשו \u0003לאחר זריקה\u0004 — \u0003מועלין בהן לעולם.\u0004","ואומרים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטה זו של רבה, על שיטת \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: פירשו\u0004 עצמות העולה \u0003לפני זריקה\u0004 — \u0003מועלין בהם,\u0004 פירשו \u0003לאחר זריקה\u0004 — \u0003לא נהנין\u0004 מהם, שחכמים אסרום בהנאה, \u0003ו\u0004אולם אם נהנו \u0003לא מועלין\u0004 בהם, אין בהם דין מעילה, שכן מדין תורה הותרו בזריקת הדם.","\u0003וכולן\u0004 כל אלה הפסולים להקרבה ששנינו בהם (פד,א) שאם עלו על המזבח לא ירדו, במקרה \u0003שפקעו\u0004 (ניתזו) מחום האש \u0003מעל גבי המזבח\u0004 — \u0003לא יחזיר\u0004 אותם הכהן למזבח. \u0003וכן גחלת שפקעה מעל גבי המזבח\u0004 — \u0003לא יחזיר. איברים\u0004 של עולה כשירה \u0003שפקעו מעל גבי המזבח,\u0004 אם פקעו \u0003קודם חצות\u0004 הלילה — \u0003יחזיר, ומועלין בהן\u0004 (יש בהם דין מעילה) \u0003לאחר חצות\u0004 — \u0003לא יחזיר, ואין מועלין בהם,\u0004 שכן כבר נעשתה מצוותם, וכל שנעשתה מצוותו שוב אין בו מעילה.","ועוד בדין דברים הפסולים להקרבה שאם עלו לא ירדו: \u0003כשם שהמזבח מקדש את הראוי לו,\u0004 והריהו קרב, \u0003כך הכבש מקדש,\u0004 שכל דבר שעלה לכבש דינו כאילו עלה על המזבח. \u0003כשם שהמזבח והכבש מקדשין את הראוי להן, כך הכלים\u0004 של קודש \u0003מקדשין\u0004 את הדברים שמניחים בהם.","על דברי המשנה שאיברי עולה שפקעו מעל המזבח לפני חצות יחזירם, ולאחר חצות אין צורך להחזירם, שואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דאית בהו\u0004 \u0005[אם\u0006 מדובר כ\u0005שיש בהם]\u0006 \u0003ממש\u0004 באיברים, שלא נשרפו כליל, ויש בהם עדיין מקצת בשר — \u0003אפילו לאחר חצות נמי\u0004 \u0005[גם כן]\u0006 צריך להחזירם! \u0003אי דלית בהו\u0004 \u0005[אם שאין בהם]\u0006 \u0003ממש\u0004 ונעשו אפר — \u0003אפילו קודם חצות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא"],["\u0003בשרירי\u0004 \u0005[ב\u0006איברים \u0005קשים]\u0006 שהאש אכלה בהם עד שנתייבשו, אך לא נעשו אפר, ועד חצות יש מצוה להקטירם. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שזמן חצות הלילה קובע בענין זה?","\u0003אמר רב, כתוב אחד אומר: \"כל הלילה והקטיר\",\u0004 שמצוה להקטיר כל הלילה את איברי העולה, כאמור: \"היא העולה על מוקדה על המזבח כל הלילה עד הבקר\" (ויקרא ו, ב), \u0003ו\u0004אילו \u0003כתוב אחד אומר: \"כל הלילה... והרים\u0004 את הדשן אשר תאכל האש את העולה... ושמו אצל המזבח\" (ויקרא ו, ב—ג), משמע שכבר מתחילת הלילה ניתן להרים את הדשן, ובכלל זה איברי העולה שכבר אכלה האש.","וכדי ליישב סתירה זו יש לומר: \u0003חלקיהו\u0004 את הלילה לשני חלקים, \u0003חציו ל\u0004מצות \u0003הקטרה\u0004 ומה שפקע — יחזיר, \u0003וחציו להרמה\u0004 שמחצות הלילה נגמרה מצות ההקטרה, וניתן להרים את הדשן.","על דברי רב, שרק בחצות מתחילה מצות תרומת הדשן, \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב כהנא\u0004 מן המשנה: \u0003בכל יום תורם את המזבח\u0004 מרים ממנו מעט דשן ומניחו בצד המזבח, \u0003מ\u0004זמן \u0003קרות הגבר\u0004 (קריאת הכרוז בבית המקדש, או קריאת התרנגול) \u0003או\u0004 בזמן ה\u0003סמוך לו,\u0004 בין \u0003מלפניו [או] מאחריו, ביום הכיפורים\u0004 — תורם \u0003בחצות,\u0004 ואילו \u0003ברגלים\u0004 — תורם \u0003באשמורת הראשונה,\u0004 בסוף השליש הראשון של הלילה. ומעתה יש לשאול: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שזמן תרומת הדשן \u0003מחצות דאורייתא\u0004 \u0005[מן התורה]\u0006 היא, כפי שדרש רב מן הכתובים, \u0003היכי מקדמינן והיכי מאחרינן\u0004 \u0005[כיצד מקדימים אנו\u0006 ברגלים \u0005וכיצד מאחרים אנו\u0006 בכל ימות השנה\u0005]?\u0006","\u0003אלא אמר ר' יוחנן:\u0004 לא מכאן למדים את זמנה של תרומת הדשן, אלא באופן זה: \u0003ממשמע שנאמר\u0004 לענין הקטרת האיברים \u0003\"כל הלילה\"\u0004 (ויקרא ו, ב), \u0003איני יודע ש\u0004היא \u0003עד הבקר?\u0004 אם כן \u0003מה תלמוד לומר\u0004 מיד אחר כך \u0003\"עד בקר\"\u0004 (ויקרא ו, ב)? ללמדנו לענין תרומת הדשן הנזכרת מיד אחר כך: \u0003תן בקר לבקרו של לילה\u0004 כלומר, יכול אתה להקדים ולעשותה כבר מתחילת הלילה,","\u0003הלכך\u0004 \u0005[על כן]\u0006 ב\u0003כל יומא\u0004 \u0005[יום]\u0006 מימות השנה \u0003מקרות הגבר סגי\u0004 \u0005[מספיק].\u0006 \u0003ביום הכיפורים, משום חולשא\u0004 \u0005[חולשה]\u0006 של \u0003כהן גדול\u0004 שהרי עליו מוטלת כל עבודת היום — מקדימים ותורמים \u0003מחצות. ברגלים, דנפישי\u0004 \u0005[שמרובים]\u0006 \u0003קרבנות\u0004 שמביאים העולים לרגל, \u0003דקדמי אתו\u0004 \u0005[ש\u0006משום כך \u0005מקדימים ובאים]\u0006 \u0003ישראל\u0004 לבית המקדש עם קרבנותיהם — תורמים את הדשן כבר \u0003מאשמורת הראשונה, כדקתני סיפא\u0004 \u0005[כמו ששנו בסופה]\u0006 של משנה זו, כי ברגלים \u0003לא היתה קריית\u0004 (קריאת) \u0003הגבר מגעת עד שהיתה עזרה מלאה מישראל.\u0004","ובענין ששנינו במשנתנו, שאיברים שאכלה האש ונתקשו (\"שרירי\"), חצות הלילה מחשיבם כמעוכלים, ונגמרה מצוותם, ואם פקעו מן המזבח אין צורך להחזירם. \u0003איתמר\u0004 \u0005[נאמר]\u0006 כי נחלקו אמוראים בבעיה הבאה: \u0003פירשו\u0004 האברים מעל המזבח \u0003קודם חצות, והחזירן אחר חצות,\u0004 כך שבחצות לא נשלם עיכולם — מתי ייחשבו כמעוכלים, ואם יפקעו שוב לא יהא צורך להחזירם? \u0003רבה אמר:\u0004"],["\u0003חצות שני\u0004 של הלילה הבא \u0003עוכלתן\u0004 (מחשיב אותם כמעוכלים). \u0003רב חסדא אמר: עמוד השחר\u0004 של הלילה הראשון \u0003עוכלתן,\u0004 ואם יפקעו אין צריך עוד להחזירם.","\u0003אמרי בי\u0004 \u0005[אמרו\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב חסדא\u0004 שעמוד השחר מטיל עליהם דין עיכול? נלמד הדבר בקל וחומר: \u0003ומה חצות שאין עושה לינה\u0004 שאם היו האיברים מחוץ למזבח בחצות לילה, אין הדבר נחשב להם כלינה הפוסלת אותם, בכל זאת \u0003עושה עיכול,\u0004 שהרי אחר חצות הם נחשבים כמעוכלים. \u0003עמוד השחר שעושה לינה,\u0004 שאם היו מחוץ למזבח הרי הם נפסלים משום נותר, \u0003אינו דין שעושה עיכול?\u0004","ועוד נחלקו חכמים אלה בבעיה אחרת: \u0003פירשו\u0004 האיברים \u0003קודם חצות והחזירן לאחר עמוד השחר, רבה אמר: חצות\u0004 של לילה \u0003שני עוכלתן\u0004 (כשיטתו בשאלה הקודמת), ואם פקעו לאחר מכן לא יחזירם, \u0003רב חסדא אמר:\u0004 מאחר ולא היו על המזבח בעלות השחר \u0003אין בהן\u0004 תורת \u0003עיכול לעולם,\u0004 וישוב ויחזירם למזבח עד שייעשו דשן ממש. משתי המחלוקות שבין רבה ורב חסדא עולה כי מוסכם על שניהם שאם לא היו האיברים על המזבח בחצות אין הם נחשבים כמעוכלים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: ומאן לימא לן\u0004 \u0005[ומי יאמר לנו]\u0006 ש\u0003חצות\u0004 דווקא בהיותם \u0003בראש המזבח משויא להו עיכול\u0004 \u0005[עושה בהם,\u0006 מחיל עליהם, דין \u0005עיכול]?\u0006 \u0003דילמא כל היכא דמשכחא להו משויא להו עיכול\u0004 \u0005[שמא כל מקום שמוצא אותם\u0006 זמן חצות \u0005עושה בהם עיכול]!\u0006 ומעירים, \u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]:\u0006 \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב יוסף\u0004 שאם עבר חצות נחשבים האיברים כמעוכלים בכל מקום שהם נמצאים בו, ולאו דווקא על המזבח.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 ש\u0003אמר ר' חייא בר אבא: פירשו\u0004 איברים מן המזבח \u0003קודם חצות והחזירן אחר חצות\u0004 — אמנם \u0003לא נהנין\u0004 מהם, \u0003ו\u0004אולם גם \u0003לא מועלין\u0004 בהם, מאחר וכבר נעשתה מצוותם, שחצות עשה בהם עיכול. \u0003וכן תנא\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: פירשו קודם חצות והחזירן לאחר חצות\u0004 — \u0003יוצאין מידי מעילה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: וכי מאחר\u0004 ש\u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]\u0006 \u0003הילכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב יוסף,\u0004 שחצות עושה עיכול גם מחוץ למזבח, \u0003ו\u0004כן \u0003אמר ר' חייא בר אבא, וכן תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא\u0004 כדבריו, אם כן \u0003רבה ורב חסדא במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ב\u0004איברים \u0003שמנים,\u0004 שכיון שיש בהם שומן הרי הוא מעכב את התעכלותם, ובאלו אין חצות עושה עיכול.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרבה:\u0004 האם \u0003לינה מועלת\u0004 (מועילה) לפסול את האיברים כאשר הם נמצאים \u0003בראשו של מזבח\u0004 בעלות השחר, שלא על גבי המוקד, \u0003או אינה מועלת בראשו של מזבח,\u0004 ולא נפסלו עם השחר? ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה שעדיין \u0003לא ירדו\u0004 מן המזבח, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אפילו אם \u0003לנו בעזרה אמרת\u0004 \u0005[אומר אתה]\u0006 שאם עלו \u0003לא ירדו,\u0004 כפי ששנינו במשנה (פד,א), אם נשארו \u0003בראשו של מזבח מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שלא ירדו?","\u0003ואלא\u0004 השאלה עוסקת במקרה שלנו בראש המזבח, ו\u0003ירדו\u0004 מעל המזבח, ומעתה יש לשאול האם נפסלו בלינה בראש המזבח, ולכן אם ירדו שוב לא יעלו, או שמא כשרים הם ויעלו. וצדדי השאלה: האם לינה בראש המזבח \u0003לשלחן\u0004 של לחם הפנים \u0003מדמינן לה\u0004 \u0005[אנו מדמים,\u0006 משווים \u0005אותה],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 חלות של לחם הפנים, שצריך ליטול אותן בכל שבת ולהביא חלות חדשות, \u0003אפילו הן\u0004 נשארות \u0003על השלחן ימים רבים\u0004 לאחר הזמן הראוי — \u0003אין בכך כלום\u0004 ולא נפסלו בלינה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003ל\u0004לינה על \u0003קרקע\u0004 העזרה \u0003מדמינן\u0004 \u0005[אנו מדמים,\u0006 משווים\u0005],\u0006 שבשר הלן על רצפת העזרה נפסל בעלות השחר?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין לינה בראשו של מזבח,\u0004 ואינם נפסלים שם. ושואלים: האם \u0003קיבלה מיניה\u0004 \u0005[קיבל\u0006 רבא הלכה זו \u0005ממנו,\u0006 מרבה\u0005]\u0006 והסכים לה, \u0003או לא?\u0004 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה הבאה: \u0003איברים שלנו בעזרה\u0004 — מעלה אותם למזבח ו\u0003מקטר והולך כל הלילה\u0004 עד עלות השחר, ולא יותר מכך. \u0003לן\u0004 איבר \u0003בראשו של מזבח\u0004 — \u0003מקטר והולך לעולם\u0004 עד שיישרפו.","\u0003ירדו\u0004 האיברים הללו שלנו בראש המזבח מעל המזבח, \u0003רבה אמר: יעלו, רבא אמר: לא יעלו\u0004 עוד. \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003לא קיבלה\u0004 רבא \u0003מיניה\u0004 \u0005[ממנו],\u0006 אלא הוא סבור שיש פסול לינה בראש המזבח. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003כשם שהמזבח מקדש\u0004 כך הכבש וכלי שרת מקדשים. ובענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"הנגע במזבח\u0004 יקדש\" (שמות כט, לז) — \u0003אין לי אלא מזבח, כבש מנין? תלמוד לומר\u0004 \"ומשחת \u0003את המזבח\"\u0004 (שמות ל, כו), \"את\" לרבות הכבש. \u0003כלי שרת מניין? תלמוד לומר\u0004 בכלי הקודש כולם: \u0003\"כל הנגע בהם יקדש\"\u0004 (שמות ל, כט).","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ריש לקיש מר' יוחנן: כלי שרת מהו שיקדשו את הפסולין? אמר ליה\u0004 \u0005[לו],\u0006 \u0003תניתוה\u0004 \u0005[\u0006הרי כבר \u0005שניתם אותה]\u0006 במשנתנו: \u0003כשם שהמזבח והכבש מקדשין את הראוי להן\u0004 למרות שהוא פסול, \u0003כך כלים מקדשין!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: ממשנתנו יש ללמוד שכלי שרת מקדשים את מה שניתן בהם, לענין ששוב לא ניתן לפדותו, גם אם נפסל. ואילו אני, לגבי השאלה האם הם מקדשים \u0003לכתחילה ליקרב קמיבעי\u0004 \u0005[נשאלה]\u0006 \u0003לי.\u0004 אמר לו ר' יוחנן: \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו],\u0006 בכלל קרבנות פסולים שאם עלו לא ירדו:"],["קרבן \u0003שקיבלו פסולין וזרקו את דמו,\u0004 \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 כוונת הדברים \u0003שקיבלו פסולין\u0004 את הדם, \u0003ו\u0004גם \u0003זרקו פסולין,\u0004 שרק אז נפסל הקרבן ואין להעלותו על המזבח. אבל אם רק קיבלו פסולים את הדם, למרות שהוא נפסל בכך — רשאים כשרים לכתחילה לזורקו, ולהעלות את הקרבן. ומכאן שכלי השרת מקדשים את הדם הפסול לזורקו אפילו לכתחילה!","דחה ריש לקיש: \u0003לא,\u0004 אפשר להסביר את המשנה כשני מקרים שונים: \u0003שקיבלו פסולין\u0004 את דמו, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003שזרקו פסולין\u0004 למרות שקיבלוהו כשרים, ובשני המקרים אין זה אלא בדיעבד, לפי שכלי השרת אינם מקדשים להקריב או לזרוק לכתחילה.","ומביאים דיון, שהובאה בו משנתנו כראיה. וכך נשאלה השאלה: \u0003אויר\u0004 שלמעלה מן ה\u0003מזבח כמזבח דמי\u0004 \u0005[נחשב],\u0006 שכאשר נכנס דבר פסול לאויר המזבח אינו יורד, \u0003או לא?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממשנתנו: \u0003כשם שהמזבח מקדש\u0004 את הפסולים, \u0003כך כבש מקדש,\u0004 שאם עלו עליו — לא ירדו, אלא יקרבו על גבי המזבח.","\u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 \u0003אויר מזבח לאו\u0004 \u0005[לא]\u0006 \u0003כמזבח דמי\u0004 \u0005[נחשב]\u0006 — \u0003אויר כבש נמי\u0004 \u0005[גם כן]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ככבש דמי\u0004 \u0005[נחשב],\u0006 ואם כן, \u0003היכי מסיק ליה\u0004 \u0005[כיצד מעלה אותו]\u0006 את איברי הקרבן הפסול \u0003מכבש למזבח?\u0004 הלוא כאשר מרים את האיבר מן הכבש להעלותו \u0003הוה ליה\u0004 \u0005[נעשה]\u0006 \u0003ירוד,\u0004 כאילו ירד מן הכבש, וכל הפסולים שירדו שוב אינם עולים!","ומשיבים: כאן מדובר \u0003דנגד ליה\u0004 \u0005[שמושך אותו]\u0006 על גבי הכבש, ואינו מגביהו, ונמצא שלא היה באויר הכבש כלל. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 גם אם גוררו על גבי הכבש, עדיין \u0003אויר\u0004 (רווח) \u0003יש בין כבש למזבח,\u0004 וכשהוא שם הריהו ירוד! ומשיבים: הואיל ואויר זה מועט הוא, רק מיעוט איבר הקרבן נמצא מעליו, ולכן כאשר \u0003רובו\u0004 של האיבר \u0003לכבש\u0004 (על הכבש), המיעוט שבאויר נידון \u0003כ\u0004מונח על ה\u0003כבש,\u0004 ואם הגיע \u0003רובו למזבח\u0004 נידון אותו מיעוט שבאויר \u0003כ\u0004מונח על ה\u0003מזבח.\u0004","ושואלים: אם כן, \u0003תיפשוט מהא הא דבעי\u0004 \u0005[תפתור מכאן\u0006 שאלה \u0005זו ששאל]\u0006 \u0003רמי בר חמא:\u0004 האם \u0003יש חיבור לעולין\u0004 שהקרבן נחשב כיחידה אחת, וגם מה שאינו נמצא על המזבח נחשב כמצוי עליו, \u0003או לא,\u0004 ודנים כל חלק לעצמו? \u0003תיפשוט\u0004 \u0005[תפתור]\u0006 ממה שאמרנו ש\u0003יש חיבור!\u0004 ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 ואכן, \u0003תיפשוט\u0004 \u0005[תפתור]\u0006 בכך את השאלה.","ועל מה שרצו להוכיח מתחילה, שאויר המזבח נחשב כמזבח, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא בר רב חנן: ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 כי \u0003אויר מזבח כמזבח דמי\u0004 \u0005[נחשב],\u0006 \u0003עולת העוף\u0004 שמליקתה נעשית באויר המזבח, \u0003דפסלה\u0004 \u0005[שנפסלת]\u0006 \u0003במחשבה\u0004 להקטירה למחר, \u0003היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]?\u0006","הרי אין מחשבת חוץ לזמנו פוסלת אלא אם חשב להקטיר בזמן שאינו רשאי להקטיר, ואילו עולת העוף \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003קלטה מזבח.\u0004 וגם אם ימתין עד למחר יקטירו אותה, כדין כל קרבן שנפסל בלינה, שאם עלה לא ירד!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על קושיה זו \u0003רב שימי בר אשי: אלמה\u0004 \u0005[למה]\u0006 \u0003לא\u0004 יהא פסול מחשבה בעולת העוף? \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003כגון\u0004 ש\u0003אמר: \"הריני מולקה על מנת להורידה למחר ולהעלותה ולהקטירה\".\u0004 ואם אכן היה מורידה למחר — שוב לא ניתן להעלותה ולהקטירה, שהרי פסולים שירדו שוב לא יעלו, ולפיכך אף מחשבתו על כך פוסלת את הקרבן!","על קושייתו של רב שימי שואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר: לינה מועלת\u0004 (מועילה) לפסול את הקרבן גם כשהוא \u0003בראש המזבח,\u0004 ולפיכך אם היה מוריד את העולה למחר שוב לא ניתן היה להקטירה, \u0003אלא ל\u0004שיטת \u0003רבה\u0004 ש\u0003אמר: אין לינה מועלת בראש המזבח,\u0004 הרי גם אם היה מורידה למחר, צריך היה לחזור ולהקטירה. ואם כן \u0003ליתא\u0004 \u0005[אינה]\u0006 \u0003למחשבתו\u0004 כלומר, אין זו מחשבת פסול!","משיב לכך רב שימי בר אשי: \u0003לרבה נמי\u0004 \u0005[גם כן]\u0006 \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה],\u0006 \u0003כגון\u0004 ש\u0003אמר: הריני מולקה על מנת להורידה קודם עמוד השחר ולהעלותה לאחר עמוד השחר,\u0004 שהואיל ובעמוד השחר לא היתה על המזבח, בזה אף רבה מודה שנפסלת בלינה.","ומוסיף רב שימי: גם אם יש מקום לדון בגוף ההוכחה של רבא בר רב חנן, \u0003להך גיסא מיהא תיפשוט\u0004 \u0005[לצד זה על כל פנים תפתור]\u0006 להיפך, ש\u0003אויר מזבח כמזבח דמי\u0004 \u0005[נחשב]:\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 כי \u0003אויר מזבח לאו\u0004 \u0005[לא]\u0006 \u0003כמזבח דמי\u0004 \u0005[נחשב],\u0006"],["\u0003חטאת העוף פסולה,\u0004 אם מלקה בראש המזבח \u0003היכי\u0004 \u0005[כיצד]\u0006 \u0003מזה מדמה\u0004 על קיר המזבח? הרי כשמגביה בידו את העוף לשם כך \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 נעשה \u0003ירוד\u0004 ושוב אינו יכול להזותו, כדין פסולים שאם ירדו שוב לא יעלו! וכן \u0003שאר\u0004 דמי קרבנות \u0003פסולים\u0004 שעלו למזבח \u0003היכי זריק להו\u0004 \u0005[כיצד זורק]\u0006 \u0003מדמה\u0004 כאשר בשעת הזריקה הוא באויר המזבח? אלא ודאי אויר מזבח נחשב כמזבח.","ודוחים: אפשר לומר שאינו זורק את הדם כדרכו, אלא \u0003דמגע להו\u0004 \u0005[שמגיע,\u0006 מצמיד \u0005אותם]\u0006 לקיר המזבח, כך שהדם נוגע מיד במזבח ואינו נמצא באויר. את התירוץ הזה דוחים: וכי שעושה כן בחטאת העוף \u0003הא\u0004 \u0005[זו]\u0006 \u0003הזאה היא?\u0004 \u0003מיצוי היא,\u0004 האמור בעולת העוף, ואין עושים כן בחטאת! וכן בשאר קרבנות פסולים, שעושה כן, \u0003הא\u0004 \u0005[זו]\u0006 \u0003זריקה\u0004 היא? הלוא \u0003שפיכה היא!\u0004","\u0003ועוד,\u0004 וכי \u0003דרך הזאה בכך?\u0004 וכי \u0003דרך זריקה בכך?\u0004 אלא מכאן שאויר המזבח כמזבח הוא נחשב.","\u0003אמר רב אשי: אי דנקט להו\u0004 \u0005[אם\u0006 במקרה \u0005שאוחז אותם\u0006 הכהן\u0005]\u0006 \u0003בראש המזבח,\u0004 את הדם או את האיברים הפסולים, \u0003הכי נמי\u0004 \u0005[אכן כך],\u0006 הרי זה נחשב כאילו הגיעו למזבח עצמו, ושוב לא ירדו. ואולם \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 כאשר נשאלה השאלה הרי זה במקרה \u0003דתלנהו\u0004 \u0005[ש\u0006עומד על רצפת העזרה ו\u0005תולה אותם]\u0006 את האיברים \u0003בקניא\u0004 \u0005[בקנה]\u0006 מעל המזבח. ובזה נשאלה השאלה: \u0003מאי\u0004 \u0005[מה]\u0006 הדין? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ולענין מה ששנינו במשנה הקודמת, שכלי שרת מקדשים את הניתן בתוכם, מוסיפים: \u0003כלי הלח\u0004 המשמשים לנוזלים (כגון דם ויין ושמן) — \u0003מקדשין את הלח\u0004 בלבד, \u0003ומדות יבש\u0004 הכלים המשמשים לדברים יבשים \u0003מקדשות את היבש\u0004 בלבד. אבל \u0003אין כלי הלח מקדשת את היבש, ולא\u0004 כלי ה\u0003יבש מקדש את הלח,\u0004 שלא לצורך זה נעשו. \u0003כלי הקודש שניקבו, אם\u0004 עדיין \u0003עושין בהן מעין מלאכתן שהיו עושין\u0004 כאשר \u0003הן שלימים\u0004 — \u0003מקדשין, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מקדשין. וכולן\u0004 כל המידות הללו \u0003אין מקדשין אלא\u0004 בהיותם \u0003בקודש\u0004 בעזרה, ולא מחוצה לו.","על דברי המשנה שכלי הלח אינם מקדשים את היבש, \u0003אמר שמואל: לא שנו אלא מדות\u0004 של לח, שמודדים בהם את היין והשמן, \u0003אבל מזרקות\u0004 שמקבלים בהם את דם הקדשים \u0003מקדשין\u0004 גם את היבש, \u0003שנאמר:\u0004 \"מזרק אחד כסף... \u0003שניהם מלאים סלת\"\u0004 (במדבר ז, יג), הרי שנעשים גם לצורך סולת שהיא יבשה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא:\u0004 הלוא \u0003מנחה לחה היא\u0004 כיון שהיא בלולה בשמן (במדבר ז, יג), ואין מכאן ראייה לדבר שהוא יבש לגמרי, כגון סולת! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא נצרכה\u0004 הוכחה זו שאמר שמואל \u0003אלא ליבש שבה,\u0004 שהרי גם אם נבללה בשמן יש בה חלקים שנשארו יבשים. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: \u0003מנחה\u0004 אף שהיא בלולה בשמן \u0003לגבי דם כיבש דמי\u0004 \u0005[נחשבת],\u0006 ומכאן יש ללמוד לכל דבר יבש.","ועוד \u0003אמר שמואל: כלי שרת אין מקדשין אלא\u0004 כשהם \u0003שלימין\u0004 ולא נקובים, \u0003אין מקדשין אלא מלאין\u0004 כשיש בהם שיעור הראוי להקרבה, \u0003אין מקדשין אלא מתוכן,\u0004 ולא מה שנגע בחלק החיצון של הכלי. \u0003ואמרי לה\u0004 \u0005[ויש אומרים אותה]\u0006 בלשון אחרת: \u0003אין מקדשין אלא שלימין, ומלאים, ומבפנים\u0004 כלומר, כשהם מצויים בעזרה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין שתי הלשונות הללו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין \u0003בירוצי מדות\u0004 מה שעולה וגודש מעל גובה שפתו של הכלי, שלפי הלשון \"מתוכן\" משמע שמה שאינו בתוך הכלי ממש — אינו מתקדש. ומעירים: \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 כשתי הלשונות: \u0003אין מקדשין אלא שלימין ומלאים ומתוכן ובפנים.\u0004","ולענין שאין מקדשים אלא מלאים, \u0003אמר ר' אסי אמר ר' יוחנן: לא שנו אלא שאין דעתו\u0004 מתחילה \u0003להוסיף\u0004 על מה שהכניס לכלי, \u0003אבל\u0004 אם היתה \u0003דעתו להוסיף\u0004 — \u0003ראשון ראשון קודש,\u0004 אפילו בכמות קטנה.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מלאין\u0004 — \u0003אין מלאין אלא שלימין. אמר ר' יוסי: אימתי? בזמן שאין דעתו להוסיף, אבל דעתו להוסיף\u0004 — \u0003ראשון ראשון קודש.\u0004","שנינו במשנה: \u0003אין כלי הלח מקדש\u0004 את היבש. \u0003אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב אסי: אין מקדשין\u0004 כדי להכשיר את מה שבתוכם \u0003ליקרב\u0004 למזבח, \u0003אבל מקדשין ליפסל\u0004 שנפסלים בדברים הפוסלים את הקדשים, כגון שנגע בהם טבול יום, שאינו פוסל במגעו אלא קדשים, או שיצאו חוץ לעזרה.","\u0003איכא דמתני לה אהא\u0004 \u0005[יש ששונים אותה\u0006 את המימרה הזו \u0005על\u0006 הלכה \u0005זו]:\u0006 \u0003אין מביאין מנחות ונסכים ומנחת בהמה וביכורים מן המדומע\u0004 (ממה שנתערב בו מקצת תרומה). שכל שאינו כשר לאכילה לכל ישראל, אלא רק לכהנים — אין מביאים אותו כקרבן. \u0003ואין צריך לומר\u0004 שאין מביאים מנחות ונסכים \u0003מערלה וכלאי הכרם,\u0004 שאסורים גם לכהנים. \u0003ואם הביא\u0004 — \u0003לא קדש.\u0004 ועל כך \u0003אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב אסי: לא קדש ליקרב, אבל קדש\u0004 כדי \u0003ליפסל.\u0004","כיון שנזכרו במשנה כלים שניקבו, מביאים בענין זה: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כלי קדש שניקבו\u0004 — \u0003אין מתיכין אותן\u0004 במקום הנקב כדי לסתום אותו, \u0003ואין מתיכין לתוכן אבר\u0004 (עופרת) לצורך זה. \u0003נפגמו\u0004 הכלים בשפתם — \u0003אין מתקנין אותן. סכין שנפגם\u0004 — \u0003אין משחיזין את פגימתה, נשמטה\u0004 מן הקת — \u0003אין מחזירין אותה.\u0004 \u0003אבא שאול אומר: סכין מטרפת היתה במקדש,\u0004 שהיתה נפגמת בקלות, ופעמים רבות עשתה את הבהמה טריפה, \u0003ונמנו\u0004 (עשו הצבעה) \u0003עליה כהנים וגנזוה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בגדי כהונה אין עושין אותם מעשה מחט, כדרך שתופרים בגד העשוי מחתיכות שונות, \u0003אלא מעשה אורג\u0004 באריגה שלימה אחת, \u0003שנאמר\u0004 בהם: \u0003\"מעשה ארג\"\u0004 (שמות כ״ח:ל״ב). \u0003נתגעלו\u0004 (נתלכלכו), \u0003אין מכבסין\u0004 אותם \u0003לא בנתר ולא באהל\u0004 המשמשים כחומרי כיבוס.","ושואלים בתמיהה: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003במים מכבסין\u0004 אותם? \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003הוגעו במים\u0004 אם נתלכלכו באופן שדי להם במים בלבד כדי לנקותם — \u0003מכבסין אותו בנתר ואהל,\u0004"],["התלכלכו כל כך עד ש\u0003הוגעו\u0004 נצרכו \u0003לנתר ואהל\u0004 כדי לכבסם — \u0003אף במים אין מכבסים\u0004 אותם. \u0003ויש אומרים:\u0004 בגדי כהונה \u0003אין מכבסין אותן כל עיקר,\u0004 גם אם נתלכלכו לכלוך קל, משום \u0003שאין עניות במקום עשירות.\u0004 ועוד בענין בגדי כהונה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעיל\u0004 של כהן גדול \u0003כולו של תכלת היה, שנאמר: \"ויעש את מעיל האפוד\u0004 מעשה אורג \u0003כליל תכלת\"\u0004 (שמות לט, כב), ללמדנו שכולו (\"כליל\") נעשה מתכלת. \u0003שוליו\u0004 של המעיל שנאמר בהם: \"ויעשו על שולי המעיל רמוני תכלת וארגמן ותולעת שני משזר\" (שמות לט, כד), \u0003כיצד\u0004 הם נעשים? \u0003מביא תכלת וארגמן ותולעת שני שזורין\u0004 יחד, \u0003ועושה אותן כמין רימונים שלא פיתחו\u0004 עדיין \u0003פיהן\u0004 (שלא נפתח ה\"כתר\" שבראש הרימון), \u0003וכמין קונאות\u0004 (מעין צורת חרוט) \u0003של קנסות\u0004 (כובעים) \u0003שבראשי תינוקות. ו\u0004כדי לקיים מה שנאמר \"ויעשו פעמוני זהב טהור ויתנו את הפעמונים בתוך הרימונים\" (שמות לט, כה), \u0003מביא שבעים ושנים זגין\u0004 (חלקו החיצון של הפעמון) עשויים מזהב \u0003שבהן\u0004 תלויים \u0003שבעים ושנים עינבלין\u0004 (לשון המתכת המקישה בזוג), \u0003ותולה בהן\u0004 בשולי המעיל \u0003שלשים וששה\u0004 רימונים ופעמונים \u0003בצד זה\u0004 של המעיל, \u0003ושלשים וששה מצד זה,\u0004 שנאמר \"פעמון ורמון פעמון ורמון על שולי המעיל סביב\" (שמות לט, כו). \u0003ר' דוסא אומר משום\u0004 (בשם) \u0003ר' יהודה:\u0004 סך הכל \u0003שלשים וששה\u0004 פעמונים \u0003היו,\u0004 \u0003שמונה עשרה מצד זה ושמנה עשרה מצד זה.\u0004 \u0003אמר ר' עיניני בר ששון: כמחלוקת\u0004 התנאים \u0003כאן\u0004 לענין מספר הפעמונים שבמעיל הכהן הגדול, \u0003כך מחלוקת\u0004 תנאים \u0003ב\u0004מספר \u0003מראות נגעים, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 כמה \u0003מראות נגעים\u0004 הם — \u0003ר' דוסא בן הרכינס אומר: שלשים וששה, עקביא בן מהללאל אומר: שבעים ושנים.\u0004 מתוך שהוזכרו דבריו של חכם זה, מביאים עוד מדבריו. \u0003ואמר ר' עיניני בר ששון: למה נסמכה\u0004 בתורה \u0003פרשת קרבנות\u0004 (ויקרא פרקים א—ז) \u0003לפרשת בגדי כהונה\u0004 (ויקרא פרק ח)? \u0003לומר לך: מה קרבנות מכפרין\u0004 — \u0003אף בגדי כהונה מכפרין.\u0004","","","","","והוא מפרט: \u0003כתונת\u0004 — \u0003מכפרת על שפיכות דם, ש\u0004כן \u0003נאמר\u0004 באחי יוסף לאחר שביקשו להמיתו: \u0003\"וישחטו שעיר עזים ויטבלו את הכתנת בדם\"\u0004 (בראשית לז, לא). \u0003מכנסים\u0004 — \u0003מכפרת על גילוי עריות, ש\u0004כן \u0003נאמר\u0004 בציווי על עשיית בגדי הכהנים: \u0003\"ועשה להם מכנסי בד [לכסות (את) בשר ערוה]\"\u0004 (שמות כח, מב). \u0003מצנפת\u0004 — \u0003מכפרת על גסי הרוח. מנין? אמר ר' חנינא: יבא דבר שבגובה,\u0004 שעל הראש, \u0003ויכפר על\u0004 חטא של \u0003גובה\u0004 הלב.","\u0003אבנט\u0004 — \u0003מכפר על הרהור הלב,\u0004 ומסבירים: מכפר הוא \u0003היכא דאיתיה\u0004 \u0005[במקום שישנו],\u0006 כי האבנט היה במקום הלב. \u0003חושן\u0004 של הכהן הגדול — \u0003מכפר על הדינין\u0004 שנעשה בהם עוול, \u0003שנאמר: \"ועשית חשן משפט\"\u0004 (שמות כח, טו). \u0003אפוד\u0004 של הכהן הגדול — \u0003מכפר על עבודה זרה, שנאמר: \"אין אפוד ותרפים\"\u0004 (הושע ג, ד), כלומר, כשאין אפוד נמצא עוון תרפים של עבודה זרה, ומכאן כי כשיש אפוד — אין חטא של עבודה זרה (תרפים).","\u0003מעיל\u0004 של הכהן הגדול — \u0003מכפר על לשון הרע. מנין? אמר ר' חנינא: יבא דבר שבקול\u0004 (פעמוני המעיל) \u0003ויכפר על קול הרע. וציץ\u0004 של הכהן הגדול — \u0003מכפר על עזות פנים, בציץ כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והיה על מצח אהרן\"\u0004 (שמות כח, לח), \u0003ובעזות פנים כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ומצח אשה זונה היה לך\"\u0004 (ירמיהו ג, ג).","ומקשים: \u0003איני\u0004 \u0005[וכן הוא]?\u0006 וכי בגדי כהונה מכפרים על עבירות אלו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהושע בן לוי: שני דברים לא מצינו\u0004 (מצאנו) \u0003להן כפרה בקרבנות, ומצינו לו כפרה ממקום אחר, ואלו הן: שפיכות דמים ולשון הרע,\u0004 \u0003שפיכות דמים\u0004 — כפרתה באה \u0003מעגלה ערופה, ולשון הרע\u0004 — \u0003מקטרת, דתני\u0004 \u0005[ש\u0006כך \u0005שנה]\u0006 \u0003רב חנניה\u0004 ברייתא: \u0003מנין לקטרת שמכפרת? שנאמר\u0004 לאחר שדיברו העם סרה במשה ואהרון ופרצה המגיפה: \u0003\"ויתן את הקטרת ויכפר על העם\"\u0004 (במדבר יז, יב),","","\u0003ותני דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: על מה קטורת מכפרת? על לשון הרע, יבא דבר שבחשאי\u0004 הקטורת שהכהן הגדול מקטיר בקודש הקדשים כשהוא לבדו, \u0003ויכפר על מעשה חשאי\u0004 לשון הרע, שנאמר לרוב בחשאי.","ולפי זה \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לשון הרע\u0004 על \u0003לשון הרע,\u0004 שלדברי ר' עיניני בר ששון כפרתו במעיל, ולדברי הברייתא אין לו כפרה אלא בקטורת. וכמו כן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003שפיכות דמים\u0004 על \u0003שפיכות דמים,\u0004 שלדברי ר' עיניני בר ששון כפרתה בכתונת, ולדברי הברייתא אין לה כפרה אלא בעגלה ערופה!","ומתרצים: לגבי שפיכות דמים \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שכתונת מכפרת שפיכות דמים, הרי זה במקרה \u0003דידיע מאן קטליה\u0004 \u0005[שידוע מי הרגו],\u0006 והכתונת מכפרת על הציבור שלא ייענש. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שעגלה ערופה מכפרת, הרי זה במקרה ש\u0003לא ידיע מאן קטליה\u0004 \u0005[ידוע מי הרגו],\u0006 ובאה עגלה ערופה לכפר על הציבור. ושואלים על כך: \u0003אי דידיע מאן קטליה\u0004 \u0005[אם ידוע מי הרגו]\u0006 — \u0003בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא,\u0004 ואין כפרה לציבור עד שייענש במיתה, שנאמר: \"ולארץ לא יכופר לדם אשר שופך בה כי אם בדם שופכו\" (במדבר לה, לג)! ומשיבים: פעמים שאי אפשר להורגו, כגון שהרג \u0003במזיד ולא אתרו ביה\u0004 \u0005[התרו בו]\u0006 קודם, שאין בית דין יכולים לענשו בלא התראה. ומוסיפים: \u0003ו\u0004כן לענין הסתירה בין כפרת \u0003לשון הרע\u0004 על כפרת \u0003לשון הרע נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 קטורת שבחשאי, מכפרת על לשון הרע ש\u0003בצינעא, הא\u0004 \u0005[זה]\u0006 מעיל שמשמיע קול, מכפר כשדיבר \u0003בפרהסיא\u0004","",""],["\u0003כל\u0004 קרבן \u0003התדיר\u0004 (נוהג לעתים תכופות) יותר \u0003מחבירו\u0004 — \u0003קודם את חבירו\u0004 בהקרבה. ומשום כך קרבנות \u0003התמידין\u0004 הקרבים בכל יום \u0003קודמין ל\u0004קרבנות ה\u0003מוספין\u0004 הבאים רק בימים מיוחדים. \u0003מוספי שבת קודמין למוספי ראש חדש\u0004 כשחל ראש חודש בשבת, כיון שהם תדירים מהם. וכן בראש חודש תשרי שהוא גם ראש השנה, \u0003מוספי ראש חדש קודמין למוספי ראש השנה.\u0004 וכלל זה, שהתדיר קודם נלמד ממה \u0003שנאמר\u0004 במוספי היום הראשון של פסח: \u0003\"מלבד עלת הבקר אשר לעלת התמיד תעשו את אלה\"\u0004 (במדבר כח, כג), הרי שתחילה מקריבים את עולת התמיד, ואחר כך אלה, קרבנות המוספים.","על דברי המשנה שכל קרבן התדיר יותר מחבירו, קודם לו בהקרבתו, שואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 הלכה זו? ותוהים על עצם השאלה: \u0003מנא לן\u0004 \u0005[מנין לנו]?!\u0006 \u0003כדקאמר טעמא\u0004 \u0005[כמו שאומר\u0006 התנא בעצמו במשנה את \u0005הטעם]:\u0006 שנאמר \u0003\"מלבד עלת הבקר\"!\u0004 ומסבירים את השאלה: אם מכתוב זה בלבד, \u0003דילמא\u0004 \u0005[שמא]\u0006 דווקא קרבנות \u0003תמידין הן דקדמו\u0004 \u0005[שקודמים]\u0006 \u0003למוספין משום דתדירי\u0004 \u0005[ש\u0006הם \u0005תדירים]\u0006 כשלעצמם, שהרי כל יום ויום הם מוקרבים, אבל \u0003מוספין\u0004 \u0003למוספין\u0004 אחרים התדירים פחות מהם, \u0003מנא לן\u0004 \u0005[מנין לנו]?\u0006","\u0003אמר ר' אילעא\u0004 בתשובה לשאלה זו: לאחר הפסוק \"מלבד עולת הבקר אשר לעולת התמיד תעשו את אלה\" (במדבר כח, כג) האמור במוספי היום הראשון של פסח, \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"כאלה תעשו ליום שבעת ימים\"\u0004 (במדבר כח, כד), ללמדנו שיהיה דינם של \u0003אלה\u0004 המוספים הנזכרים בפסוק השני \u0003כ\u0004דינם של \u0003אלה,\u0004 התמיד והמוספים שנזכרו בפסוק הראשון, שהתדיר קודם לפחות תדיר ממנו.","ומקשים על לימוד זה: \u0003והאי מיבעי ליה לגופיה\u0004 \u0005[והרי \u0006כתוב זה \u0005נצרך לו לגופו]\u0006, ללמד שכמו שעושים ביום הראשון של פסח, כך עושים בכל שבעת ימי החג! ומשיבים: \u0003אם כן,\u0004 רק ללמד דבר זה, \u0003ניכתוב\u0004 \u0005[שיכתוב]:\u0006 \u0003\"אלה תעשו ליום\u0004 שבעת ימים\" בלבד, ואין צורך ב\"כאלה\".","ודוחים: \u0003אי כתב\u0004 \u0005[אם היה כותב]\u0006 \u0003\"אלה תעשו ליום שבעת הימים\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אלה לשבעת הימים (\u0004— \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא)\u0004 כלומר, שבכל שבעת הימים יחד יקריבו את הקרבנות האמורים בפסוק הראשון. לכן הוצרך \"כאלה\", ואין הוא מיותר! ומשיבים: לא ניתן לומר כן, שהרי \u0003\"ליום\" כתיב\u0004 \u0005[נאמר],\u0006 ומשמע לכל יום משבעת הימים.","ומקשים: \u0003ואכתי אימא\u0004 \u0005[ועדיין אמור]:\u0006 אילו היה כתוב \"אלה\" הייתי אומר: \u0003אלה ליום\u0004 הראשון, \u0003אבל שאר יומי לא ידענא\u0004 \u0005[הימים איני יודע]\u0006 \u0003כמה,\u0004 ולכך הוצרך \"כאלה\"! ומשיבים: לא ניתן לומר כן, שהרי \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"תעשו\"\u0004 — \u0003שיהו כל העשיות\u0004 בכל הימים הנזכרים שם \u0003שוות,\u0004 ומ\"כאלה\" למדנו איפוא לדין קדימה.","\u0003אביי אמר\u0004 מקור אחר לכלל שהתדיר קודם בכל הקרבנות, והוא \u0003מגופה דקרא\u0004 \u0005[מגופו של הכתוב]\u0006 שהביאה המשנה: \u0003אם כן,\u0004 שרק קרבן תמיד קודם למה שתדיר פחות ממנו, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"מלבד עלת הבקר\" ותישתוק\u0004 \u0005[ושישתוק],\u0006 \u0003\"אשר לעלת התמיד\" למה לי? למימר\u0004 \u0005[לומר\u0006 ללמד\u0005],\u0006 \u0003דהך דתדירא תיקדום\u0004 \u0005[שזו\u0006 העולה \u0005שתדירה\u0006 יותר \u0005תקדום]\u0006 לעולות האחרות, שאינן \"תמיד\" כמותה.","ועוד כלל בדיני קדימות של קרבנות: \u0003כל המקודש\u0004 יותר \u0003מחבירו\u0004 — \u0003קודם את חבירו.\u0004 ומפרטים: דם חטאת ודם עולה העומדים לזריקה על המזבח — \u0003דם החטאת קודם לדם העולה, מפני שהוא מרצה\u0004 (מכפר) על עבירות חמורות שיש בהן עונש כרת. איברי עולה ואימורי חטאת העומדים להקטרה על גבי המזבח — \u0003איברי עולה קודמין לאימורי חטאת, מפני שהוא\u0004 (קרבן העולה) \u0003כליל לאישים\u0004 (מוקרב כולו על אש המזבח), ואילו מן החטאת מקריבים רק אימורים בלבד.","חטאת ואשם — \u0003חטאת קודמת לאשם,\u0004 למרות ששניהם מרצים, \u0003מפני שדמה ניתן לארבע קרנות\u0004 המזבח, וכן שיירי דמה ניתנים \u0003על היסוד,\u0004 ואילו דם האשם ניתן רק על שתי קרנות. \u0003אשם קודם לתודה ו\u0004ל\u0003איל נזיר, מפני שהוא קדשי קדשים,\u0004 ותודה ואיל נזיר הריהם קדשים קלים. \u0003תודה ואיל נזיר קודמים לשלמים, מפני שהן נאכלין\u0004 רק \u0003ליום אחד\u0004 כקדשי קדשים, ואילו שלמים נאכלים לשני ימים. \u0003ו\u0004כן תודה ואיל נזיר \u0003טעונין\u0004 (מביאים עימם) \u0003לחם\u0004 (ארבעת מיני לחם בתודה, ושני מיני לחם באיל נזיר), מה שאין כן בשלמים.","היו לפניו שלמים ובכור — \u0003השלמים קודמין לבכור, מפני שהן טעונין מתן ארבע\u0004 (שתי נתינות על המזבח שהן כארבע), \u0003ו\u0004כן הם חייבים ב\u0003סמיכה\u0004 על ראש הקרבן, ולהביא עימם \u0003נסכים\u0004 (מנחת נסכים), \u0003ו\u0004יש בהם גם \u0003תנופות\u0004 (הנפת) \u0003חזה ושוק\u0004 על ידי הכהן והבעלים, מה שאין כן בבכור. בכור ומעשר בהמה — \u0003הבכור קודם למעשר, מפני שקדושתו מרחם\u0004 אמו, ולא על ידי הקדשה כמעשר. \u0003ו\u0004כן יש בו מעלה יתירה ש\u0003נאכל לכהנים,\u0004 מה שאין כן המעשר, שנאכל לבעלים.","מעשר בהמה וקרבנות מן העופות — \u0003המעשר קודם לעופות, מפני שהוא זבח,\u0004 כלומר, מן הבהמה שיש בה זביחה (שחיטה בסכין), בעוד שהעוף נמלק ביד, ובהמה חשובה מן העוף. \u0003ויש בו\u0004 במעשר בהמה שני חלקים שהם \u0003קודש קדשים, דמו\u0004 הנזרק על המזבח, \u0003ו\u0004גם \u0003אימוריו\u0004 הקרבים על המזבח, ואילו בקרבן העוף אין למזבח אלא דמו בלבד. \u0003העופות קודמין למנחות, מפני שהן מיני דמים,\u0004 שמזים מדמם על המזבח, וכפרתו של הדם מרובה. היו לפניו שתי מנחות: האחת מנחה הבאה על חטא (כגון קרבן עני על חטא שבועת העדות וכיוצא בו, ראה ויקרא ה, יא), ומנחה הבאה בנדבה — \u0003מנחת חוטא\u0004 \u0003קודם למנחת נדבה, מפני שהוא בא\u0004 כדי לכפר \u0003על חטא. חטאת העוף קודמת לעולת העוף. וכן בהקדישה\u0004 שכאשר מקדיש זוג עופות (\"קן\") של חטאת ועולה, צריך תחילה לומר איזהו חטאת, ואחר כך איזהו עולה."],["שנינו במשנה שדם קרבן החטאת קודם בזריקתו לדם קרבן העולה, ואולם איברי קרבן העולה קודמים בהקרבתם לאימורי קרבן החטאת, ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כך \u0005שנו חכמים]\u0006 בברייתא: אמר הכתוב בפרשת חינוך הלויים לעבודתם במשכן: \"ולקחו פר בן בקר וכו' \u0003ופר שני בן בקר תקח לחטאת\"\u0004 (במדבר ח, ח). ויש לשאול: מה בא \"שני\" זה ללמדנו?","\u0003אם בא ללמד ש\u0004הקרבנות הבאים לחינוך הלויים \u0003הן שנים\u0004 — לכך אין צורך, ש\u0003הרי כבר נאמר\u0004 בהמשך: \u0003\"ועשה את האחד חטאת ואת האחד עלה\"\u0004 (במדבר ח, יב), ומכאן שהם שני קרבנות. ואם כן \u0003מה תלמוד לומר \"ופר שני בן בקר תקח לחטאת\"? ש\u0004כן אם מ\"ועשה את האחד חטאת והאחד עולה\" \u0003יכול\u0004 הייתי לומר \u0003שיהא חטאת קודמת לכל מעשה עולה,\u0004 לכך \u0003תלמוד לומר: \"ופר שני בן בקר תקח לחטאת\",\u0004 משם למדנו שהחטאת באה שניה, לאחר העולה.","ומעתה יש מקום לשאול: \u0003אי\u0004 מהכתוב \u0003\"פר שני\", יכול\u0004 אתה לומר כי \u0003תהא\u0004 ה\u0003עולה קודמת לחטאת לכל מעשיה?\u0004 לכך \u0003תלמוד לומר: \"ועשה את האחד חטאת ואת האחד עלה\",\u0004 ללמדנו שחטאת קודמת לעולה. \u0003הא כיצד\u0004 ניישב את הסתירה שבין שני הדיוקים הללו? זריקת דם חטאת קודמת לזריקת \u0003דם עולה, מפני ש\u0004דם החטאת \u0003מרצה\u0004 (מכפר), מה שאין כן בעולה. ואילו הקטרת \u0003איברי\u0004 ה\u0003עולה\u0004 קודמת להקטרת אימורי החטאת.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יקדמו כל מתנות דם החטאת למתנות העולה? נאמר שרק \u0003מתנה קמייתא דמכפרה תיקדום\u0004 \u0005[המתנה הראשונה, ש\u0006היא זו \u0005שמכפרת,\u0006 היא \u0005שתקדים]\u0006 לזריקת דם העולה, שהרי אם נתן מתנה אחת כיפר בדיעבד (לעיל זבחים לו,ב), \u0003ו\u0004אילו \u0003הנך\u0004 \u0005[אלה,\u0006 שאר שלוש המתנות הנוספות\u0005]\u0006 — \u0003לא!\u0004","\u0003אמר רבינא: הכא\u0004 \u0005[כאן],\u0006 בפרשה ממנה למדו דין זה, הרי \u0003בחטאת\u0004 של חינוך \u0003הלוים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ואף על גב דכי עולה דמי\u0004 \u0005[ואף על פי שכמו עולה\u0006 היא \u0005נחשבת],\u0006 שהרי היא לא באה ככפרה על חטא כשאר חטאות, מכל מקום \u0003קאמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 ש\u0003היא תיקדים\u0004 \u0005[תקדם]\u0006 לעולה בזריקת דמה, וכל שכן שיהא הדין כן במתנות האחרונות של חטאת רגילה, שבאו לכפר. \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל אומרים]\u0006 תשובה אחרת לשאלה זו: \u0003הואיל והתחיל\u0004 הכהן \u0003במתנות\u0004 של חטאת, הריהו גם \u0003גומר\u0004 בהן.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003דם חטאת ואיברי עולה, איזה מהן קודם?\u0004 וצדדי השאלה: האם נאמר כי \u0003דם חטאת קודם, מפני שמרצה\u0004 (מכפר), ומשום כך הריהו מקודש יותר. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003איברי עולה קודמין, מפני שהן\u0004 עולים \u0003כליל לאישים?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו במשנתנו: \u0003דם חטאת קודם לדם עולה.\u0004 ונדייק מכאן: דווקא \u0003לדם עולה הוא דקדים\u0004 \u0005[שקודם],\u0006 אך \u0003לאיברי עולה לא קדים\u0004 \u0005[אינו קודם].\u0006","ודוחים את ההוכחה: \u0003אדרבה, מסיפא\u0004 \u0005[להיפך,\u0006 נלמד \u0005מ\u0006מה ששנינו ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003איברי עולה קודמין לאימורי חטאת.\u0004 ונדייק: דווקא \u0003לאימורי חטאת הוא דקדים\u0004 \u0005[שקודם],\u0006 \u0003לדם חטאת\u0004 — \u0003לא קדים\u0004 \u0005[אינו קודם]!\u0006 \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מ\u0006משנה \u0005זו אין לשמוע ממנה]\u0006 פתרון לשאלה זו.","ועוד \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003דם עולה ואימורי חטאת, איזה מהן קודם?\u0004 וצדדי השאלה: האם \u0003דם עולה קודם\u0004, משום \u0003דקאתי\u0004 \u0005[שהוא בא]\u0006 \u0003מכח\u0004 קרבן עולה שהוא \u0003כליל. או דילמא\u0004 \u0005[שמא]\u0006 \u0003אימורי חטאת קודמין,\u0004 משום \u0003דקאתי\u0004 \u0005[שהם באים]\u0006 \u0003מכח\u0004 קרבן חטאת שדמו \u0003מכפר?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו במשנתנו: \u0003דם חטאת קודם לדם עולה.\u0004 ונדייק: דווקא \u0003דם חטאת הוא דקדים\u0004 \u0005[שקודם]\u0006 \u0003לדם עולה, אבל אימורי חטאת\u0004 — \u0003לא!\u0004","ודוחים: \u0003אדרבה, מסיפא\u0004 \u0005[להיפך,\u0006 נלמד \u0005מ\u0006מה שנלמד ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003איברי עולה קודמין לאימורי חטאת.\u0004 ונדייק: דווקא \u0003איברי עולה הוא דקדמי\u0004 \u0005[שקודמים]\u0006 \u0003לאימורי חטאת, אבל דם עולה לא! אלא מהא ליכא למשמע מינה\u0004 \u0005[מזו אין ללמוד ממנה].\u0006","ועוד \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 זריקת \u0003דם עולה ו\u0004זריקת \u0003דם אשם, איזה מהן קודם?\u0004 האם \u0003דם עולה קודם\u0004 משום \u0003דקאתי\u0004 \u0005[שהוא בא]\u0006 \u0003מכח\u0004 קרבן שהוא \u0003כליל. או דילמא\u0004 \u0005[שמא]\u0006 \u0003דם אשם קודם,\u0004 משום \u0003(דקאתי\u0004 \u0005[שהוא בא]\u0006 \u0003מכח)\u0004 שהוא \u0003מכפר?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 פתרון לשאלה זו ממה ששנינו במשנתנו: \u0003דם חטאת קודם לדם עולה.\u0004 ונדייק: דווקא דם חטאת קודם לדם עולה, \u0003אבל דם אשם\u0004 — \u0003לא\u0004 קודם לדם עולה!","ודוחים: \u0003בדין הוא דאיבעי למיתני\u0004 \u0005[שהיה צריך לשנות]\u0006 במשנתנו: \u0003דם אשם\u0004 קודם לדם עולה, ומשם היינו למדים כי כל שכן שדם החטאת, שקודם לדם האשם, יקדם לדם העולה. \u0003ו\u0004אולם \u0003איידי דבעא למיתני סיפא\u0004 \u0005[מתוך שרצה\u0006 התנא \u0005לשנות\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003איברי עולה קודמין לאימורי חטאת,\u0004 שבמקרה זה חייב היה התנא להשמיע את דינו דווקא באימורי חטאת, משום","\u0003דאי תנא\u0004 \u0005[שאם\u0006 היה \u0005שונה]\u0006 שאיברי עולה קודמים \u0003לאימורי אשם, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא \u0003לאימורי אשם הוא דקדמי\u0004 \u0005[שקודמים], אבל\u0006 \u0003לאימורי חטאת\u0004 הם \u0003לא קדמי\u0004 \u0005[קודמים],\u0006 שהרי חטאת מקודשת מאשם, \u0003משום הכי תנא\u0004 \u0005[כך שנה]\u0006 גם לגבי דין קדימה בדם את דם ה\u0003חטאת.\u0004 ואין לדייק מכך לענין דם האשם.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו במשנתנו: \u0003חטאת קודם לאשם.\u0004 ונדייק: \u0003חטאת הוא דקדמה ליה\u0004 \u0005[שקודמת לה]\u0006 \u0003לאשם, אבל עולה\u0004 — \u0003לא\u0004 קודמת לאשם. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר על \u0003דם?\u0004 ונפשוט מכאן את הבעיה.","ודוחים: \u0003לא,\u0004 מדובר על \u0003אימורים,\u0004 שבהם החטאת קודמת לאשם, ולא על דם. ומוסיפים: \u0003דיקא נמי\u0004 \u0005[מדוייק\u0006 כן \u0005גם כן]\u0006 מן הלשון, \u0003דקתני\u0004 \u0005[ששונה]\u0006 התנא כנימוק לדין זה, שהחטאת קודמת \u0003\"מפני שדמה ניתן\",\u0004 ולא \"מפני שהיא ניתנת\", \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שלא על הדם מדובר מתחילה.","שנינו במשנה: \u0003חטאת קודמת\u0004 לאשם מפני שדמה ניתן על ארבע קרנות המזבח ועל יסוד המזבח. ושואלים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 נאמר כי \u0003אשם קדים\u0004 \u0005[קודם],\u0006 \u0003שכן יש לו קיצבה\u0004 מן התורה, איל בשווי שני שקלים (ראה ויקרא ה, טו). מה שאין כן בחטאת, שאפשר להביאה אף במחיר מועט! ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 ענין \u0003ריבוי\u0004 מתנות הדם על ה\u0003מזבח עדיף.\u0004","ועוד שנינו במשנה: \u0003אשם קודם לתודה\u0004 ואיל נזיר, משום שהוא קדשי קדשים. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 נאמר ש\u0003התודה ואיל נזיר קדמי\u0004 \u0005[קודמים],\u0006 \u0003שכן\u0004 הם \u0003טעונין\u0004 (באים עם) \u0003לחם,\u0004 מה שאין כן האשם! ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 זה שקרבנות האשם הינם \u0003קדשי קדשים\u0004 עושה אותם \u0003עדיפי\u0004 \u0005[עדיפים].\u0006","שנינו במשנה: \u0003תודה ואיל נזיר\u0004 קודמים לשלמים, לפי שהם נאכלים רק ליום אחד. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003שלמים קדמי\u0004 \u0005[קודמים],\u0006 \u0003שכן ישנן בציבור כביחיד\u0004 שיש שלמי ציבור הבאים בעצרת (ראה ויקרא כג, יט). ואילו תודה ואיל נזיר הם רק קרבנות של יחידים! ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 כיון ש\u0003נאכלין ליום אחד, עדיפי\u0004 \u0005[עדיפים]\u0006 הם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003תודה ואיל נזיר, איזה מהן קודם?\u0004 וצדדי השאלה: האם \u0003תודה קדמה, שכן טעונה ארבעה מיני לחם,\u0004 חלות, רקיקים, רבוכה ולחם חמץ (ויקרא ז, יב—יג), ואיל נזיר טעון רק שני מינים, חלות ורקיקים (במדבר ו, טו). \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003איל נזיר קודם, שכן יש עמו דמים אחרים,\u0004 שהנזיר מביא עמו עולה וחטאת (במדבר ו, יד)? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה מפורשת מברייתא, ששנינו בה: \u0003זו\u0004 (תודה) \u0003קודמת לזו\u0004 (לאיל נזיר), \u0003שזו טעונה ארבעה מיני לחם, וזו אינה טעונה אלא שני מיני לחם.\u0004","ועוד שנינו במשנה: \u0003והשלמים קודמין לבכור,\u0004 לפי שהם טעונים סמיכה ונסכים ותנופת חזה ושוק. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003בכור קודם, שכן קדושתו\u0004 כבר \u0003מרחם\u0004 אמו, \u0003ונאכל לכהנים,\u0004 ואילו שלמים נאכלים לכל ישראל! ודוחים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 \u0003מצו‍ת יתירות\u0004 שיש בשלמים \u0003עדיפי\u0004 \u0005[עדיפות].\u0006","ועוד שנינו במשנה: \u0003הבכור קודם\u0004 למעשר, מפני שקדושתו מרחם ונאכל לכהנים. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מעשר קודם, שכן מקדש לפניו ולאחריו\u0004 שאם טעה במנין הבהמות, וקרא לתשיעי \"עשירי\", או שקרא לאחד עשר \"עשירי\" — הרי כל אלה קדושים! ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003קדושה מרחם עדיפא\u0004 \u0005[עדיפה].\u0006","ועוד שנינו במשנה: \u0003מעשר קודם לעופות\u0004 מפני שהוא מין זבח ויש בו קדשי קדשים, דמו ואימוריו. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003עופות קדמי\u0004 \u0005[קודמים],\u0006 \u0003שכן\u0004 הם עצמם \u0003קדשי קדשים\u0004 (עולה וחטאת)! ודוחים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 השיקול שמעשר הוא \u0003מין זבח עדיף.\u0004","ומביאים דיון שהוזכרה בו משנתנו. \u0003אמר רבינא בר שילא: אימורי קדשים קלים שיצאו\u0004 מן העזרה \u0003לפני זריקת דמים\u0004 — \u0003פסולין. ו\u0004כן \u0003תנא תונא\u0004 \u0005[שונה התנא שלנו\u0006 במשנה\u0005]:\u0006 מעשר קודם לעופות \u0003מפני שהוא זבח וישנו קדשי קדשים דמיו ואימורין.\u0004","ויש לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אימורין ליתנהו\u0004 \u0005[אינם]\u0006 \u0003בעופות, אלא דם מיהא איתיה\u0004 \u0005[על כל פנים ישנו]\u0006 גם בעופות, ומפני מה הזכיר כאן את הדם? \u0003אלא לאו קא משמע לן\u0004 \u0005[האם לא משמיע לנו]\u0006 בכך חידוש: \u0003אימורין\u0004 של מעשר (ושאר קדשים קלים) שמדובר עליהם כאן, הריהם \u0003כי\u0004 \u0005[כמו]\u0006 \u0003דמו:\u0004","\u0003מה דמו\u0004 שנזכר כאן הוא \u0003לפני זריקה\u0004 (שהרי משנזרק ונעשתה מצוותו שוב אינו בכלל דם הראוי למזבח), \u0003אף אימורין\u0004 שמדובר עליהם כאן הם \u0003קודם זריקה. וקא קרי להו\u0004 \u0005[ו\u0006ממה ש\u0005הוא קורא להם]\u0006 לאימורים כמו לדם \u0003\"קדשי קדשים\"\u0004 יש ללמוד: \u0003ומה דמו מיפסל\u0004 \u0005[נפסל]\u0006 \u0003ביוצא, אף אימורין מיפסל\u0004 \u0005[נפסל]\u0006 \u0003ביוצא.\u0004","ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[נאמר שמסייע לו]\u0006 ממחלוקת זו: \u0003בשר קדשים קלים שיצא\u0004 מן העזרה \u0003לפני זריקת דמים, ר' יוחנן אמר: כשר, ריש לקיש אמר: פסול.\u0004","ומסבירים את טעמיהם: \u0003ר' יוחנן אמר כשר\u0004 — \u0003הואיל וסופו לצאת,\u0004 שהרי בשר קדשים קלים נאכל בכל העיר, מחוץ לעזרה. \u0003ריש לקיש אמר פסול\u0004 — \u0003עדיין לא הגיע זמנו לצאת,\u0004 לפני זריקת הדם. ויש לדייק: \u0003עד כאן לא פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא בבשר\u0004 שסופו לצאת, ולכן ר' יוחנן אומר שהוא כשר, \u0003אבל באימורין\u0004 שאין סופם לצאת — \u0003לא,\u0004 וגם לדעת ר' יוחנן הריהם פסולים!","ודוחים: \u0003הוא הדין\u0004 ש\u0003באימורין\u0004 שיצאו קודם זריקת הדם \u0003נמי פליגי\u0004 \u0005[גם כן חלוקים],\u0006 ור' יוחנן מכשיר, \u0003והא דקא מיפלגי\u0004 \u0005[וזה שנחלקו]\u0006 \u0003בבשר\u0004 — \u0003להודיעך כחו\u0004 של \u0003ריש לקיש\u0004 עד כמה הוא מחמיר, ש\u0003אפילו בשר\u0004 ש\u0003סופה לצאת, אמר: עדיין לא הגיע זמנו לצאת.\u0004","ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי הלכה זו שאימורי קדשים קלים שיצאו לפני זריקת דמים נפסלים ביוצא, הריהי שנויה \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 ששנינו: \u0003אימורי קדשים קלים שיצאו\u0004 אל מחוץ לעזרה \u0003לפני זריקת דמים,\u0004 והיו בחוץ בשעת זריקת הדם, \u0003ר' אליעזר אומר: אין מועלין בהן\u0004 לפי שאין הזריקה מכשירה אותם להקרבה."],["\u0003ו\u0004לכן גם \u0003אין חייבין עליהן\u0004 כרת, לא \u0003משום\u0004 אכילת \u0003פיגול\u0004 (אם אחת מעבודות הקרבן נעשתה במחשבת חוץ לזמנו), ולא משום \u0003נותר\u0004 (אם נאכלו לאחר הזמן המותר באכילה), \u0003ו\u0004אין חייב כרת אם אכלם כשהוא \u0003טמא,\u0004 לפי שרק זריקה ראויה קובעת איסורים אלה על הקרבן. \u0003ר' עקיבא אומר:\u0004 זריקה מועילה לאימורים שיצאו, ולפיכך \u0003מועלין בהן\u0004 אם נהנה מהם, \u0003וחייבין עליהן\u0004 על אכילתם \u0003משום פיגול נותר וטמא.\u0004","ומסבירים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003ב\u0004מקרה \u0003דהדר עיילינהו\u0004 \u0005[שחזר\u0006 ו\u0005הכניסם]\u0006 את האימורים לעזרה, והיו במקומם בשעת זריקת הדם, \u0003פליגי\u0004 \u0005[חלוקים]\u0006 ר' אליעזר ור' עקיבא. \u0003ובהא פליגי\u0004 \u0005[ובזה\u0006 הם \u0005חלוקים]:\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003מיפסלי\u0004 \u0005[נפסלים]\u0006 האימורים \u0003ביוצא,\u0004 ולכן שוב אין להם תקנה בזריקת הדם, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' עקיבא, \u0005סבור]:\u0006 \u0003לא מיפסלי\u0004 \u0005[נפסלים]\u0006 \u0003ביוצא,\u0004 וכדעת ר' יוחנן, ולכן הזריקה מועילה בהם?","\u0003אמר רב פפא: ב\u0004מקרה \u0003דהדר עיילינהו\u0004 \u0005[שחזר\u0006 ו\u0005הכניסם]\u0006 את האימורים לעזרה, ואז זרק עליהם את הדם — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים],\u0006 ואף ר' אליעזר סבור שזריקת הדם הכשירתם, ואין היציאה פוסלתם. \u0003והכא בדאיתנהו אבראי\u0004 \u0005[וכאן ב\u0006זמן \u0005שהם נמצאים בחוץ]\u0006 בשעת זריקת הדם \u0003פליגי\u0004 \u0005[נחלקו]\u0006 ר' אליעזר ור' עקיבא. \u0003ובהא פליגי\u0004 \u0005[וב\u0006עקרון \u0005זה נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003אין זריקה מועלת\u0004 (מועילה) \u0003ליוצא\u0004 כאשר הוא בחוץ, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' עקיבא, \u0005סבור]:\u0006 \u0003זריקה מועלת ליוצא.\u0004","ותוהים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב פפא\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר\u0004 היפך דבריו כאן, ביחס לשתי הלחם שיצאו מהמקדש קודם זריקת דמם של כבשי העצרת (המכשירה אותם לאכילה). שם גם כן נחלקו ר' אליעזר ור' עקיבא, האם כשנזרק הדם במחשבת חוץ לזמנו חייבים על שתי הלחם משום פיגול. ועל כך אמר רב פפא: אם נזרק הדם \u0003בדאיתנהו אבראי\u0004 \u0005[ב\u0006זמן \u0005שהם נמצאים בחוץ]\u0006 \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שאין חייבים עליהם, וגם ר' עקיבא סבור, שאין זריקה מועלת ליוצא. ודווקא \u0003בדעיילינהו לגוואי פליגי\u0004 \u0005[בשהכניסם לפנים נחלקו]!\u0006","ומשיבים, יש לחלק בין המקרים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שלדעת הכל אין הזריקה מועילה ליוצא, נאמרו דווקא ל\u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שתי\u0004 ה\u0003לחם,\u0004 משום \u0003דלאו גופיה דזיבחא\u0004 \u0005[שאינם גופו של הזבח],\u0006 של כבשי העצרת. \u0003אבל אימורין, דגופיה דזיבחא\u0004 \u0005[שגופו של זבח]\u0006 \u0003הוא,\u0004 יש לומר שלדעת הכל מועילה להם זריקה כשהם בפנים, ורק \u0003בדאיתנהו אבראי פליגי\u0004 \u0005[בהיותם בחוץ נחלקו]\u0006 ר' אליעזר ור' עקיבא האם תועיל להם הזריקה.","שנינו במשנה: \u0003עופות קודמין\u0004 למנחות מפני שהם מיני דמים. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 נאמר ש\u0003מנחות\u0004 תהיינה \u0003קודמות\u0004 לעופות, \u0003שכן ישנן בצבור כביחיד\u0004, ואילו עופות אינם באים אלא כקרבן יחיד! ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003מיני דמים עדיפי\u0004 \u0005[עדיפים].\u0006","שנינו במשנה כי \u0003מנחת חוטא\u0004 (שאין ידו משגת לחטאת בהמה או עוף) קודמת למנחת נדבה. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 נאמר ש\u0003מנחת נדבה\u0004 תהיה \u0003קודמת\u0004 למנחת חוטא, \u0003שכן\u0004 היא \u0003טעונה\u0004 (מביאים עמה) \u0003שמן ולבונה!\u0004 ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003מנחת חוטא הבאה על חטא עדיפא\u0004 \u0005[עדיפה,\u0006 קודמת\u0005],\u0006 שכן היא \u0003מכפרת,\u0004 מה שאין כן מנחת נדבה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 היו לפני הכהן \u0003מנחת סוטה ומנחת נדבה, איזו מהן קודמת?\u0004 וצדדי השאלה: האם \u0003מנחת נדבה קדמה\u0004 \u0005[קודמת],\u0006 \u0003שכן\u0004 היא \u0003טעונה שמן (או) ולבונה, או דלמא\u0004 \u0005[שמא]\u0006 \u0003מנחת סוטה קדמה\u0004 \u0005[קודמת],\u0006 \u0003שכן\u0004 היא \u0003באה לברר עון\u0004 כחלק מתהליך הבדיקה של המים המאררים?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003מנחת חוטא קודמת למנחת נדבה\u0004 מפני שהיא באה על חטא. ונדייק מכאן: דווקא \u0003מנחת חוטא הוא דקדמה\u0004 \u0005[היא שקודמת]\u0006 \u0003למנחת נדבה, הא\u0004 \u0005[אבל]\u0006 \u0003מנחת סוטה\u0004 — \u0003לא.\u0004 ודוחים: \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 שמעלת מנחת חוטא היא \u0003מפני שהיא מכפרת? \"מפני שהיא באה על חטא\" קתני\u0004 \u0005[שנה],\u0006 \u0003והא נמי\u0004 \u0005[וזו,\u0006 מנחת סוטה, \u0005גם כן]\u0006 \u0003באה על חטא,\u0004 שנסתרה הסוטה עם זר.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו בברייתא: \u0003זו קודמת לזו, שזו באה מן החיטין וזו באה מן השעורין. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003מנחת נדבה\u0004 שקודמת \u0003למנחת סוטה?\u0004 ודוחים: \u0003לא,\u0004 הכוונה ל\u0003מנחת חוטא\u0004 שקודמת \u0003למנחת סוטה.\u0004 ומקשים: אם כן, מדוע נזקקים לנתינת טעם זה של חיטים ושעורים?","\u0003תיפוק\u0004 \u0005[תצא]\u0006 \u0003לי\u0004 הלכה זו מטעם \u0003דהא\u0004 \u0005[שזו,\u0006 מנחת חוטא\u0005]\u0006 \u0003מכפרת, והא\u0004 \u0005[וזו,\u0006 מנחת סוטה\u0005]\u0006 \u0003לא מכפרת,\u0004 אלא רק מבררת עוון!","ודוחים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר, שהכוונה היא ל\u0003מנחת נדבה\u0004 שקודמת למנחת סוטה? \u0003תיפוק\u0004 \u0005[תצא]\u0006 \u0003לי\u0004 הלכה זו מטעם ש\u0003זו\u0004 מנחת נדבה \u0003טעונה שמן ולבונה, וזו\u0004 מנחת סוטה \u0003אינה טעונה שמן ולבונה! אלא\u0004 אין להוכיח ממה שלא נזכר טעם נוסף, כי \u0003חד מתרי טעמי [נקיט]\u0004 \u0005[אחד משני טעמים תפס]\u0006 והזכיר.","שנינו במשנה: \u0003חטאת העוף קודמת\u0004 לעולת העוף. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בענין קרבנות העוף, חטאת ועולה שמביא חוטא עני על שגגתו במקום חטאת מן הבהמה: מה שנאמר \u0003\"והקריב את אשר לחטאת ראשונה\"\u0004 (ויקרא ה, ח), \u0003מה תלמוד לומר\u0004 (מה בא ללמדנו)? \u0003ש\u0004כן \u0003אין תלמוד לומר\u0004 שבא \u0003ללמד שתקרב\u0004 חטאת העוף \u0003ראשונה,\u0004 לפני עולת העוף, ש\u0003הרי כבר נאמר\u0004 בהמשך: \"\u0003ואת השני יעשה עולה\u0004\" (ויקרא ה, י).","\u0003אלא זה\u0004 הכתוב \u0003בנה אב,\u0004 בא ללמד כלל \u0003לכל\u0004 ה\u0003חטאות שיקדמו ל\u0004קרבנות \u0003עולה הבאות עמהן, בין חטאת העוף לעולת העוף, בין חטאת בהמה לעולת בהמה, ואפילו חטאת העוף\u0004 קודמת בהקרבה \u0003לעולת בהמה.\u0004","ומסכמים את המקורות לקדימת חטאת לעולה: \u0003הלכך\u0004 \u0005[על כן],\u0006 \u0003חטאת העוף\u0004 שקודמת \u0003לעולת העוף\u0004 — נלמד הדבר \u0003מ\u0004הפסוק \u0003\"ואת השני\u0004 יעשה עולה\", כמבואר כאן. \u0003חטאת בהמה\u0004 שקודמת \u0003לעולת בהמה\u0004 — \u0003מדרבי רחמנא\u0004 \u0005[מ\u0006מה \u0005שריבתה התורה]\u0006 בחטאת הלויים מן האמור \"ופר שני בן בקר\" (במדבר ח, ח), כמבואר בעמוד הקודם. \u0003חטאת העוף\u0004 שקודמת \u0003לעולת בהמה\u0004 — \u0003מ\"זה בנה אב\",\u0004 כמבואר כאן.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 סתירה לכלל זה, שכל חטאות קודמות לעולות הבאות עמהן, ממה שבקרבן יולדת עניה הקדים עולת העוף לחטאת העוף, שנאמר \"אחד לעולה ואחד לחטאת\" (ויקרא יב, ח), ועל כך שנינו, \u0003ר' אליעזר אומר: כל מקום שנתחלפה חטאת\u0004 מן הבהמה בקרבן מן העוף, אם עני הוא המקריב, כגון במטמא מקדש בשוגג, שבמקום כבשה לחטאת מביא שני עופות, אחד לחטאת ואחד לעולה — \u0003חטאת קודמת\u0004 לעולה. \u0003וכאן ביולדת\u0004 עניה, שאם עשירה היתה מביאה כבש לעולה (ועוף לחטאת) — \u0003עולה קודמת\u0004 לחטאת.","וכן \u0003כל מקום שבא\u0004 הקרבן \u0003על חטא\u0004 — \u0003חטאת קודמת\u0004 לעולה, \u0003וכאן\u0004 ביולדת, שקרבן חטאתה אינו לכפרה אלא לטהרה — ה\u0003עולה קודמת. וכל מקום ששנים\u0004 (שני עופות) \u0003באים תחת חטאת\u0004 שמביא קרבנו בדלות — \u0003חטאת קודמת, וכאן\u0004 ביולדת שאין שניהם באים תחת חטאת, אלא רק עולה תחת עולה (שהרי גם עשירה מביאה חטאת מן העוף) — \u0003עולה קודמת.\u0004 משמע שפעמים עולה קודמת לחטאת!","\u0003אמר רבא:\u0004 רק \u0003למקראה הקדימה הכתוב,\u0004 שבקרבן יולדת הזכיר אותה תחילה, אבל למעשה מקריבים גם ביולדת את החטאת תחילה.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת: היו לפניו קרבנות ממינים שונים, מה יעשה? \u0003פרים קודמין לאילים, ואילים קודמין לכבשים, כבשים\u0004 קודמים \u0003לשעירים.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר במוספי \u0003חג\u0004 הסוכות, שיש בהם שעירים לחטאת וכבשים לעולה? ואם כן, יש שעולה קודמת לחטאת! ודוחים: \u0003לא,\u0004 כאן מדובר בקרבנות שכולם באו \u0003לנדבה,\u0004 וגם השעירים. וטעמה של הברייתא כך הוא: \u0003פרים קודמין לאילים\u0004 — \u0003שכן נתרבו בנסכים,\u0004 שנסכי הפר חצי ההין יין, ונסכי האיל שלישית ההין, \u0003וכן\u0004 מסיבה זו, קודמים \u0003אילים לכבשים,\u0004 שנסכיהם רביעית ההין (ראה במדבר טו, א—יב). ואילו ה\u0003כבשים\u0004 קודמים \u0003לשעירים,\u0004 למרות שנסכיהם שווים — \u0003שכן נתרבו ב\u0004הקרבת אימוריהם גם ב\u0003אליה\u0004 שלהן, מה שאין כן השעירים.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במסכת הוריות: \u0003פר\u0004 חטאת \u0003כהן משיח\u0004 שמביא כהן גדול על שגגת הוראה (ויקרא ד, ג) \u0003קודם\u0004 בהקרבה \u0003לפר\u0004 חטאת על \u0003העלם דבר של צבור\u0004 שמביאים כששגגו הסנהדרין בהוראה (ויקרא ד, יג); \u0003פר העלם דבר של צבור\u0004 בשאר עבירות \u0003קודם לפר\u0004 העלם דבר של ציבור בשגגת \u0003עבודה זרה,\u0004 שהוא קרבן עולה (במדבר טו, כד);","\u0003פר עבודה זרה קודם לשעירי עבודה זרה,\u0004 כלומר, לשעיר הבא עמו (במדבר טו, כד), \u0003דאף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003פר עבודה זרה\u0004 הוא \u0003עולה ושעירי עבודה זרה\u0004 הם \u0003חטאת.\u0004 ובניגוד לכלל שהובא, שבכל מקום חטאת קודמת לעולה הבאה עמה!","ודוחים: עד שאתה מקשה על כלל זה מסוף המשנה, \u0003ואימא מרישא\u0004 \u0005[ואמור\u0006 והבא סיוע לכלל זה \u0005מן ההתחלה\u0006 של אותה משנה\u0005]\u0006 שנאמר בה: \u0003פר העלם דבר של צבור\u0004 שהוא חטאת, \u0003קודם לפר עבודה זרה\u0004 שהוא עולה!","ומשיבים: \u0003בחד מינא מיהא לא קאמרינן\u0004 \u0005[במין אחד על כל פנים אין אנו אומרים],\u0006 שכיון ששני הקרבנות הם ממין אחד (פרים) ודאי ש\u0003חטאת קדמה\u0004 \u0005[קודמת].\u0006 \u0003כי קאמרינן בתרי מיני\u0004 \u0005[כאשר אנו אומרים\u0006 ומקשים הרי זה \u0005בשני מינים],\u0006 שלפי הכלל שהובא בברייתא, גם חטאת העוף קודמת לעולת בהמה שהיא גדולה, וכאן \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003עולה דקדמה\u0004 \u0005[שקודמת]\u0006 \u0003לחטאת!\u0004","\u0003אמרי במערבא משמיה\u0004 \u0005[אומרים בארץ ישראל משמו]\u0006 של \u0003רבא בר מרי: חטאת עבודה זרה חסר א', \"לחטת\" כתיב\u0004 \u0005[כתוב]\u0006 (\"ושעיר עזים אחד לחטת\", במדבר טו, כד), לומר שאין חטאת זו כשאר חטאות, ופר העולה קודם לה. \u0003רבינא אמר: \"כמשפט\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 (\"ועשו כל העדה פר בן בקר אחד לעולה לריח ניחוח לה' ומנחתו ונסכו כמשפט ושעיר עזים לחטת\", במדבר טו, כד), לומר שמקריבים קרבנות אלה כסדר שהם כתובים במקרא, ולכן פר העולה קודם.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן]\u0006 והשתמשת בהסבר זה, יש לחזור ולהסביר את הברייתא הקודמת שהובאה כראיה, ולומר: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר שם ב\u0003פרים\u0004 ושאר קרבנות מוסף של \u0003חג נמי\u0004 \u0005[גם כן],\u0006 אין להקשות ממה שכבשי העולה קודמים לשעירי החטאת, שכן \u0003\"כמשפטם\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 (במדבר כט, לג).","בעקבות המסקנה, שחטאת העוף קודמת לעולת בהמה, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: היו לפניו \u0003חטאת העוף, ועולת בהמה, ומעשר, איזו מהן קודם\u0004 בהקרבה? וצדדי הבעיה, אם תאמר: \u0003תיקדום\u0004 \u0005[תקדם]\u0006 \u0003חטאת העוף\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 \u0003מעשר דקדים\u0004 \u0005[שקודם]\u0006 \u0003לה,\u0004 כפי ששנינו במשנה, מפני שהוא מין זבח! ואם תאמר: \u0003ליקדים\u0004 \u0005[שיקדים]\u0006 את ה\u0003מעשר\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 \u0003עולת בהמה דקדמה ליה\u0004 \u0005[שקודמת לו],\u0006 שהיא קדשי קדשים! ואם תאמר: \u0003תיקדום\u0004 \u0005[תקדם]\u0006 \u0003עולת בהמה\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 \u0003חטאת העוף דקדמה\u0004 \u0005[שקודמת]\u0006 \u0003לה!\u0004","בפתרון שאלה זו, \u0003הכא תרגימו\u0004 \u0005[כאן,\u0006 בבבל, \u0005תרגמו\u0006 הסבירו\u0005]\u0006 כי השיקול של \u0003מין זבח עדיף,\u0004 ולכן יקרב תחילה המעשר, ואחריו חטאת העוף, ולבסוף עולת הבהמה. \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל אומרים]:\u0006 \u0003עיילא\u0004 \u0005[נכנסה]\u0006 \u0003בה עולת בהמה בחטאת העוף\u0004 הבאה עמה, \u0003ואגבהתה\u0004 \u0005[והגביהה אותה]\u0006 במעלתה \u0003מ\u0004על ה\u0003מעשר,\u0004 שהרי עולת הבהמה מקודשת ממנו. ולפיכך תקדם חטאת העוף, ואחריה עולת הבהמה, ואחר כך המעשר.","ועוד בדיני קדימויות בקרבנות. \u0003כל\u0004 קרבנות \u0003החטאות שבתורה קודמות\u0004 בהקרבתן \u0003לאשמות,\u0004 כפי ששנינו במשנה הקודמת (לעיל זבחים פט,א), מפני שדם החטאת ניתן על ארבע קרנות המזבח ועל יסוד המזבח, מה שאין כן באשם. \u0003חוץ מאשם מצורע, מפני שהוא בא על הכשר\u0004 כדי להתיר את המצורע לאכול בקדשים ולהיכנס למקדש. והואיל ובו תלויה עיקר טהרת המצורע, לפיכך חשוב הוא יותר מן החטאת.","ועוד הבחנה בין קרבנות האשם השונים: \u0003כל האשמות שבתורה באין\u0004 מן האילים, שהם כבשים זכרים \u0003בני שתים\u0004 כלומר, בשנתם השניה, \u0003ובאין בכסף שקלים\u0004 (ששוויים צריך להיות לפחות שני סלעים), \u0003חוץ מאשם נזיר ואשם מצורע, שהן באין\u0004 מכבשים \u0003בני שנתן\u0004 הראשונה, \u0003ואין\u0004 הם \u0003באין בכסף שקלים\u0004 שאין להם מחיר קצוב. ועוד בדיני קדימה בקרבנות.","\u0003כשם ש\u0004קרבנות המקודשים מאחרים \u0003קודמין\u0004 להם \u0003בהקרבן,\u0004 לפי סדר הקדימות במשנה הקודמת (פט,א), כך הם גם \u0003קודמין\u0004 להם \u0003באכילתן.\u0004 ועוד בענין קדימה: \u0003שלמים של אמש\u0004 (אתמול) \u0003ושלמים של\u0004 ה\u0003יום\u0004 — שלמים \u0003של אמש קודמין ל\u0004שלמים \u0003של\u0004 ה\u0003יום.\u0004 וכמו כן אם היו לפניו \u0003שלמים של אמש, חטאת ואשם של היום\u0004 — \u0003שלמים של אמש קודמין,\u0004 אלו \u0003דברי ר' מאיר. ו\u0004אילו \u0003חכמים אומרים:\u0004 ה\u0003חטאת קודמת\u0004 לשלמים (וכן האשם), \u0003מפני שהיא קדשי קדשים,\u0004 ומעלתה גדולה משל השלמים שהם קדשים קלים.","\u0003וכולן\u0004 בכל הקרבנות הנאכלים, \u0003הכהנים רשאין לשנות באכילתן\u0004 ולאכול אותם בכל אופן שירצו: \u0003לאכלן צלוין\u0004 באש, \u0003ושלוקין\u0004 (מבושלים ביותר), \u0003ומבושלין\u0004 כרגיל. ורשאים הכהנים \u0003לתת לתוכו תבלי\u0004 (תבלינים של) \u0003חולין ותבלי תרומה,\u0004 אלו \u0003דברי ר' שמעון. ר' מאיר אומר: לא יתן לתוכו תבלי תרומה,\u0004 כדי \u0003שלא יביא התרומה לידי פסול,\u0004 שהרי לקדשים יש זמן אכילה קצוב, ולאחר מכן הם נפסלים ודינם לשריפה, ונמצא פוסל גם את התרומה מאכילה.","שנינו למעלה (פט,א) כי התדיר מחבירו קודם לחבירו, וכן שנינו במשנה הקודמת (פט,א) ובמשנתנו כי המקודש מחבירו קודם לו. ומעתה \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: היו לפני הכהן שני קרבנות, האחד \u0003תדיר\u0004 מחבירו \u0003ו\u0004אולם האחר \u0003מקודש\u0004 מחבירו, \u0003איזה מהם קודם?\u0004 וצדדי השאלה: האם ה\u0003תדיר קודם, משום\u0004 שהוא \u0003תדיר\u0004 \u0003מחבירו, או דלמא\u0004 \u0005[שמא]\u0006 ה\u0003מקודש קדים\u0004 \u0005[קודם],\u0006 משום שהוא \u0003קדיש\u0004 \u0005[מקודש]\u0006 יותר מחבירו? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו במשנה בתחילת הפרק: \u0003תמידין\u0004 הבאים בכל יום \u0003קודמין למוספין,\u0004 משום שתדיר קודם,"],["\u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 שקרבנות ה\u0003מוספין קדישי\u0004 \u0005[קדושים]\u0006 יותר, שהרי הם מיוחדים לשבת! ודוחים: \u0003אטו\u0004 \u0005[וכי]\u0006 קדושה יתירה זו של \u0003שבת\u0004 רק \u0003ל\u0004קרבנות ה\u0003מוספין\u0004 הבאים בה \u0003אהנאי\u0004 \u0005[הועילה]\u0006 להחשיבם מקודשים יותר, ו\u0003ל\u0004קרבנות \u0003תמידין\u0004 הבאים בה, האם \u0003לא אהנאי\u0004 \u0005[הועילה]?\u0006 שאף תמידים של שבת נחשבים מקודשים יותר. ואין מכאן כל ראיה, איפוא, שהרי בתמידים של שבת יש מעלת תדיר ומקודש.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003מוספי שבת קודמין למוספי ראש חודש\u0004 כשחל בשבת, אף שראש חודש יש בו קדושה יתירה. הרי שתדיר ומקודש — תדיר קודם! ודוחים באותו אופן: \u0003אטו\u0004 \u0005[וכי]\u0006 מעלה זו של \u0003ראש חודש\u0004 רק \u0003ל\u0004קרבנות ה\u0003מוספין דידיה אהני\u0004 \u0005[שלו הועילה]\u0006 ואילו \u0003ל\u0004קרבנות \u0003מוספי שבת\u0004 שחל בו ראש חודש \u0003לא אהני\u0004 \u0005[הועילה]?\u0006","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003מוספי ראש חודש קודמין למוספי ראש השנה, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003ראש השנה קדשה\u0004 \u0005[מקודש]\u0006 יותר. הרי שתדיר קודם למקודש! ודוחים שוב: \u0003אטו\u0004 \u0005[וכי]\u0006 מעלה זו של \u0003ראש השנה\u0004 רק \u0003למוספי דידיה אהני\u0004 \u0005[שלו הועילה],\u0006 ואילו \u0003למוספי ראש חודש לא אהני\u0004 \u0005[הועילה]?\u0006","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במחלוקת בית שמאי ובית הלל בקידוש של שבת, האם ברכת היין או ברכת הקידוש קודמת. שבית הלל הסבורים שברכת היין קודמת הביאו ראיה לדבריהם: \u0003דבר אחר, ברכת היין תדירה וברכת היום, אינה תדירה, ותדיר ושאינו תדיר\u0004 — \u0003תדיר קודם\u0004. והביאו ראיה זו \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003ברכת היום,\u0004 שהיא באה מכח קדושת השבת, \u0003קדישה\u0004 \u0005[קדושה]\u0006 מברכת היין. הרי שתדיר קודם למקודש! ודוחים: \u0003אטו\u0004 \u0005[וכי]\u0006 מעלה יתירה של \u0003שבת\u0004 רק \u0003לברכת היום אהנאי\u0004 \u0005[הועילה],\u0006 ואילו \u0003לברכת היין לא אהנאי\u0004 \u0005[הועילה]?\u0006 ולכן אין להביא מכאן ראיה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ש\u0003אמר ר' יוחנן: הלכה\u0004 היא, שאם כבר הגיע בשבת זמן תפילת המנחה, ולא התפלל עדיין תפילת מוסף — \u0003מתפלל אדם\u0004 תחילה תפילה \u0003של מנחה, ואחר כך\u0004 תפילה \u0003של מוספין.\u0004 משמע שתדיר קודם למקודש! ודוחים: \u0003אטו\u0004 \u0005[וכי]\u0006 מעלה זו של \u0003שבת\u0004 רק \u0003לתפלת מוספין אהנאי\u0004 \u0005[הועילה],\u0006 ואילו \u0003לתפלת מנחה לא אהנאי\u0004 \u0005[הועילה]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממשנתנו: היו לפני הכהן \u0003שלמים של אמש, חטאת ואשם של יום\u0004 — \u0003שלמים של אמש קודמין\u0004 לדעת ר' מאיר. ויש לדייק מכאן, \u0003הא אידי ואידי דיום\u0004 \u0005[אבל\u0006 אם היו \u0005אלה ואלה של היום]\u0006 — \u0003חטאת ואשם קדמי\u0004 \u0005[קודמים],\u0006 \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003שלמים תדירי\u0004 \u0005[תדירים],\u0006 שאנשים רגילים להביא שלמים בנדר ונדבה. משמע שהמקודש קודם לתדיר!","\u0003אמר רבא:\u0004 ממה שהוא \u0003מצוי קאמרת\u0004 \u0005[אומר אתה]\u0006 להביא ראיה? אמנם קרבנות השלמים מרובים ומצויים יותר מן החטאת, אבל אין להם מעלה של חובה קבועה ותמידית. ו\u0003תדיר\u0004 הוא \u0003קמיבעיא לן\u0004 \u0005[\u0006ש\u0005נשאלה לנו]\u0006 אם הוא קודם למקודש, \u0003מצוי לא קמיבעיא לן\u0004 \u0005[נשאלה לנו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר יהודה לרבא: אטו\u0004 \u0005[וכי]\u0006 \u0003מצוי לאו\u0004 \u0005[אינו]\u0006 בכלל \u0003\"תדיר\"? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בענין מצוות עשה שיש כרת על ביטולן, ומכל מקום אין מביאים חטאת על שגגתם: \u0003אוציא את הפסח\u0004 מכלל חובת חטאת לפי \u0003שאינו תדיר, ולא אוציא את המילה שהיא תדירה.\u0004 והרי מילה אינה תדירה, אלא שהיא מצויה יותר מן הפסח!","ודחה רבא: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"תדירה\"\u0004 האמורה כאן? לא שהיא מצויה יותר, אלא שהיא \u0003תדירה במצות,\u0004 שיש בה מצוות רבות. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003מילה לגבי\u0004 \u0005[אצל]\u0006 \u0003פסח כי תדיר דמיא\u0004 \u0005[כמו תדיר\u0006 היא \u0005נחשבת],\u0006 שהיא מצויה הרבה יותר מפסח, ונחשבת לעומתו כתדירה, מה שאין כן בשלמים ביחס לחטאת. ומשום כך אין להוכיח ממשנתנו שהמקודש קודם לתדיר.","ועוד בדיני קדימה בעבודות המקדש, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 היו לפני הכהן שני קרבנות, \u0003תדיר ושאינו תדיר, ו\u0004אף שהיה צריך להקדים את התדיר \u0003קדים\u0004 \u0005[קדם]\u0006 \u0003ושחט לשאינו תדיר, מאי\u0004 \u0005[מה]\u0006 הדין? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דשחטיה\u0004 \u0005[ששחטו]\u0006 כבר, \u0003מקריב ליה\u0004 \u0005[אותו].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 לא יקריבנו, אלא \u0003יהיב\u0004 \u0005[יתן]\u0006 אותו \u0003ל\u0004כהן \u0003אחר\u0004 ש\u0003ממרס\u0004 (שמנענע ובוחש) \u0003בדמו\u0004 כדי שלא יקרש, \u0003עד\u0004 ש\u0003מקריב ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004קרבן שהוא \u0003תדיר, ו\u0004רק אחרי כן \u0003הדר\u0004 \u0005[חוזר]\u0006 ו\u0003מקריב לשאינו תדיר?\u0004","\u0003אמר רב הונא מסורא,\u0004 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה ששנינו במשנתנו, לענין המקודש מחבירו: \u0003שלמים של אמש\u0004 שהובאו אתמול, \u0003חטאת ואשם של יום\u0004 — שלמים \u0003של אמש קודם ל\u0004חטאת \u0003של יום.\u0004 ויש לדייק: דווקא שלמים של אמש קודמים, \u0003הא\u0004 \u0005[אבל]\u0006 אם היו שלמים שהביאם ה\u0003יום דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003אמש,\u0004","\u0003והיכי דמי\u0004 \u0005[וכיצד הוא בדיוק]?\u0006 \u0003דקדים שחטיה\u0004 \u0005[שקדם ושחט]\u0006 \u0003לשלמים,\u0004 במקרה זה נאמר כי \u0003חטאת ואשם קדמי\u0004 \u0005[קודמים]\u0006 למרות שכבר שחט את השלמים, מאחר שהם מקודשים יותר. והוא הדין לתדיר, שיש לשוחטו קודם שייזרק דם הקרבן שאינו תדיר!","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 מה שנאמר במשנה: \u0003שלמים\u0004 של \u0003אמש וחטאת ואשם\u0004 של \u0003יום,\u0004 ששלמים של אמש קודמים, ומכאן דייקנו שאם הובאו שניהם היום החטאת קודמת, \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]\u0006 — \u0003דשחטינהו לתרוייהו\u0004 \u0005[ש\u0006כבר \u0005שחט את שניהם]\u0006 את השלמים והחטאת, ושניהם עומדים לזריקה. \u0003אבל לא שחטינהו לתרוייהו\u0004 \u0005[שחט את שניהם],\u0006 אלא רק את השלמים, ודמם עומד לזריקה, עדיין \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה האם יש להניח את דם השלמים, ולשחוט את החטאת המקודשת יותר. וכיוצא בזה לענין תדיר ושאינו תדיר.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה ששנינו לגבי סדר ברכות הקידוש של שבת: \u0003דבר אחר, ברכת היין תדירה וברכת היום אינה תדירה, ותדיר ושאינו תדיר\u0004 — \u0003תדיר קודם.\u0004 והרי קדושת השבת חלה עליו ונתחייב בברכת היום עוד קודם שעמד לברך על היין, ובכל זאת היין קודם משום שהוא תדיר. וכך גם לענייננו, יש להקדים את שחיטת התדיר, למרות שכבר החל בעבודת הקרבן שאינו תדיר!","ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין ברכות הקידוש, אינו דומה לענייננו, \u0003דכיון דאתיין\u0004 \u0005[שכיון שבאות]\u0006 הברכות לפניו כאחת, כשהוא עומד לקדש — \u0003כמאן דשחיטי תרוייהו דמי\u0004 \u0005[כמו ששחוטים שניהם נחשב\u0006 הדבר\u0005].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר ר' יוחנן, הלכה:\u0004 אם הגיע זמן המנחה בשבת \u0003מתפלל אדם\u0004 תפילה \u0003של מנחה ואחר כך של מוספין,\u0004 אף שחיוב המוסף חל עליו קודם! ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003כיון דמטי\u0004 \u0005[שמגיע]\u0006 כבר \u0003זמן תפלת מנחה,\u0004 ושני החיובים מוטלים עליו, \u0003כמאן דשחיטי תרוייהו דמי\u0004 \u0005[כמו ששחוטים שניהם נחשב\u0006 הדבר\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי לרבינא:\u0004 אפשר להביא ראיה ממשנה זו: \u0003שחטו\u0004 את קרבן הפסח \u0003קודם חצות\u0004 — \u0003פסול, מפני שנאמר בו \"בין הערבים\"\u0004 (שמות יב, ו). שחטו \u0003קודם לתמיד\u0004 של בין הערביים — \u0003כשר,\u0004 למרות שצריך להקדים את התמיד, \u0003ויהא ממרס בדמו\u0004 של הפסח \u0003עד ש\u0004ישחוט את התמיד ו\u0003יזרוק הדם.\u0004 הרי שלמרות שקדם ושחט את שאינו תדיר — שוחט תחילה את התדיר, ואחר זורק דמו של השחוט!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה עוסקים אנו]?\u0006 \u0003כגון דקדים שחטיה\u0004 \u0005[שקדם ושחטו]\u0006 \u0003לתמיד ברישא\u0004 \u0005[בתחילה],\u0006 וקודם שזרק את דמו שחט את הפסח. והואיל ודם שניהם עומד לזריקה, לכן מקדים את זריקת דם התמיד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא סבא לרב אשי: מתניתין נמי דיקא\u0004 \u0005[\u0006לשון \u0005משנתנו גם כן מדוייקת\u0006 כך\u0005],\u0006 \u0003דקתני\u0004 \u0005[ש\u0006הוא \u0005שונה]:\u0006 \u0003\"עד שיזרק הדם\" (תמיד), ולא קתני\u0004 \u0005[ואינו שונה]\u0006 \u0003\"עד שישחוט ויזרק דם\",\u0004 משמע שהתמיד כבר שחוט. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003בכולן\u0004 בכל הקרבנות הנאכלים, \u0003כהנים רשאין\u0004 לשנות באכילתם, לאוכלם צלי שלוק ומבושל. ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006 המקור\u0005]\u0006 להלכה זו? \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במתנות כהונה: \"לך נתתים \u0003למשחה\u0004 ולבניך לחק עולם\" (במדבר יח, ח), ומתרגמים \"למשחה\" — \u0003לגדולה,\u0004 שיהא בשר הקרבן נאכל בדרך גדולה, \u0003כדרך שהמלכים אוכלין,\u0004 והרי המלכים אוכלים את מאכלם בכל אופן שירצו.","ועוד בענין אכילה של כהנים. \u0003אמר ר' שמעון: אם ראית שמן שהוא מתחלק בעזרה\u0004 בין הכהנים, שיאכלוהו, וברצונך לדעת מה טיבו, \u0003אין\u0004 אתה \u0003צריך לשאול מהו, אלא\u0004 הריהו \u0003מותר\u0004 השמן של \u0003רקיקי מנחות ישראל\u0004 לאחר שמשחו אותם במעט שמן, או שהוא מותר \u0003לוג שמן של מצורע\u0004 לאחר שהיזו ממנו, שאף הוא ניתן לכהנים.","ומצד אחר, \u0003אם ראית שמן שהוא ניתן על גבי האישים\u0004 כקרבן, \u0003אין\u0004 אתה \u0003צריך לשאול מהו, אלא\u0004 הריהו בוודאות \u0003מותר\u0004 השמן של \u0003רקיקי מנחת כהנים,\u0004 או מותר השמן של \u0003מנחת כהן משיח,\u0004 שיש באלו שמן מרובה, ואין בהם חלק לכהנים, אלא הן עולות כליל למזבח. ומוסיפה המשנה: ואין להניח כי השמן המתחלק לכהנים או הניתן על גבי האישים הריהו שמן שהביא אדם כנדבה, לפי \u0003שאין מתנדבין שמן. ר' טרפון אומר: מתנדבין שמן.\u0004"],["\u0003אמר שמואל: לדברי ר' טרפון\u0004 במשנתנו, הסבור שמתנדבים שמן למקדש, אדם \u0003המתנדב שמן\u0004 — הכהן \u0003קומצו\u0004 (נוטל ממנו קומץ) ומקטירו, \u0003ושיריו\u0004 (מה שנותר) \u0003נאכלין\u0004 \u0003לכהנים. מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 לכך? \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי מנחת נדבה: \"ונפש כי תקריב \u0003קרבן מנחה\"\u0004 (ויקרא ב, א), וייתור המלה \"קרבן\" \u0003מלמד שמתנדבין\u0004 גם \u0003שמן, וכי\u0004 \u0005[וכמו]\u0006 \u0003מנחה: מה מנחה\u0004 — \u0003קומצה\u0004 (קומץ אותה) הכהן \u0003ושיריה נאכלין, אף שמן\u0004 — \u0003קומצו\u0004 הכהן \u0003ושיריו נאכלין.\u0004","\u0003אמר ר' זירא: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 במשנתנו כדברי שמואל, שכן שנינו: \u0003אמר ר' שמעון: אם ראית שמן שמתחלק בעזרה, אי\u0004 (אין) \u0003אתה צריך לשאול מהו, אלא מותר רקיקי מנחות ישראל ולוג שמן של מצורע,\u0004 וטעם הדבר — מפני \u0003שאין מתנדבין\u0004 שמן. ונדייק: \u0003מכלל\u0004 דברים אלה יש ללמוד, כי לשיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מתנדבין\u0004 שמן, הריהו \u0003מתחלק\u0004 בין הכהנים לאכילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לר' זירא: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003אם ראית שמן שניתן על גבי אישים, אי אתה צריך לשאול מהו, אלא מותר רקיקי מנחת כהנים ומנחת כהן משיח,\u0004 וטעם הדבר — מפני \u0003שאין מתנדבין שמן.\u0004 ונדייק: \u0003מכלל דלמאן דאמר\u0004 \u0005[של\u0006 דעת \u0005מי שאומר]\u0006 \u0003מתנדב\u0004 אדם שמן, הריהו עולה \u0003כולן לאישים\u0004, והרי זה בניגוד לדברי שמואל, שאמר כי לדברי ר' טרפון, מקטיר קומצו ושייריו נאכלים. על כל פנים, \u0003לאביי קשיא רישא\u0004 \u0005[קשה\u0006 הדיוק מ\u0005תחילת\u0006 המשנה\u0005],\u0006 \u0003לר' זירא קשיא סיפא\u0004 \u0005[קשה\u0006 הדיוק מ\u0005סוף\u0006 המשנה\u0005].\u0006","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004פי דעת \u0003ר' זירא,\u0004 המדייק כשמואל, \u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 ממנה משמע כי לדעת ר' טרפון שמן שנדב מתחלק לכהנים, מדברת \u0003בשירים,\u0004 ואילו \u0003סיפא\u0004 \u0005[סופה]\u0006 ממנה משמע כי לדעתו מקטירים את השמן, מדבר \u0003בקומץ.\u0004 \u0003אלא לאביי קשיא\u0004 \u0005[קשה]\u0006 מתחילת המשנה! ומשיבים: לדעתו אין לדייק משם, שכן \u0003תנא רישא אטו סיפא\u0004 \u0005[שנה\u0006 את \u0005ראשה משום\u0006 ששנה כך את \u0005סופה],\u0006 והוא מסגנון המשנה.","ומקשים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003סיפא תני משום רישא\u0004 \u0005[סופה\u0006 של משנה \u0005שונה\u0006 התנא \u0005משום ראשה],\u0006 שחוזר על דבריו באותו אופן. \u0003אלא רישא משום סיפא מי תני\u0004 \u0005[ראשה משום סופה האם שונה]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 וכך \u0003אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]:\u0006 \u0003תנא רישא משום סיפא\u0004 \u0005[שנה ראשה משום סופה].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לענין זה ממה ששנינו בברייתא: המתנדב \u0003יין, כדברי ר' עקיבא,\u0004 שאמר שמתנדבים יין — הריהו ניתן \u0003לספלים\u0004 שבקרן המזבח. המתנדב \u0003שמן כדברי ר' טרפון\u0004 שאמר שניתן להתנדב שמן — הריהו ניתן \u0003לאישים. מאי לאו\u0004 \u0005[האם לא]\u0006 נדייק כי \u0003מ\u0004תוך ש\u0003יין כולו לספלים, שמן\u0004 גם כן \u0003כולו לאישים,\u0004 שלא כדברי שמואל? ודוחים: \u0003מידי איריא\u0004 \u0005[וכי הדברים שייכים]?\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כפי שהוא וזה כפי שהוא].\u0006","\u0003אמר רב פפא,\u0004 דברי שמואל שנויים \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 ששנינו בברייתא: המתנדב \u0003שמן לא יפחות מלוג, רבי אומר: שלשת לוגין.\u0004 ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון הם \u0005חלוקים]?\u0006 \u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב פפא:\u0004 בשאלה האם נוקטים במדרש ההלכה בשיטה של \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה],\u0006 שאם יש היקש או גזירה שווה לומדים מן המלמד על הלמד לכל ענין שיש במלמד, או \u0003דון מינה ואוקי באתרה\u0004 \u0005[דון ממנה והעמד במקומה],\u0006 שלמדים רק לענין אחד שיש צורך ללומדו מן המלמד, ולא לשאר דברים שניתן להסיק אותם מגופו של הלמד, \u0003איכא בינייהו\u0004 \u0005[יש\u0006 מחלוקת \u0005ביניהם].\u0006","\u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]\u0006 שיש ללמוד בשיטת \"דון מינה ומינה\": \u0003מה מנחה מתנדבין אף שמן מתנדבין\u0004 (כפי שלמדנו לעיל מ\"קרבן מנחה\"), \u0003[ומינה\u0004 \u0005[ו\u0006נמשיך ללמוד \u0005ממנה]:\u0006 \u0003מה\u0004 המתנדב \u0003מנחה\u0004 מביא עמה \u0003לוג שמן, אף כאן\u0004 כשמתנדב שמן בלבד — \u0003לוג שמן. ו\u0004עוד, \u0003מה מנחה קומצה\u0004 (קומץ אותה) \u0003ושיריה נאכלין,\u0004 וכדברי שמואל, \u0003אף שמן קומצו\u0004 (קומץ אותו) \u0003ושיריו נאכלין.\u0004","\u0003ואידך\u0004 \u0005[והאחר,\u0006 רבי\u0005],\u0006 לומד בשיטת \"דון מינה ואוקי באתרה\": דון \u0003ממנחה, מה מנחה מתנדבין אף שמן מתנדבין. ו\u0004אולם לגבי פרטי ההלכה הריהו \u0003אוקי באתרה\u0004 \u0005[מעמיד\u0006 את דינה של נדבת שמן \u0005במקומה]\u0006, \u0003כ\u0004דין \u0003נסכים, מה נסכים\u0004 מתנדבים \u0003שלשת לוגין\u0004 — \u0003[\u0004\u0003אף שמן\u0004 זה שמנסכים על המזבח — \u0003שלש לוגין,\u0004 ועוד, \u0003מה נסכים כולן\u0004 נשפכים \u0003לספלין]\u0004 — \u0003אף שמן כולן לאישים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אי ממנחה מייתי לה\u0004 \u0005[אם ממנחה מביא,\u0006 למד, \u0005אותה]\u0006 \u0003[רבי]\u0004 לא היה חולק על חכמים, שכן \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 למדים בשיטת \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה].\u0006 \u0003אלא רבי מ\"אזרח\" גמר לה\u0004 \u0005[למד אותה]\u0006 שבסוף פרשת הנסכים נאמר: \"כל האזרח יעשה ככה את אלה להקריב אשה לה'\", (במדבר טו, יג), שכשם שניתן להתנדב יין לנסכים, כן ניתן להתנדב שמן. ובדרך של \"דון מינה ומינה\" הוא למד מיין שנדבת שמן הריהי שלושה לוגים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא: מי מצית אמרת הכי\u0004 \u0005[האם יכול אתה לומר כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"קרבן מנחה\"\u0004 (ויקרא ב, א) — \u0003מלמד שמתנדבין שמן, וכמה? שלשה לוגין. ומאן שמעת ליה\u0004 \u0005[ומי שמעת אותו]\u0006 ש\u0003אמר שלשה לוגין? רבי היא, וקא מייתי לה\u0004 \u0005[ו\u0006הוא \u0005מביא,\u0006 למד, \u0005אותה]\u0006 \u0003מ\"קרבן\"! אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003אי תניא תניא\u0004 \u0005[אם שנויה\u0006 ברייתא \u0005שנויה],\u0006 וחוזר אני מדברי.","\u0003אמר שמואל: המתנדב יין, מביא ומזלפו על גבי האישים. מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ויין תקריב לנסך חצי ההין אשה ריח ניחח לה'\"\u0004 (במדבר טו, י), הרי שיש יין שהוא \"אשה\" — לאישים. ומקשים: \u0003והא קא מכבי\u0004 \u0005[והרי הוא מכבה]\u0006 על ידי זה את האש, ונאמר: \"אש תמיד תוקד על המזבח לא תכבה\" (ויקרא ו, ו)! ומשיבים: \u0003כיבוי במקצת לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003כיבוי\u0004 שנאסר בכתוב.","ומקשים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר רבה בר אבוה: המוריד גחלת מעל גבי המזבח וכיבה\u0004 — \u0003חייב\u0004 משום \"לא תכבה\"! ודוחים: מדובר שם \u0003דליכא\u0004 \u0005[שאין]\u0006 על המזבח \u0003אלא האי\u0004 \u0005[\u0006גחלת \u0005זו]\u0006 ונמצא שמכבה כל מה שנמצא. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: גם אם כיבוי במקצת נאסר, \u0003כיבוי\u0004 של \u0003מצוה,\u0004 כגון על ידי ניסוך יין, \u0003שאני\u0004 \u0005[שונה],\u0006 שהוא מותר.","ומקשים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 סתירה לתירוץ זה, ממה \u0003דתנא\u0004 \u0005[ששנה]\u0006 \u0003ר' אליעזר בן יעקב: כלפי\u0004 (מאחר) \u0003שנתנה תורה\u0004 מצוה \u0003לתרום\u0004 מן הדשן, והם גחלים שנתאכלו ונגמרה בעירתם, \u0003יכול יכבה\u0004 גחלת \u0003ויתרום? אמרת: לא יכבה\u0004 שנאמר \"לא תכבה\" (ויקרא ו, ו). משמע איפוא שאף לצורך מצוה אסור כיבוי במקצת! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 שכן \u0003אפשר\u0004 לו לכהן \u0003דיתיב ונטר\u0004 \u0005[שישב וישמור,\u0006 ישגיח\u0005]\u0006 עד שיהפוך חלק מן הגחלים לאפר, ואז יתרום. אבל בזילוף היין לא תועיל ההמתנה, ולכן מותר הדבר.","ומקשים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שאין מזלפים את היין על גבי האש, ממה ששנינו בברייתא: \u0003יין\u0004 של נדבה \u0003כדברי ר' עקיבא\u0004 נשפך \u0003לספלים, שמן כדברי ר' טרפון\u0004 נשפך \u0003לאישים! ועוד תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יין נסך\u0004 נשפך \u0003לספלים.\u0004 ויש לשאול: \u0003או אינו אלא לאישים? אמרת: לא יכבה!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 כשיטת \u0003ר' יהודה\u0004 הסבור כי גם דבר שאין מתכוון לו — אסור, \u0003הא\u0004 \u0005[זהו\u0006 שאמר שמואל\u0005]\u0006 כשיטת \u0003ר' שמעון\u0004 הסבור שדבר שאין מתכוון לו — מותר. ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן ש\u0003שמואל כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: מכבין גחלת\u0004 (חתיכה לוהטת) \u0003של מתכת ברשות הרבים\u0004 בשבת \u0003בשביל שלא יזוקו בה רבים,\u0004"],["\u0003אבל לא גחלת של עץ,\u0004 מפני שיש בה מלאכת כיבוי מן התורה. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי שמואל \u0003כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא]\u0006 — \u0003אפילו גחלת של עץ נמי\u0004 \u0005[גם כן]\u0006 יכבה, כי לדעת ר' שמעון אין חיוב מלאכת כיבוי אלא כאשר רוצה להשתמש בגחלת עצמה כשהיא כבויה. ואם לא — הרי זו מלאכה שאינה צריכה לגופה, ובזה פוטר ר' שמעון!","ומשיבים: אין זו סתירה, כי \u0003בדבר שאין מתכוין סבר לה\u0004 \u0005[סבור הוא]\u0006 שמואל \u0003כר' שמעון,\u0004 אבל \u0003במלאכה שאינה צריכה לגופה סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יהודה,\u0004 שמחייב עליה בשבת.","\u0003אמר רב הונא: נסכים שנטמאו, עושה להן מערכה\u0004 של עצים \u0003בפני עצמן ושורפן\u0004 שם, ואינו שורף אותם מחוץ לעזרה. \u0003משום שנאמר\u0004 לגבי חטאת שנפסלה: \u0003\"בקדש ... באש תשרף\"\u0004 (ויקרא ו, כג), ומריבוי הכתובים למדו שהוא הדין לכל דבר שצריך להקריבו על המזבח ונפסל. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הדם והשמן והמנחות והנסכים שנטמאו, עושה להן מערכה בפני עצמן ושורפן.\u0004 מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב חנא בגדתאה\u0004 \u0005[מבגדד]:\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003לי בי\u0004 \u0005[בית,\u0006 מנין\u0005]\u0006 \u0003עשרה\u0004 אנשים, לפרסום הדבר, \u0003ואימא\u0004 \u0005[ואומר]\u0006 \u0003לך קמייהו\u0004 \u0005[בפניהם]:\u0006 \u0003נסכים שנטמאו, עושה להן מערכה בפני עצמן ושורפן.\u0004","","","\u0003דם\u0004 קרבן \u0003חטאת\u0004 העומד להזאה \u0003שנתז על הבגד\u0004 — \u0003הרי זה טעון\u0004 (חייב) \u0003כיבוס,\u0004 שכן נאמר בתורה בדין החטאת: \"ואשר יזה מדמה על הבגד אשר יזה עליה תכבס במקום קדוש\" (ויקרא ו, כ). ו\u0003אף על פי שאין הכתוב\u0004 הזה \u0003מדבר אלא ב\u0004חטאות \u0003נאכלות\u0004 שמזים מדמן במזבח החיצון, \u0003ש\u0004הרי כך \u0003נאמר\u0004 בפסוק שלפניו: \u0003\"במקום קדוש תאכל\"\u0004 (ויקרא ו, יט), מכל מקום \u0003אחד הנאכלות ואחד הפנימיות\u0004 שמזים מדמן על המזבח הפנימי, שהן נשרפות כליל ואינן נאכלות, \u0003טעונות כיבוס\u0004 אם ניתז מהם על הבגד, \u0003שנאמר\u0004 בתחילת אותה פרשה: \"זאת \u0003תורת החטאת\"\u0004 (ויקרא ו, יח), ללמד: \u0003תורה אחת\u0004 (דין שווה) \u0003לכל החטאות.\u0004","וכל זה אמור דווקא בחטאות כשרות, אבל \u0003חטאת פסולה\u0004 — \u0003אין דמה טעון כיבוס, בין שהיתה לה שעת הכושר\u0004 שהיה דמה ראוי להיזרק, ורק אז נפסלה, \u0003ובין שלא היתה לה שעת הכושר. איזו היא\u0004 חטאת פסולה \u0003שהיתה לה שעת הכושר? ש\u0004לאחר שנשחטה ונתקבל דמה כראוי \u0003לנה\u0004 נפסלה בלינה, \u0003ושנטמאה\u0004 החטאת, \u0003ושיצאת\u0004 (שיצאה) דמה או בשרה אל מחוץ לעזרה. \u0003ואיזו היא\u0004 חטאת \u0003שלא היתה לה שעת הכושר? שנשחטה\u0004 במחשבה שיזרק דמה או יאכל בשרה \u0003חוץ לזמנה\u0004 הראוי, \u0003וחוץ למקומה\u0004 הראוי. וכן זו \u0003שקיבלו פסולין\u0004 לעבודה \u0003(וזרקו) את דמה.\u0004","שנינו במשנה כי \u0003דם חטאת (שמתה) [שנתז]\u0004 על הבגד — הריהו חייב בכיבוס, בין חטאת הנאכלת ובין חטאת שאינה נאכלת, שנאמר \"זאת תורת החטאת\" (ויקרא ו, יח) — תורה אחת לכל החטאות. ושואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003תורה אחת לכל חטאות,\u0004 אם כן \u0003אפילו חטאת העוף נמי\u0004 \u0005[גם כן]\u0006 יהיה דמה טעון כיבוס! \u0003אלמה תניא\u0004 \u0005[מדוע שנה\u0006 בברייתא\u0005]:\u0006 \u0003יכול תהא דם חטאת העוף טעון כיבוס? תלמוד לומר: \"זאת\u0004 תורת החטאת\" (ויקרא ו, יח) שהוא לשון מיעוט, זאת ולא אחרת, דווקא בחטאת בהמה נוהג דין זה, ולא בחטאת העוף! \u0003אמר ריש לקיש משום\u0004 (בשם) \u0003בר קפרא: אמר קרא\u0004 \u0005[הכתוב]\u0006 בפסוק זה: \"זאת תורת החטאת... \u0003תשחט\u0004 החטאת\", ללמדנו שדווקא \u0003ב\u0004חטאות ה\u0003נשחטות הכתוב מדבר,\u0004 ולא בחטאת העוף, שהיא נמלקת ואינה נשחטת.","","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ודייק באופן אחר: דווקא \u0003בנאכלות הכתוב מדבר, כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"במקום קדוש תאכל\"\u0004 (ויקרא ו, יט), \u0003אבל פנימיות\u0004 שאינן נאכלות — \u0003לא!\u0004 ומשיבים: \u0003רבי רחמנא\u0004 \u0005[ריבתה התורה]\u0006 \u0003\"תורת\u0004 החטאת\" לרבות כל החטאות, גם שאינן נאכלות.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שיש כאן ריבוי, \u0003אפילו חטאת העוף נמי\u0004 \u0005[גם כן]\u0006 תיכלל בריבוי זה! ומשיבים: \u0003מיעט רחמנא\u0004 \u0005[הכתוב]\u0006 על ידי המלה \u0003\"זאת\"\u0004 את חטאת העוף.","ושואלים: \u0003ומה ראית\u0004 לרבות את הפנימיות ולמעט את חטאת העוף, ולא להיפך, לרבות את חטאת העוף ולמעט את הפנימיות? ומשיבים: הואיל וצריך למעט ולרבות, ומן הכתוב יש ראיה לכאן ולכאן, \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 יותר לומר ש\u0003חטאת [בהמה] פנימיות הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 שהן דומות לחטאות החיצוניות בכמה צדדים, \u0003שכן\u0004 אלו ואלו באות ממין ה\u0003בהמה,\u0004 וטעונות ב\u0003שחיטת צפון\u0004 (בצפון העזרה), \u0003וקבלת\u0004 דמן ב\u0003כלי,\u0004"],["\u0003ו\u0004מזה מדמן על \u0003קרן\u0004 המזבח, \u0003ו\u0004ב\u0003אצבע\u0004 הכהן, \u0003ו\u0004ההזאה נעשית על \u0003חודה\u0004 של קרן המזבח, \u0003ו\u0004אלו ואלו אימוריהן ניתנים על ה\u0003אישים.\u0004 מה שאין כן בחטאת העוף.","ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 נאמר שדווקא את \u0003חטאת העוף הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 ולהשוות דינה לחטאת הנאכלת, \u0003שכן\u0004 היא נעשית ב\u0003חוץ\u0004 (במזבח החיצון) \u0003כמותה, ו\u0004יש בה \u0003אכילה כמותה!\u0004 ודוחים: \u0003הנך נפישין\u0004 \u0005[אלה,\u0006 של החטאות הפנימיות, \u0005מרובים\u0006 יותר\u0005].\u0006","\u0003רב יוסף אמר:\u0004 יש ראיה אחרת למעט דם חטאת העוף מכלל דין כיבוס, שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בפרשה העוסקת בענין זה של כיבוס: \"הכהן המחטא אותה \u0003יאכלנה\"\u0004 (ויקרא ו, יט), ויש בכך לשון הדגשה: דווקא \u0003לזו ולא לאחרת,\u0004 ומכאן למדנו כי \u0003ב\u0004תוך החטאות ה\u0003נאכלות מיעט הכתוב,\u0004 שבאחת מהן אין הלכות אלו נוגעות, והיא חטאת העוף.","ושואלים: \u0003ואלא,\u0004 אם מכאן למדים, המיעוט של חטאת העוף מ\u0003\"זאת\u0004 תורת החטאת\" (ויקרא ו, יח) \u0003למה לי?\u0004 ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא\u0006 היה כתוב\u0005]\u0006 \u0003\"זאת\", הוי אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003\"יאכלנה\" אורחיה דקרא\u0004 \u0005[דרכו של המקרא]\u0006 הוא זה, ואין כאן הדגשה שזו ולא אחרת, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \"זאת\" שיש למעט, והכתוב \"יאכלנה\" מלמדנו שהמיעוט הוא בין החטאות הנאכלות דווקא.","\u0003רבה אמר\u0004 הסבר אחר: אין למעט חטאות הפנימיות מדין כיבוס, משום שאדרבה, דווקא בהן עוסק הכתוב, ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בפרשה זו: \u0003\"אשר יזה\u0004 מדמה\" (ויקרא ו, כ), והרי זה מורה ש\u0003ב\u0004חטאות שיש בהן \u0003הזאות הכתוב מדבר,\u0004 ולשון הזאה נזכרת דווקא בחטאות הפנימיות (ויקרא ד, ו ועוד), ואילו בחיצוניות נזכרה לשון \"ונתן\" (ויקרא ד, כה).","ומקשים: כיצד יכול אתה לפרש שבהן דווקא עוסק הכתוב? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 משנתנו\u0005]:\u0006 \u0003אף על פי שאין הכתוב מדבר אלא בנאכלות!\u0004 ומשיבים: דברים אלה נאמרו רק \u0003לענין\u0004 דין \u0003מריקה ושטיפה\u0004 של כלי נחושת שהתבשלה בו חטאת (ויקרא ו, כא), שהוא אכן שייך רק בחטאות הנאכלות, שמבשלים את בשרן, \u0003אבל לענין כיבוס\u0004 דם החטאת מן הבגד — \u0003\"אשר יזה\u0004 עליה תכבס\" \u0003כתיב\u0004 \u0005[כתוב],\u0006 ובפנימיות מדובר, ואין הנאכלות נלמדות אלא מן הריבוי \"תורת החטאת\".","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שעיקר דין כיבוס נאמר בחטאות הפנימיות, מה ששנינו במשנתנו: \u0003\"אחד הנאכלות ואחד הפנימיות\u0004 טעונות כיבוס\" אינו מדוייק, שהרי משמע מכך שהנאכלות הן העיקר, ונוספו עליהן הפנימיות מריבוי הכתוב. אלא \u0003\"אחד הפנימיות ואחד הנאכלות\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומשיבים: אכן, \u0003תני\u0004 \u0005[שנה]\u0006 כך: \u0003\"אחד הפנימיות ואחד הנאכלות\".\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שדין כיבוס שבכתוב נאמר בחטאות שנאמרה בהן הזאה, אם כן \u0003חטאת העוף נמי\u0004 \u0005[גם כן]\u0006 בכלל זה, שהרי נאמרה בה לשון הזאה (ויקרא ה, ט)! ומשיבים: \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה\u0006 אותן\u0005]\u0006 על ידי המלה \u0003\"זאת\u0004 תורת החטאת\" (ויקרא ו, יח). ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שיש מיעוט, חטאת \u0003חיצונה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא!\u0004 ומשיבים: \u0003ריבה רחמנא\u0004 \u0005[ריבתה התורה]\u0006 \u0003\"תורת\".\u0004","ושואלים: \u0003ומה ראית\u0004 למעט חטאת העוף ולרבות חטאת חיצונה? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 \u0003חטאת בהמה הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 \u0003שכן\u0004 יש בה צדדים רבים של דמיון לחטאת הפנימית: שהיא \u0003בהמה\u0004 כמותה, וטעונה \u0003שחיטת צפון, וקבלת\u0004 דמה ב\u0003כלי, ו\u0004מתן דם על \u0003קרן, ו\u0004נתינת הדם ב\u0003אצבע, ו\u0004מתן דם על \u0003חודה\u0004 של הקרן, \u0003ו\u0004הקטרת האימורים על \u0003אישים,\u0004 מה שאין כן בעוף.","ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003חטאת העוף הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 \u0003שכן\u0004 יש בה \u0003הזאה כמותה!\u0004 ומשיבים: \u0003הנך נפישין\u0004 \u0005[אלה,\u0006 צדדי הדמיון לחטאת חיצונה, \u0005מרובים]\u0006 יותר.","אגב שהוזכר דינו של דם חטאת העוף, שאינו צריך קבלה בכלי, אלא מזה בגוף העוף, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבין:\u0004 הלכה היא שדם חטאת החיצונה שהוכנס בכלי שרת להיכל, הריהו נפסל בכך (לעיל זבחים פא,ב). ואולם \u0003חטאת העוף ש\u0004נמלקה ו\u0003הכניס דמה\u0004 כשהוא נתון \u0003בצוארה בפנים, מהו\u0004 דינו? וצדדי השאלה: האם \u0003צוארה\u0004 של חטאת העוף \u0003ככלי שרת דמי\u0004 \u0005[נחשב],\u0006 שהרי כך הוא מזה מדמה, \u0003ו\u0004לכן \u0003מיפסיל\u0004 \u0005[נפסל]\u0006 אם נכנס להיכל.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 דין הדם שבצואר העוף \u0003כ\u0004דין הדם שב\u0003צואר בהמה,\u0004 ובענין זה \"אשר יובא \u0003מדמה\u0004 אל אוהל מועד\" (ויקרא ו, כג) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 שדמה נפסל כשהוא בכלי שרת לעצמו, \u0003ולא\u0004 כשהוא ב\u0003בשרה?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו, ממה ששנינו בברייתא: \u0003פירכסה\u0004 חטאת העוף לאחר שנמלקה, \u0003ו\u0004בתוך כך \u0003נכנסה לפנים\u0004 (להיכל) \u0003וחזרה\u0004 שוב אל העזרה — לא נפסלה בכך, והריהי \u0003כשירה\u0004 להזות מדמה ולאכול מבשרה. ונדייק מכאן: דווקא שנכנסה מעצמה אל ההיכל אין היא נפסלת בכך, \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003הכניסה\u0004 הכהן מדעתו — \u0003פסולה,\u0004 בגלל הדם שבצוארה!","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שיש לדייק כך מלשון זו, \u0003גבי\u0004 \u0005[אצל]\u0006 בהמת \u0003קדשי קדשים דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003פירכסה\u0004 לאחר שנשחטה בצפון העזרה, כדינה, \u0003ויצאה לדרום, וחזרה\u0004 שוב לצפון העזרה — \u0003כשרה,\u0004 האם נדייק ונאמר: \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003הוציאה\u0004 הכהן בעצמו לדרום — \u0003פסולה?\u0004 והרי אין כלל פסול יציאה מצפון העזרה לדרומה!","\u0003אלא\u0004 יש לומר כי \u0003האי\u0004 \u0005[\u0006לשון \u0005זו]\u0006 \"ויצאה\", שהוזכרה שם — לענין בהמה ש\u0003יצתה\u0004 (יצאה) \u0003לחוץ איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 באותה ברייתא, ולהשמיענו כי היא נפסלת בכך, אף אם יצתה מאליה. ואגב כך הוזכרה לשון \"יצאה\" גם בדין זה. \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לשון \"נכנסה\" לענין חטאת העוף, לענין \u0003יצתה לחוץ\u0004 הוא \u0003דאיצטריכא ליה\u0004 \u0005[שהוצרכה לו],\u0006 ללמד שגם אם יצאה מאליה פסולה, ואגב כך הוזכרה לענין כניסה לפנים. ואין איפוא מכאן פתרון לשאלת ר' אבין.","ועוד בענין דם העוף, שאינו מתקבל בכלי, אלא מזה אותו כשהוא אוחז בגוף העוף. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבין:\u0004 שנינו לענין דם בהמה שאם נשפך על הרצפה קודם שנתקבל בכלי שרת הריהו פסול (לעיל זבחים כה,א), אבל אם נשפך לאחר שנתקבל בכלי, ואספו — כשר (לעיל זבחים לב,ב). ויש לשאול: אם \u0003נשפך\u0004 דם העוף \u0003על הרצפה ואספה\u0004 מן הרצפה, \u0003מהו\u0004 דינו?","וצדדי השאלה: האם דם העוף, \u0003אצרוכיה הוא\u0004 ש\u0003לא אצרכיה רחמנא\u0004 \u0005[הצריכה אותו התורה]\u0006 \u0003כלי שרת, והלכך\u0004 אם נשפך — \u0003אוספו\u0004 מן הרצפה \u0003וכשר. או דלמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003מיפסל פסל ביה רחמנא\u0004 \u0005[פסלה בו התורה,\u0006 בעוף\u0005]\u0006 \u0003כלי שרת,\u0004 משום שצריך להזות דווקא מגוף העוף ישירות על המזבח, \u0003והלכך\u0004 גם אם נשפך על הרצפה — \u0003אוספו ופסול?\u0004","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה ששנינו בברייתא: \u0003יכול יהא דם חטאת העוף\u0004 שניתז על הבגד \u0003טעון כיבוס? תלמוד לומר: \"זאת\". ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי \u0003מיפסל פסיל ביה רחמנא\u0004 \u0005[פסלה אותו התורה]\u0006 את דם העוף, אם לא הוזה ישירות על המזבח, \u0003תיפוק\u0004 \u0005[תצא]\u0006 \u0003לי\u0004 הלכה זו, שדם העוף אינו טעון כיבוס, גם בלא הלימוד מ\"זאת\", \u0003דהא אפסיל לה\u0004 \u0005[שהרי\u0006 כבר \u0005נפסל]\u0006 משעה שהוא נמצא \u0003באויר\u0004 ה\u0003כלי\u0004 (הבגד), עוד קודם שנגע בכלי עצמו, ודם פסול אינו טעון כיבוס!","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 אין מכאן ראיה, שכן גם אם דם העוף נפסל באויר הבגד, עדיין יש צורך במיעוט \"זאת\", למקרים שדם העוף אינו נפסל תחילה באויר הכלי, כגון \u0003במדביק כלי בצוארה\u0004 של העוף. ולא נפשטה, איפוא, שאלתו של ר' אבין.","ושבים לעיקר דין משנתנו, בדין דם חטאת בהמה שטעון כיבוס. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003לוי\u0004 מר' יהודה הנשיא: \u0003ניתז\u0004 דם חטאת \u0003מבגד לבגד, מהו? מבגד קמא אידחי ליה לכיבוס\u0004 \u0005[\u0006האם משעה שנפל \u0005מן הבגד הראשון נדחה\u0006 מן הדם דין \u0005כיבוס],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003זו שאלה\u0004 יפה, והתשובה: \u0003טעון כיבוס, ממה נפשך\u0004 \u0005[מאיזה צד\u0006 ש\u0005רצונך\u0006 לבחון זאת\u0005],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר כי דם שניתז על הבגד \u0003אוספו וכשר\u0004 להזאה, \u0003הא\u0004 \u0005[זה]\u0006 שניתז על בגד אחר — \u0003כשר\u0004 גם הוא, וטעון כיבוס. \u0003ו\u0004גם \u0003אי\u0004 \u0005[אם]\u0006 תאמר שכשניתז על הבגד הראשון \u0003אוספו ופסול\u0004 — מכל מקום \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כר' עקיבא סבירא לי\u0004 \u0005[סבורני],\u0006 ש\u0003אמר:\u0004 כל דם ש\u0003היתה לו שעת הכושר ונפסלה\u0004 — \u0003דמה טעון כיבוס,\u0004 והרי דם זה היה בכלי שרת תחילה קודם שניתז על הבגד, והיתה לו שעת הכושר."],["ועוד בענין זה \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רמי בר חמא מרב חסדא:\u0004 אם \u0003ניתז\u0004 דם החטאת \u0003על בגד טמא\u0004 ונטמא בכך, ונפסל להזאה, \u0003מהו\u0004 דינו, האם חייב בכיבוס? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: מדקמיבעיא ליה הכי\u0004 \u0005[מ\u0006כיון \u0005שנשאלה לו\u0006 לרמי בר חמא \u0005כך],\u0006 כשהדם נטמא כאשר ניתז על הבגד, ולא שאל על מקרה של דם שכבר היה טמא קודם שניתז על הבגד, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהוא סבור כי גם אם \u0003היתה לה\u0004 לחטאת \u0003שעת הכושר ו\u0004רק לאחר מכן \u0003נפסלה\u0004 — \u0003אין דמה טעון כיבוס,\u0004 והשאלה שלו היתה איפוא: האם","\u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא כאשר היו הדברים \u0003בזה אחר זה,\u0004 שתחילה נפסלה החטאת, ואחר כך ניתז דמה על הבגד, \u0003אבל\u0004 אם התרחשו הדברים \u0003בבת אחת\u0004 כגון במקרה זה, בו ניתז הדם על הבגד ונטמא בו זמנית — \u0003לא,\u0004 וחל דין כיבוס על הדם. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היו הדברים בבת אחת או בזה אחר זה, אלא הואיל ונפסל הדם כשהוא נוגע בבגד — אינו ראוי לכיבוס? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר חמא בתשובה לשאלתו: פתרון השאלה תלוי ב\u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' אלעזר ורבנן אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003רבה\u0004 בהסבר מחלוקת זו, \u0003וכדקא מתריץ\u0004 \u0005[וכפי שמתרץ,\u0006 מיישב\u0005]\u0006 \u0003אביי\u0004 את הדברים.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: מי חטאת\u0004 הבאים לטהר אדם מטומאת מת, \u0003שנטמאו,\u0004 בכל זאת הריהם \u0003מטהרין\u0004 את האדם מטומאתו. וראיה לדבר, \u0003שהרי\u0004 אשה \u0003נדה\u0004 שנטמאה בטומאת המת, \u0003מזין עליה\u0004 ממי החטאת אף שהיא טמאת נדה, ומי החטאת נטמאים כשהם נוגעים בה.","\u0003ואמר רבה:\u0004 אף על פי שלכאורה אין הדברים דומים, שהרי בנדה לא נטמאו מי החטאת קודם שנגעו בגופה, ואין מכאן ראיה למי חטאת שנטמאו קודם לכן — \u0003ר' אלעזר\u0004 סבור שמי החטאת נטמאו עוד קודם שטיהרו את הנדה, כשהיו מעל גופה, שכן \u0003בשיטת ר' עקיבא רבו אמרה,\u0004 שכך \u0003אמר\u0004 ר' עקיבא: \u0003העברת כלי\u0004 של מי חטאת \u0003על גבי מקום טמא\u0004 — \u0003כ\u0004אילו \u0003מונח\u0004 הכלי באותו מקום \u0003דמי\u0004 \u0005[נחשב הוא],\u0006 ומי החטאת נטמאים. ומנין שכך סבור ר' עקיבא?","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003היה\u0004 אדם טהור \u0003עומד חוץ\u0004 (מעבר) \u0003לתנור\u0004 שהתנור מפריד בינו לבין קיר הבית, \u0003ושרץ\u0004 מטמא מונח \u0003בתנור, והושיט\u0004 האדם את \u0003ידו לחלון\u0004 שבקיר הבית \u0003ונטל את הלגין\u0004 (כלי ובו מי חטאת) \u0003והעבירו\u0004 מ\u0003על פי\u0004 ה\u0003תנור\u0004 (המצוי בחלקו העליון של התנור) — \u0003ר' עקיבא מטמא\u0004 את מי החטאת שבלגין, אף שלא הונח הלגין על התנור, אלא רק עבר מעליו, \u0003וחכמים מטהרין. ו\u0004לשיטת רבה, \u0003בהא פליגי\u0004 \u0005[בזה\u0006 הם \u0005חלוקים],\u0006 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 כי הכלי ובו מי החטאת הריהו \u0003כמונח\u0004 עליו \u0003דמי\u0004 \u0005[נחשב],\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כמונח\u0004 \u0003דמי\u0004 \u0005[נחשב].\u0006 ור' אלעזר בענין הזאה על נדה, סבור כר' עקיבא, ולכן הוא מוכיח את דבריו ממי החטאת שנטמאו כשעברו מעל הנדה.","\u0003ואיתיביה\u0004 \u0005[והקשה לו]\u0006 \u0003אביי\u0004 לרבה על הסברו זה ממה ששנינו בברייתא: אף על פי שר' עקיבא מטמא את מי החטאת כשהם מונחים בלגין קודם הזאה, \u0003מודה ר' עקיבא בהזאה\u0004 עצמה, \u0003ש\u0004אם תוך כדי הזאה על טמא מת \u0003העבירה\u0004 מ\u0003על כלי חרס טמא,\u0004 או מ\u0003על גבי משכב ומושב טמא\u0004 — \u0003שהיא טהורה,\u0004 משום \u0003שאין לך דבר שמטמא\u0004 את מה שנמצא בחלל ש\u0003למעלה\u0004 ממנו \u0003כלמטה, אלא\u0004 רק \u0003כזית מן המת, ושאר כל המאהילין\u0004 המטמאים דבר המאהיל עליהם. ומעירים: לשון (\"כל המאהילין\") באה \u0003לאיתויי\u0004 \u0005[לרבות]\u0006 \u0003אבן המנוגעת\u0004 בצרעת הבתים, שאף היא מטמאה באוהל!","\u0003אלא אמר אביי\u0004 הסבר אחר במחלוקת ר' עקיבא וחכמים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 כלי ובו מי חטאת העובר על מקום טמא — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כמונח דמי\u0004 \u0005[נחשב],\u0006 \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים]\u0006 ש\u0003ר' עקיבא סבר: גזרינן\u0004 \u0005[גוזרים אנו]\u0006 טומאה על הכלי העובר שיהא טמא \u0003שמא ינוח\u0004 הכלי על התנור, שאז הוא נטמא בוודאות. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 גזירה זו. \u0003ומודה ר' עקיבא ב\u0004מי \u0003הזאה\u0004 שעברו מעל דבר טמא, שאין מקום לגזירה זו, שהרי \u0003כיון דנפק נפק\u0004 \u0005[כיון שיצא\u0006 מתחת ידו של הכהן, כבר \u0005יצא]\u0006 ושוב אין הוא יכול להניחה היכן שירצה, ולכן אין חשש שיניחנה במקום הטמא.","ושואלים: לפי הסבר זה של אביי, נמצא כי לדעת הכל, מי חטאת שהוזו על הנדה, אינם נטמאים קודם שהם מטהרים אותה, \u0003ו\u0004אם כן \u0003ר' אלעזר ורבנן\u0004 \u0005[וחכמים],\u0006 שנחלקו האם מי חטאת שנטמאו מטהרים, \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 \u0003אמר אביי: ב\u0004שאלה האם \u0003דנין\u0004 (למדים) דינה של \u0003טומאה קדומה\u0004 (קודמת) כגון מי חטאת שנטמאו מתחילה, \u0003מטומאה ש\u0004חלה על מי החטאת \u0003באותה שעה\u0004 שהם מטהרים (כפי שהוא בנדה שמזים עליה) \u0003קמיפלגי\u0004 \u0005[הם חלוקים].\u0006","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר, \u0005סבור]:\u0006 \u0003דנין,\u0004 והם מטהרים כמותם, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003אין דנין.\u0004 והוא מה שהשיב רב חסדא על שאלת רמי בר חמא לענין דם חטאת שניתז על בגד טמא, ששאלה זו תלויה במחלוקת זו של ר' אלעזר וחכמים: לר' אלעזר דינו של דם שנטמא בשעת מגע בבגד כדינו של דם שנטמא קודם לכן, ואינו טעון כיבוס. ולדעת חכמים אין למדים זה מזה, ולכן כשנטמא בשעת המגע בבגד הריהו טעון כיבוס.","\u0003רבא אמר:\u0004 אין להוכיח מכאן לענייננו, שכן \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין דנין\u0004 טומאה קדומה מטומאה שבאותה שעה, וגם לא לדעת ר' אלעזר.","\u0003והכא\u0004 \u0005[וכאן],\u0006 שנחלקו האם יש ללמוד מנדה שנטהרת בהזאה, שמי חטאת שנטמאו מטהרים, \u0003בהא קמיפלגי\u0004 \u0005[בזה הם חולקים],\u0006 \u0003ר' אלעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003הזאה\u0004 של מי חטאת \u0003צריכה שיעור, ו\u0004מכל מקום \u0003מצטרפין\u0004 (מצרפים) \u0003להזאות\u0004 יחד, להשלים לשיעור הזאה כדי לטהר את הטמא. ולכן אם בהזאה הראשונה על הנדה לא היה שיעור הזאה, הרי כבר נטמאה אותה הזאה. והואיל ולדעת ר' אלעזר היא מצטרפת להזאה השניה לטהר את הנדה, נמצא שמי חטאת שנטמאו מטהרים את הנדה. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ש\u0003הזאה אין צריכה שיעור\u0004, ובהזאה הראשונה כבר נטהרת הנדה, והרי זו טומאה שחלה על מי החטאת באותה שעה שהם מטהרים. ואין ללמוד ממנה למקרה בו היו טמאים מתחילה.","שנינו במשנה: \u0003חטאת פסולה\u0004 אין דמה טעון כיבוס, בין שהיתה לה שעת הכושר קודם שנפסלה, ובין שלא היתה לה שעת הכושר. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 זה שנאמר בדין כיבוס דם החטאת: \"ואשר יזה \u0003מדמה\u0004 על הבגד\" (ויקרא ו, כ) בא למעט: דווקא כשהוזה \u0003מדם\u0004 חטאת \u0003כשירה, ולא מדם\u0004 חטאת \u0003פסולה. ר' עקיבא אומר:\u0004 יש להבחין: אם \u0003היתה לה שעת הכושר\u0004 שהיתה כשרה בשלב כלשהו, \u0003ונפסלה\u0004 — \u0003דמה טעון כיבוס, לא היתה לה\u0004 כלל \u0003שעת הכושר, ונפסלה\u0004 — \u0003אין דמה טעון כיבוס.\u0004","\u0003ור' שמעון אומר: אחד זה ואחד זה,\u0004 גם זו שהיתה לה שעת הכושר, מאחר שנפסלה — \u0003אין דמה טעון כיבוס.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון?\u0004 ומשיבים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפרשת החטאת, שנזכר בה דין כיבוס הדם: \"כל זכר בכהנים יאכל \u0003אותה\"\u0004 (ויקרא ו, כב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 עוד באותה פרשה \u0003\"מדמה\"\u0004 (ויקרא ו, כ), הרי אלו שני מיעוטים: \u0003חד\u0004 \u0005[\u0006מקרא \u0005אחד]\u0006 בא למעט \u0003להיכא\u0004 \u0005[למקום]\u0006 ש\u0003היתה לו\u0004 לדם החטאת \u0003שעת הכושר,\u0004 ואחד למקרה שלא היתה שעת הכושר.","\u0003ור' עקיבא,\u0004 מה הוא משיב לכך? לדעתו יש רק מיעוט אחד לחטאת פסולה, הנלמד מהכתוב \"מדמה\" והוא מלמד על זו שלא היתה לה כלל שעת הכושר. ואילו המיעוט הנלמד מ\u0003\"אתה\"\u0004 בא ללמד בענין מריקה ושטיפה של כלי נחושת שבושלה בו החטאת — \u0003פרט לתרומה,\u0004 שאם נתבשלה — אין בכלי שנתבשלה בו דין מריקה ושטיפה. \u0003ור' שמעון\u0004 שאינו דורש כך, הרי זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: קדשים קלים\u0004 שנתבשלו \u0003אין טעונין\u0004 דין \u0003מריקה ושטיפה\u0004 כפי שיבואר להלן (זבחים צו,ב), \u0003וכל שכן תרומה.\u0004 ולפיכך אין צורך בכתוב מיוחד למעט תרומה מדין זה, ולכן הוא ממעט מ\"אותה\" חטאת פסולה.","\u0003ניתז\u0004 דם החטאת \u0003מן הצואר\u0004 של הבהמה \u0003על הבגד\u0004 — \u0003אינו טעון כיבוס.\u0004 נתקבל הדם בכלי וניתן על המזבח, וניתז \u0003מן הקרן ומן היסוד\u0004 על הבגד — \u0003אינו טעון כיבוס,\u0004 שהרי כבר הוזה הדם ונתקיימה מצוותו. אם \u0003נשפך\u0004 הדם מצוואר הבהמה \u0003על הרצפה\u0004 קודם שנתקבל בכלי, \u0003ואספו\u0004 הכהן וניתז הדם על הבגד — \u0003אין\u0004 הדם \u0003טעון כיבוס. אין\u0004 דם הנבלע בבגד \u0003טעון כיבוס אלא דם שנתקבל בכלי\u0004 שרת, \u0003וראוי\u0004 (ועומד) \u0003להזאה.\u0004","ומביאים מקור לדינים שהובאו במשנתנו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול ניתז\u0004 דם \u0003מן הצואר על הבגד יהא טעון כיבוס? תלמוד לומר\u0004 בענין זה: \u0003\"אשר יזה\"\u0004 (ויקרא ו, כ), \u0003לא אמרתי לך\u0004 דין זה של כיבוס \u0003אלא ב\u0004דם ה\u0003ראוי להזאה\u0004 בלבד, שנתקבל בכלי. ועוד \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003יכול ניתז מן הקרן ומן היסוד יהא טעון כיבוס? תלמוד לומר: \"אשר יזה\"\u0004 (ויקרא ו, כ) — \u0003פרט לזה שכבר הוזה.\u0004","שנינו במשנה: \u0003נשפך\u0004 הדם \u0003על הרצפה\u0004 ואספו הכהן, וניתז על הבגד — אינו טעון כיבוס. ועוד שנינו: אין טעון כיבוס אלא דם שנתקבל בכלי וראוי להזאה."],["ויש לשאול: \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו],\u0006 שאין טעון כיבוס אלא דם שהתקבל בכלי וראוי להזאה, \u0003תו\u0004 \u0005[עוד\u0006 בנוסף\u0005]\u0006 \u0003למה לי?\u0004 והרי כבר שנינו שאם נשפך הדם מן הצואר על הרצפה אינו טעון כיבוס! ומשיבים: אין זו הלכה נוספת, אלא \u0003מה טעם קאמר\u0004 \u0005[אומר]\u0006 התנא: \u0003מה טעם נשפך\u0004 הדם \u0003על הרצפה ואספו אין טעון כיבוס? לפי שאין טעון כיבוס אלא דם שנתקבל בכלי וראוי להזייה.\u0004","עוד שנינו במשנה, שאין דין כיבוס בגד אלא בדם חטאת ה\u0003ראוי להזאה.\u0004 ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט מה]\u0006 באה הלכה זו? והרי כבר אמרנו שאין דם פסול טעון כיבוס! ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 אם \u0003קיבל\u0004 הכהן דם מן הקרבן \u0003פחות מכדי\u0004 שיעור \u0003הזייה בכלי זה, ופחות מכדי הזייה בכלי זה,\u0004 ועירב את שני הדמים, שאף שעתה יש בהם שיעור הזאה אין הדם נחשב ראוי להזאה. ומנין שכך הוא?","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 לענין מי חטאת של פרה אדומה שצריך לקדשם על ידי אפר הפרה, \u0003ר' חלפתא בר שאול אומר: קידש\u0004 הכהן \u0003פחות מכדי הזייה בכלי זה, ופחות מכדי הזייה בכלי זה\u0004 אף ששב ועירב אותם — \u0003לא קידש.\u0004","בעקבות הלכה זו \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם עשה כן הכהן \u0003בדם\u0004 חטאת פנימית, שקיבל פחות משיעור הזיה בכלי זה ופחות משיעור בכלי זה, ועירבם, \u0003מהו\u0004 דינו? וצדדי השאלה: האם \u0003הלכתא\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005]\u0006 \u0003היא\u0004 בדין מי חטאת של פרה אדומה, שאם עשה כן — לא התקדשו בכך, \u0003ומהלכתא לא גמרינן\u0004 \u0005[ומהלכה אין אנו למדים]\u0006 לעניינים אחרים.","\u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003התם\u0004 \u0005[שם,\u0006 במי חטאת\u0005]\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שהם אינם כשרים? משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בשעת ההזאה: \u0003\"וטבל במים\"\u0004 (במדבר יט, יח), בה\"א הידיעה, ומשמע: באותם מים שנתן מתחילה בכלי, ומכאן שכשנתנם בכלי צריכים היו להיות ראויים להזאה. ואם כן, \u0003הכא נמי כתיב\u0004 \u0005[כאן גם כן,\u0006 בדם חטאת, \u0005נאמר]:\u0006 \u0003\"וטבל\u0004 הכהן את אצבעו בדם והזה מן הדם\" (ויקרא ד, ו), ונלמד באותו אופן, שיהא זה באותו דם שהיה כבר מתחילה ראוי להזאה, ואם לא היה בו מתחילה שיעור ראוי — אינו מתקדש.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ש\u0003אמר ר' זריקא\u0004 שכך \u0003אמר ר' אלעזר\u0004 בפירוש: אף בדם אם עשה כן — \u0003לא קידש.\u0004","ובאותו ענין \u0003אמר רבא, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין חטאת פנימית, שמזים מדמה בהיכל: \u0003\"וטבל\u0004 הכהן את אצבעו בדם והזה מן הדם\". ויש לדייק: \"וטבל אצבעו בדם\" — שיהא די דם כדי שיטבול בו את אצבעו, \u0003ולא\u0004 שיהא \u0003מספג\u0004 (מקנח) הדם באצבעו מדפנות הכלי ומתחתיתו. \u0003\"בדם\"\u0004 — \u0003עד שיהא בדם שיעור טבילה מעיקרו,\u0004 ולא כשהיה בו מתחילה פחות מכשיעור וחזר והוסיף לו. \"והזה \u0003מן הדם\"\u0004 — \u0003מן הדם ש\u0004נזכר \u0003בענין,\u0004 כלומר, מן הדם שבכלי.","ומסביר רבא: \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב\u0006 בתורה\u0005]\u0006 גם \u0003\"בדם\"\u0004 וגם \"וטבל\", משום \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"וטבל\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 די שיש בדם עכשיו כדי לטבול בו את האצבע, \u0003אף על פי דליכא\u0004 \u0005[שאין,\u0006 שלא היה\u0005]\u0006 בדם \u0003שיעור טבילה מעיקרו,\u0004 לכן \u0003כתב [רחמנא]\u0004 \u0005[כתבה התורה]\u0006 \u0003\"בדם\".\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"בדם\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי אם מתחילה היה בדם כשיעור הראוי, אינו צריך שתהא אצבעו טבולה בדם כל פעם שמזה, אלא \u0003אפילו מספג\u0004 מקנח מדפנות הכלי — \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"וטבל\",\u0004 שיהא בדרך טבילה.","ומבררים עוד את האמור בברייתא \"והזה מן הדם\" — \u0003מן הדם שבענין.\u0004 ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט מה]\u0006 בא התנא? \u0003אמר רבא: למעוטי\u0004 \u0005[למעט]\u0006 \u0003שיריים ש\u0004נותרו \u0003באצבע\u0004 לאחר הזאה, שאינו יכול להזותם, אלא צריך כל פעם לחזור ולטבול את האצבע בדם שבכלי. והוסיף רבא: \u0003מסייע\u0004 לו הדבר \u0003לר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: שיריים שבאצבע פסולין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין בר רב אדא לרב\u0004 (לרבא): \u0003אמר תלמידך,\u0004 כך \u0003אמר רב עמרם, תנינא\u0004 \u0005[שנינו]\u0006 שלא כדברי ר' אלעזר: \u0003היה מזה\u0004 מדם חטאות פנימיות, \u0003וניתזה הזאה מידו\u0004 על הבגד, \u0003עד שלא הזה\u0004 — \u0003טעון כיבוס, משהזה\u0004 — \u0003אין טעון כיבוס.\u0004","\u0003מאי לאו הכי קאמר\u0004 \u0005[האם לא כך אמר]:\u0006 \u0003עד שלא גמר מלהזות\u0004 — \u0003טעון כיבוס,\u0004 אפילו ניתז משיריים שבאצבע, \u0003משגמר להזות\u0004 — \u0003אין טעון כיבוס?\u0004 ואם שיריים שבאצבע פסולים, מדוע הם טעונים כיבוס? השיב לו רבא: \u0003לא, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003עד שלא יצתה הזאה מידו\u0004 — \u0003טעון כיבוס, משיצתה הזאה מידו\u0004 — מה שנותר על אצבעו \u0003אין טעון כיבוס.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו בהזיית דמה של פרה אדומה: \u0003גמר מלהזות\u0004 — \u0003מקנח ידו בגופה של פרה.\u0004 ונדייק: \u0003גמר\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא גמר\u0004 — \u0003לא,\u0004 למרות שנותרו שיריים על אצבעו. ומכאן שאינם פסולים להזייה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא, כך יש להבין: \u0003גמר\u0004 כל ההזאות — \u0003מקנח ידו בגופה של פרה, לא גמר\u0004 — \u0003מקנח אצבעו\u0004 אחר כל הזאה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גמר\u0004 את כל ההזאות \u0003מקנח ידו בגופה של פרה,\u0004 כפי \u0003שנאמר: \"ושרף את הפרה לעיניו\u0004 את עורה ואת בשרה ואת דמה\" (במדבר יט, ה), הרי שצריך לשרוף את מה שנותר מדמה יחד עם בשרה. \u0003אלא אצבעו במאי\u0004 \u0005[במה]\u0006 \u0003מקנח\u0004 לאחר כל הזאה? שאם יקנחנו בגופה של הפרה יידבקו בה השערות, והרי הוא צריך להמשיך ולהזות! \u0003אמר אביי:\u0004 מקנח \u0003בשפת מזרק\u0004 (כלי הדם), \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"כפורי זהב\"\u0004 (עזרא א, י), והם המזרקים. והם נקראים \"כפורים\" משום שמכפרים (= מקנחים) בהם את הדם.","בתורה נזכר דין כיבוס דם חטאת מן הבגד (ויקרא ו, כ), ודנים מה נכלל בבגד שהזכירה התורה. \u0003ניתז\u0004 מדם החטאת \u0003על העור,\u0004 אם ניתז עליו \u0003עד שלא הופשט\u0004 מן הבהמה — \u0003אינו טעון כיבוס,\u0004 לפי שאינו נחשב כבגד, שהוא דבר הראוי לקבל טומאה. ואם ניתז הדם על העור משהופשט, ומעתה הוא ראוי לקבל טומאה, כשיחשוב להשתמש בו — \u0003טעון כיבוס,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' אלעזר אומר: אף\u0004 אם ניתז הדם על העור \u0003משהופשט\u0004 — \u0003אינו טעון כיבוס\u0004 עד שיוכשר בפועל ככלי המקבל טומאה. זה הכלל בדיני כיבוס: אין כל הבגד חייב בכיבוס, \u0003אלא מקום\u0004 שניתז עליו \u0003הדם, ו\u0004אין חייב בכיבוס אלא \u0003דבר שהוא ראוי לקבל טומאה, ו\u0004דבר שהוא \u0003ראוי לכיבוס.\u0004","\u0003אחד הבגד\u0004 המפורש בתורה, \u0003ואחד השק ואחד העור\u0004 — \u0003טעונין כיבוס. ו\u0004עוד בדיני כיבוס: \u0003הכיבוס\u0004 נעשה \u0003במקום קדוש\u0004 (בעזרה שבמקדש). \u0003ו\u0004כן \u0003שבירת כלי חרס\u0004 שבשלו בהם חטאת (כאמור בויקרא ו, כא) אף היא צריכה להיעשות \u0003במקום קדוש, ו\u0004כן \u0003מריקה ושטיפה בכלי נחושת\u0004 שהתבשלה בהם חטאת (ויקרא ו, כא) אף אלו צריכות להיעשות \u0003במקום קדוש. זה חומר\u0004 (חומרה) שיש \u0003בחטאת מקדשי קדשים\u0004 אחרים.","על מחלוקת ר' יהודה ור' אלעזר במשנתנו האם דם שניתז על עור הבהמה שהופשט חייב בכיבוס, מבררים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה,\u0006 מה המקור לשיטותיהם\u0005]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא: נאמר בדין כיבוס הבגד \"ואשר יזה מדמה על ה\u0003בגד\"\u0004 (ויקרא ו, כ) — \u0003אין לי אלא בגד, מנין לרבות\u0004 גם \u0003עור משהופשט\u0004 מהבהמה? \u0003תלמוד לומר\u0004 בהמשך הפסוק: \u0003\"אשר יזה עליה תכבס\"\u0004 (ויקרא ו, כ) — לרבות כל שהוזה עליו מן הדם.","ומעתה יש לשאול: \u0003יכול שאני מרבה\u0004 לדין כיבוס אף \u0003עור עד שלא הופשט? תלמוד לומר: \"בגד\"\u0004 — \u0003מה\u0004 פיסת \u0003בגד\u0004 כלשהי הריהי דבר \u0003הראוי לקבל טומאה,\u0004 אם יחשוב להשתמש בה, כטלאי לבגדו, \u0003אף כל\u0004 דבר \u0003הראוי לקבל טומאה\u0004 כשיחשוב להשתמש בו כמות שהוא, חייב מעתה בכיבוס. ועור — רק משהופשט ראוי הוא לקבל טומאה, אם יחשוב להשתמש בו כשטיח וכיוצא בו, אלו \u0003דברי ר' יהודה.\u0004","ואילו \u0003ר' אלעזר,\u0004 הסבור שאף משהופשט העור אין הוא חייב בכיבוס, \u0003אומר,\u0004 כך יש לדרוש את הכתוב: \u0003\"בגד\"\u0004 — \u0003אין לי אלא בגד, מנין לרבות\u0004 גם \u0003שק\u0004"],["\u0003ו\u0004כן \u0003כל מיני בגדים\u0004 העשויים מחומרים אחרים, שיהו אף הם חייבים בכיבוס? \u0003תלמוד לומר: \"אשר\u0004 יזה \u0003עליה תכבס\"\u0004 (ויקרא ו, כ) — שכל שהוא ראוי לכיבוס, הריהו חייב בכיבוס אם ניתז עליו דם חטאת. ומעתה יש לשאול, \u0003יכול שאני מרבה עור\u0004 בהמה כבר \u0003מ\u0004שעה \u0003שהופשט\u0004 ממנה? \u0003תלמוד לומר: \"בגד\"\u0004 — \u0003מה בגד\u0004 הריהו \u0003דבר המקבל טומאה\u0004 כמות שהוא, \u0003אף כל דבר המקבל טומאה\u0004 חייב בכיבוס, ואילו עור בהמה משהופשט אינו מקבל טומאה כמות שהוא, אלא רק ראוי לקבל טומאה משיחשוב להשתמש בו, ולכן אינו חייב בכיבוס. זו שיטת ר' אלעזר. וכאמור לעיל, לשיטת ר' יהודה אף בגד הראוי לקבל טומאה חייב בכיבוס, אף שעדיין אינו מקבל טומאה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]\u0006 בין ר' יהודה ור' אלעזר, כלומר, איזה דבר ראוי לקבל טומאה, אך אינו מקבל טומאה? \u0003אמר אביי: מטלית\u0004 שהיא \u0003פחותה משלש\u0004 אצבעות מרובעות \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 לדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שכל ה\u0003ראוי\u0004 לקבלת טומאה חייב בכיבוס — \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 בכלל \u0003ראוי\u0004 לקבל טומאה היא, \u0003דאי בעי חשיב עליה\u0004 \u0005[שאם ירצה יחשוב עליה]\u0006 לשימוש מסויים (כגון כטלאי לבגדו). ואילו לדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שרק \u0003דבר המקבל טומאה\u0004 הריהו חייב בכיבוס — \u0003הא מיהא לאו בת קבולי\u0004 \u0005[זו על כל פנים אינה בת קבלת\u0006\u0005]\u0006 \u0003טומאה היא,\u0004 ואינה חייבת איפוא בכיבוס.","\u0003רבא אמר\u0004 הסבר אחר: \u0003בגד ש\u0004כשעשאו מתחילה \u0003חישב עליה\u0004 \u0005[עליו]\u0006 \u0003לצורה,\u0004 כלומר, לעשות עליו ציור או קישוט, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שהואיל ועשאו לשם כך, הרי כל עוד לא עשה כן — אין הבגד נחשב כלי הראוי לקבל טומאה. לדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שכל ה\u0003ראוי\u0004 לקבל טומאה חייב בכיבוס — \u0003הא נמי\u0004 \u0005[זה גם כן]\u0006 \u0003ראוי\u0004 לקבל טומאה, \u0003דאי בעי מבטיל ליה למחשבתיה\u0004 \u0005[ש\u0006הרי \u0005אם\u0006 הוא \u0005רוצה\u0006 הריהו \u0005מבטל את מחשבתו]\u0006 ומחליט שהבגד ראוי לו כמות שהוא, ואז הוא מקבל טומאה. ואילו לדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שרק \u0003דבר המקבל טומאה\u0004 חייב בכיבוס — \u0003השתא מיהא לאו בת קבולי\u0004 \u0005[עכשיו על כל פנים אינה בת קבלת]\u0006 \u0003טומאה היא\u0004\u0005,\u0006 ואינה חייבת איפוא בכיבוס.","ולפי לשון אחרת, \u0003רבא אמר\u0004 הסבר אחר: \u0003עוצבא\u0004 (כעין שטיח) \u0003דחשיב עלה\u0004 \u0005[שחשב עליה]\u0006 \u0003לקצעה\u0004 (לקוצצה בחיתוך מדוייק) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 לדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שכל דבר ה\u0003ראוי\u0004 לקבל טומאה חייב בכיבוס — \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003ראויה\u0004 לקבל טומאה לכשיקצענה, וחייבת בכיבוס. ואילו לדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שרק \u0003דבר המקבל טומאה\u0004 חייב כיבוס — \u0003הא לאו\u0004 \u0005[זו\u0006 הרי \u0005אינה]\u0006 \u0003מקבלה טומאה עד דמקצע לה\u0004 \u0005[שמקצע אותה].\u0006 \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן מנסיא אומר: עוצבא שחשב עליה לקצעה\u0004 — \u0003טהורה עד שיקציענה.\u0004","שנינו במשנה: \u0003אין טעון כיבוס\u0004 אלא מקום הדם, ולא כל הבגד. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על מה שנאמר בענין כיבוס הבגד: \"ואשר יזה מדמה על הבגד...\" (ויקרא ו, כ), \u0003יכול נתז\u0004 הדם \u0003על מקצת בגד יהא כל הבגד טעון כיבוס? תלמוד לומר\u0004 מיד אחר כך: \u0003\"אשר יזה\u0004 עליה\" (ויקרא ו, כ) — \u0003לא אמרתי לך\u0004 לכבס \u0003אלא מקום\u0004 שהוזה עליו ה\u0003דם בלבד.\u0004","ועוד שנינו במשנה: כל \u0003דבר שהוא ראוי לקבל טומאה\u0004 טעון כיבוס. ומעירים: \u0003סתמא\u0004 \u0005[סתם\u0006 דברי המשנה אלו\u0005]\u0006 הריהם \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 בתחילת המשנה, ולא כשיטת ר' אלעזר, הסבור שרק דבר המקבל טומאה בפועל חייב בכיבוס.","ועוד שנינו במשנה שכל דבר ה\u0003ראוי לכיבוס\u0004 חייב בכיבוס. ומסבירים: לשון זו באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003כלי\u0004 מדין כיבוס, משום \u0003דבר\u0004 \u0005[שבן]\u0006 \u0003גרידה הוא,\u0004 שמגרדים ממנו את הדם, ולא מכבסים אותו, כבגד שנספג בו הדם.","שנינו במשנה: \u0003אחד הבגד ואחד השק\u0004 ואחד העור טעונין כיבוס. ושואלים: מתוך ששנינו תחילה כי רק דבר שהוא ראוי לכיבוס טעון כיבוס, יש \u0003למימרא\u0004 \u0005[לומר]\u0006 מכאן ש\u0003עור בר\u0004 \u0005[בן]\u0006 \u0003כיבוס הוא. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו במשנה בהלכות שבת: \u0003היתה עליו\u0004 על הכר \u0003לשלשת\u0004 (צואת עופות) — \u0003מקנחה בסמרטוט\u0004 יבש, אבל אינו שוטף אותה במים, משום איסור כיבוס בשבת. \u0003היתה\u0004 הלשלשת \u0003על\u0004 כר \u0003של עור\u0004 — \u0003נותן עליה מים עד שתכלה.\u0004 משמע שאין בעור משום כיבוס כלל!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003\"אחרים\". דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדין כיבוס דם חטאת: \u0003הבגד והשק\u0004 — \u0003מכבסו, הכלי והעור\u0004 — \u0003מגררו. אחרים אומרים: הבגד והשק והעור\u0004 — \u0003מכבסו, והכלי\u0004 — \u0003מגררו.\u0004 ומשמע שלדעת חכמים אין בעור כיבוס, ולדעת אחרים יש בו כיבוס.","ומעירים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו]\u0006 ש\u0003אמר רב חייא בר אשי: זימנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים הרבה הייתי עומד לפני]\u0006 \u0003רב\u0004 בשבת, \u0003ושכשיכי ליה מסאניה במיא\u0004 \u0005[ושכשכתי לו מנעליו\u0006 שנתלכלכו \u0005במים],\u0006 ולא חשש לאיסור כיבוס, משום שהיו נעליו עשויות מעור? \u0003כמאן\u0004 \u0005[כמי]\u0006 — \u0003כרבנן\u0004 \u0005[כחכמים]\u0006 שבברייתא זו.","\u0003אמר רבא: ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 ש\u0003עור לאו בר\u0004 \u0005[לא בן]\u0006 \u0003כיבוס הוא? והכתיב\u0004 \u0005[והרי נאמר]\u0006 בדיני נגע צרעת: \u0003\"והבגד או השתי או הערב או כל כלי העור אשר תכבס\"\u0004 (ויקרא יג, נח)! \u0003אלא אמר רבא: קרא ומתניתין\u0004 \u0005[הכתוב\u0006 בענין נגע הצרעת, \u0005והמשנה\u0006 שלנו בענין כיבוס מדם חטאת\u0005]\u0006 מדברים \u0003ב\u0004עורות \u0003רכין,\u0004 ובאלה ודאי שיש בהם כיבוס. ואולם \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 חכמים אם יש בעורות משום כיבוס הרי זה \u0003ב\u0004עורות \u0003קשין.\u0004","ומקשים על הסבר זה: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חייא\u0004 בר אשי: \u0003זימנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים הרבה הייתי עומד לפני]\u0006 \u0003רב\u0004 בשבת, \u0003ושכשיכי ליה מסאניה במיא\u0004 \u0005[ושכשכתי לו מנעליו במים].\u0006 והרי נעליים עשויות לרוב מעור רך, ולדברי רב, הרי לדעת הכל יש בו משום כיבוס! ומשיבים: מדובר היה \u0003ב\u0004נעלים העשויות מעורות \u0003קשין, ו\u0004נהג רב \u0003כ\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שאין בעורות קשים משום כיבוס.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: לאו מילתא היא דאמרי\u0004 \u0005[אין זה דבר\u0006 נכון מה \u0005שאמרתי],\u0006 להעמיד את המקרא בענין צרעת בעורות רכים; וכי אנו \u0003ניקו נימא ליה לקרא דכי כתיבן ברכין כתיבן\u0004 \u0005[נעמוד\u0006 ו\u0005נאמר לו למקרא\u0006 בענין נגע צרעת, \u0005שכאשר כתובים\u0006 כלי עור, דווקא \u0005ב\u0006עורות \u0005רכים כתובים]\u0006 ולא בעורות קשים? \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 גם \u0003בכלי אכסלגיא\u0004 (עור קשה) \u0003הבאים ממדינת הים, וקאמר רחמנא\u0004 \u0005[ואמרה התורה]:\u0006 \u0003ניבעי\u0004 \u0005[שיצטרך]\u0006 הם \u0003כיבוס?\u0004","\u0003אלא אמר רבא:\u0004 אף שהכתוב בנגע צרעת עוסק גם בכלי עור קשים, מכל מקום אין קושי ממה שהם טעונים כיבוס, שכן ה\u0003צרעת, כיון דמגופיה קא פרחה\u0004 \u0005[שמגופו\u0006 של הבגד \u0005היא פורחת]\u0006 הריהי \u0003מחלחלא ליה ומשוי לה\u0004 \u0005[מחלחלת,\u0006 מרפה, \u0005אותו ועושה אותו]\u0006 \u0003רך. אמר רבא: אי קשיא\u0004 \u0005[אם קשה]\u0006 \u0003לי,\u0004 לשיטתי, שבעור רך יש כיבוס לדעת הכל, \u0003הא קשיא\u0004 \u0005[\u0006דבר \u0005זה\u0006 הוא ש\u0005קשה]\u0006 \u0003לי,\u0004"],["\u0003כרים וכסתות\u0004 ש\u0003רכין נינהו\u0004 \u0005[הם],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 לענין שבת: \u0003היתה\u0004 הכר \u0003של עור\u0004 — \u0003נותן עליה מים עד שתכלה\u0004 הלשלשת, משמע שאין כיבוס כלל בכלי עור! \u0003אלא אמר רבא: כל כיבוס דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003כיסכוס\u0004 שאינו משפשף את הבגד, \u0003לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003כיבוס,\u0004 ולכן יכול לתת מים על כר או כסת של עור רך, למרות שיש בהם דין כיבוס.","\u0003והא\u0004 \u0005[וזה]\u0006 ש\u0003אמר רב חייא בר אשי: זימנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים הרבה הייתי עומד לפני]\u0006 \u0003רב\u0004 בשבת, \u0003ושכשיכי ליה מסאניה במיא\u0004 \u0005[ושכשכתי לו\u0006 את \u0005נעליו במים],\u0006 ונדייק: \u0003שכשוך\u0004 במים — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל כבוס\u0004 — \u0003לא!\u0004 יש לפרש: \u0003אי\u0004 \u0005[אם]\u0006 \u0003ב\u0004נעלים מעורות \u0003רכין וכדברי הכל, אי\u0004 \u0005[אם]\u0006 \u0003ב\u0004נעלים מעורות \u0003קשין, וכ\u0004שיטת \u0003\"אחרים\"\u0004 (בברייתא שהובאה לעיל) הסבורים שגם בהם יש דין כיבוס של דם חטאת.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ששכשוך במים בלבד אינו נחשב כיבוס, \u0003בגד נמי\u0004 \u0005[גם כן]\u0006 יתן עליו מים כדי לנקותו, ומדוע שנינו שמותר רק לקנחו בסמרטוט! ומשיבים: \u0003בגד\u0004 — \u0003שרייתו זהו כיבוסו,\u0004 ולכן אסור ליתן מים עליו.","ומעירים: \u0003[רבא\u0004 בענין זה הולך \u0003לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר רבא:\u0004 אם \u0003זרק סודר למים\u0004 בשבת — \u0003חייב, זרק\u0004 זרעי \u0003פשתן למים\u0004 — \u0003חייב.\u0004 ודנים לגופה של הלכה זו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003סודר\u0004 שלא יזרקנו למים — משום שהוא סבור כי שריה \u0003עביד\u0004 \u0005[עושה]\u0006 \u0003כיבוס], אלא זרע פשתן מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003משום דמקדח\u0004 \u0005[שמתחיל לצמוח]\u0006 ויש בכך משום איסור זריעה, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003חיטי ושערי נמי\u0004 \u0005[חטים ושעורים גם כן]!\u0006 ומשיבים: טעם הדבר אינו משום זריעה, אלא \u0003הנך אית להו רירי\u0004 \u0005[אלה,\u0006 זרעי פשתן, \u0005יש להם ריר]\u0006 המופרש מהם במים. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003שלחים\u0004 (עורות) \u0003נמי\u0004 \u0005[גם כן],\u0006 הרי גם להם יש ריר היוצא מהם במים! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בפשתן, הרי זה \u0003קעביד\u0004 \u0005[עושה]\u0006 \u0003לישה\u0004 האסורה בשבת, מה שאין כן בשלחים.","ועוד בענין זה מסופר, \u0003דרש רבא\u0004 בציבור: \u0003מותר לכבס מנעל בשבת.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא בר אשי: זימנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים הרבה הייתי עומד לפני]\u0006 \u0003רב\u0004 בשבת, \u0003ושכשיכי ליה מסאני במיא\u0004 \u0005[ושכשכתי לו נעליו במים].\u0006 ונדייק: \u0003שכשוך\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל כיבוס\u0004 — \u0003לא!\u0004 כיון ששמע זאת \u0003הדר אוקי\u0004 \u0005[חזר והעמיד]\u0006 \u0003רבא אמורא עליה\u0004 \u0005[מתורגמן עליו]\u0006 \u0003ודרש\u0004 בציבור: \u0003דברים שאמרתי לפניכם טעות הם בידי, ברם\u0004 (באמת) \u0003כך אמרו\u0004 חכמים: \u0003שכשוך\u0004 במים בשבת — \u0003מותר, כיבוס\u0004 — \u0003אסור.\u0004","שנינו במשנה כי \u0003הכיבוס\u0004 של דם החטאת מן הבגד צריך להיעשות \u0003במקום קדוש,\u0004 וכן גם שבירת כלי חרס, ומריקת כלי נחושת שהתבשל בהם קרבן החטאת. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים האלה]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר \"אשר יזה עליה \u0003תכבס במקום קדש\"\u0004 (ויקרא ו, כ). ו\u0003שבירת כלי חרס מניין\u0004 לנו שכך הדין? \u0003תלמוד לומר\u0004 מיד בהמשך הדברים: \u0003\"וכלי חרס אשר תבשל בו ישבר\"\u0004 (ויקרא ו, כא). \u0003מריקה ושטיפה בכלי נחשת מנין\u0004 לנו שכך הדין? \u0003תלמוד לומר: \"ואם בכלי נחשת בשלה ומרק ושטף במים\"\u0004 (ויקרא ו, כא).","שנינו במשנה: \u0003זה חומר בחטאות\u0004 משאר קדשי קדשים. ושואלים: \u0003ותו\u0004 \u0005[ועוד]\u0006 חומרות בחטאת מבשאר קדשי קדשים \u0003ליכא\u0004 \u0005[אין]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 בהן דין זה: \u0003שנכנס דמה\u0004 של חטאת \u0003לפני ולפנים\u0004 להיכל ולקודש הקדשים לשם הזאה! ומתרצים: לא עסקה המשנה אלא \u0003בחטאות החיצונות.\u0004","וחוזרים ושואלים: הרי אף בחטאות החיצוניות ישנה חומרה מיוחדת, \u0003שאם נכנס דמה (לפני ו)לפנים\u0004 להיכל הריהי \u0003פסולה!\u0004 ומשיבים: התנא של משנתנו סבור \u0003כ\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר: כל דמים,\u0004 לא רק של חטאת, אלא גם של קרבנות אחרים, \u0003שנכנסו להיכל לכפר\u0004 — \u0003פסולה,\u0004 ואין זו חומרה המיוחדת לחטאת.","ושואלים עוד: והרי יש חומרה מיוחדת בחטאות \u0003שכן מכפרין\u0004 קרבנות אלה \u0003על חייבי כריתות\u0004 שעשו בשגגה! ומשיבים: מדובר כאן גם \u0003בחטאת\u0004 הבאה על \u0003שמיעת הקול\u0004 (של אדם שנשבע שאינו יודע עדות לחבירו), שאין בה כרת במזיד.","ושואלים עוד: והרי יש בחטאת חומרה מיוחדת \u0003שכן טעונה\u0004 (חייבת) \u0003ארבע מתנות\u0004 (נתינות) דם על ארבע קרנות המזבח. ובשאר קדשי קדשים שתים שהן ארבע! ומשיבים: תנא זה סבור \u0003כ\u0004דעת \u0003ר' ישמעאל,\u0004 ש\u0003אמר: כל דמים\u0004 של הקרבנות \u0003טעונין ארבע מתנות על ארבע קרנות.\u0004 ולפיכך לדעת התנא של משנתנו, אין בחטאת חיצונה אלא חומרה זאת, של כיבוס דמה.","ועל כך מקשים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שכך אתה מתרץ את המשנה, הרי אפשר לחזור ולשאול עוד ועוד: \u0003האיכא\u0004 \u0005[הרי יש]\u0006 חומרות נוספות, שכן דם החטאת ניתן על \u0003קרן\u0004 המזבח דווקא, ולא למטה מאמצע המזבח, וכן \u0003האיכא\u0004 \u0005[הרי יש]\u0006 חומרה בדם החטאת שהוא ניתן ב\u0003אצבע\u0004 ולא בכלי, וכן \u0003האיכא\u0004 \u0005[הרי יש]\u0006 חומרה נוספת בחטאת, שכן צריך שדמה יינתן על \u0003חודה\u0004 של קרן המזבח! \u0003אלא\u0004 יש לחזור ממה שסברנו תחילה ולפרש באופן אחר, שמה שנאמר \"זה חומר בחטאת משאר קדשי קדשים\" — \u0003חד מתרי תלתא חומרי נקט\u0004 \u0005[אחת משתים שלוש חומרות תפס\u0006 התנא\u0005],\u0006 ולא התכוון לומר שזו היא החומרה היחידה שיש בחטאת.","\u0003בגד ש\u0004ניתז עליו דם חטאת ו\u0003יצא\u0004 אל \u0003מחוץ לקלעים\u0004 (חוץ לעזרה) לפני שכובס — \u0003נכנס ומכבסו במקום קדוש.\u0004 ואם \u0003נטמא\u0004 הבגד \u0003חוץ לקלעים,\u0004 והרי אסור להכניס טומאה לעזרה — \u0003קורעו\u0004 כך ששוב אינו קרוי בגד, ובטלה בכך טומאתו, ו\u0003נכנס ומכבסו במקום קדוש.\u0004 וכן \u0003כלי חרס ש\u0004התבשל בו קרבן חטאת, והריהו חייב שבירה בעזרה, ו\u0003יצא\u0004 אל \u0003מחוץ לקלעים\u0004 — \u0003נכנס\u0004 עם הכלי \u0003ושוברו במקום קדוש.\u0004 ואם \u0003נטמא\u0004 הכלי \u0003חוץ לקלעים\u0004 — הרי זה \u0003נוקבו\u0004 (עושה בו חור) כדי לטהרו מטומאתו, \u0003ונכנס ושוברו במקום קדוש.\u0004","וכן הוא הדין ב\u0003כלי נחשת ש\u0004התבשל בו קרבן חטאת, והרי הוא חייב במריקה ושטיפה בעזרה, ו\u0003יצא\u0004 אל מ\u0003חוץ לקלעים\u0004 — \u0003נכנס ומורקו ושוטפו במקום קדוש.\u0004 ואם \u0003נטמא\u0004 בהיותו מ\u0003חוץ לקלעים\u0004 — \u0003פוחתו\u0004 (עושה בו חור גדול), \u0003ונכנס ומורקו ושוטפו במקום קדוש.\u0004","שנינו במשנה שבגד שניתז עליו דם חטאת, ונטמא חוץ לעזרה, יש לקורעו כדי לטהרו, ואז להכניסו ולכבסו. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא:\u0004 כיון ש\u0003קורעו,\u0004 שוב אינו טעון כיבוס, שכן \u0003\"בגד\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שיש לכבס, ואילו זה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בגד הוא,\u0004 אלא פיסת בד!","ומשיבים: אינו קורע אותו לגמרי, אלא ש\u0003משייר ביה\u0004 \u0005[בו]\u0006 קצת \u0003כדי מעפורת\u0004 (סודר קטן). ושואלים על כך: \u0003איני\u0004 \u0005[כך הוא]?\u0006 וכי באופן זה נטהר הבגד? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: לא שנו\u0004 שטלית טמאה שנקרע רובה הריהי נטהרת בכך, \u0003אלא שלא שייר בה\u0004 בחלק שלא נקרע \u0003כדי מעפורת, אבל\u0004 אם \u0003שייר בה כדי מעפורת\u0004 — הרי \u0003חבור הוי\u0004 \u0005[הוא],\u0006 ועדיין הבגד נשאר בטומאתו, ואם כן מה הועיל כששייר כדי מעפורת!"],["ומשיבים: זה שאמר רב הונא שעדיין טמא הוא, הרי זה \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003הוא,\u0004 שגזרו חכמים עליו טומאה, שמא לא יקרע מספיק. ואולם מדין תורה נטהר הבגד, ולכן רשאים להכניסו לעזרה לשם כיבוס דם החטאת.","עוד שנינו במשנה כי \u0003כלי חרס ש\u0004בושל בו בשר חטאת ו\u0003יצא\u0004 חוץ לעזרה ונטמא שם, יש לנוקבו תחילה כדי להוציאו מטומאתו, ואחר כך מכניסו ושוברו במקדש. ושואלים על כך אותה שאלה: והרי בדין זה של שבירה, \u0003\"כלי\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ו\u0004זה לאחר שניקב \u0003לא כלי הוא!\u0004 ומשיבים: מדובר \u0003שניקב\u0004 רק כשיעור \u0003שורש קטן,\u0004 שאמנם מיטהר בכך כלי החרס מטומאתו, לפי ששוב אינו ראוי לבישול, אבל עדיין הוא נחשב כלי לצרכים אחרים, כגון להניח בו פירות.","ועוד שנינו במשנה כי \u0003כלי נחשת\u0004 שבושל בו בשר חטאת, ויצא אל מחוץ לעזרה ונטמא שם, יש ל\u0003פוחתו\u0004 תחילה, ואחר כך להכניסו לעזרה, ולמורקו ולשוטפו שם. ושואלים שוב: \u0003והא\u0004 \u0005[והרי]\u0006 לאחר שפוחתו, מעתה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלי הוא!\u0004 ומשיבים: \u0003דרציף מרציף\u0004 \u0005[שמרקעו\u0006 ומחברו\u0005]\u0006 \u0003(הוא),\u0004 והוא חוזר להיות כלי, ואז מורקו ושוטפו.","על מה ששנינו במשנה, שבגד שניתז עליו דם חטאת, ויצא ונטמא — קורעו ונכנס ומכבסו, \u0003אמר ריש לקיש: מעיל\u0004 של כהן גדול \u0003ש\u0004ניתז עליו דם חטאת, ויצא ו\u0003ניטמא\u0004 — אינו קורעו, אלא \u0003מכניסו\u0004 לעזרה שלב שלב, כאשר בכל פעם מכניס \u0003בפחות מ\u0004שיעור בגד טמא, שהוא \u0003שלש\u0004 אצבעות \u0003על שלש\u0004 אצבעות, \u0003ומכבסו\u0004 לאותו חלק. שכן לקרוע את המעיל אי אפשר, \u0003משום שנאמר\u0004 במעיל: \u0003\"לא יקרע\"\u0004 (שמות כח, לב).","\u0003מותיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אדא בר אהבה\u0004 ממה ששנינו במשנה: הבגדים \u0003העבין\u0004 ביותר \u0003והרכים\u0004 כגון מיני \u0003לבד,\u0004 \u0003אין בהן\u0004 קבלת טומאה \u0003משום שלש\u0004 אצבעות \u0003על שלש\u0004 אצבעות, שהוא שיעור טומאה של בגד שמשתמשים בו כטלאי וכיוצא בו, משום שאינם ראויים לכלום בשיעור זה, אלא רק בשיעור גדול יותר. וכיון שהמעיל של כהן גדול הוא בגד עבה, בו אין טומאה בשיעור של שלוש על שלוש, ולמה מכניסו לעזרה דווקא בפחות משיעור זה!","ומשיבים: חלקי המעיל הללו, \u0003אגב אביהן\u0004 (המעיל) שהוא בגד חשוב, אף הם הריהם \u0003חשיבי\u0004 \u0005[חשובים]\u0006 ומקבלים טומאה בשיעור שלוש אצבעות, אף שהם עבים.","ובאים לדון בעצם דין הכיבוס של דם חטאת בעזרה: \u0003והא בעי\u0004 \u0005[והרי צריך]\u0006 לכבס את הדם על ידי \u0003שבעת סממנין\u0004 (חומרי הכיבוס). שכן \u0003אמר רב נחמן אמר רבה בר אבוה: דם חטאת\u0004 שניתז על הבגד \u0003ומראות נגעים\u0004 של בגדים, שנאמר בהם דין כיבוס (ויקרא יג, נד) — \u0003צריכין שבעת סממנין\u0004 המנויים במשנה שהם מעבירים את דם הנדה (נדה סא,ב), ובין הסממנים הללו יש גם מי רגלים. \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 לענין עשיית הקטורת, שמי רגלים יפים לה, \u0003אלא שאין מכניסין מי רגלים למקדש\u0004 מפני כבוד המקדש. ואם כן כיצד אפשר לכבס דם חטאת במקדש?"],["\u0003וכי תימא דמבלע להו בהדי\u0004 \u0005[ואם תאמר שמבליע אותם,\u0006 את מי הרגלים, \u0005יחד עם]\u0006 שאר \u0003שבעה סממנין, ומעבר להו לכולהו כחד\u0004 \u0005[ומעביר אותם את כולם ביחד]\u0006 על הבגד, באופן שאין מי הרגלים ניכרים לעצמם — \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 לענין בדיקת כתם, האם דם נדה הוא: אם \u0003העבירן\u0004 את הסממנים הללו \u0003שלא כסדרן\u0004 האמור במשנה, \u0003או שהעביר שבעתן כאחד\u0004 — \u0003לא עשה ולא כלום!\u0004","\u0003וכי תימא דמיבלע להו בהדי חד\u0004 \u0005[ואם תאמר שמבליע אותם,\u0006 את מי הרגלים, \u0005בתוך אחד]\u0006 \u0003מ\u0004שבעת ה\u0003סממנין\u0004 — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003צריך לכסכס\u0004 לשפשף את הכתם \u0003שלש פעמים בכל אחד ואחד\u0004 מהסממנים הללו לעצמו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006 \u0003אלא\u0004 צריך לומר \u0003דמבלע להו\u0004 \u0005[שמבליע,\u0006 מבטל \u0005אותם\u0006 את מי הרגלים\u0005]\u0006 \u0003ברוק תפל\u0004 (שאין בו טעם), רוק של אדם שלא טעם כלום קודם לכן, שכן \u0003אמר ריש לקיש: רוק תפל צריך שיהא עם כל אחד ואחד\u0004 מהסממנים.","\u0003אחד\u0004 כלי \u0003שבישל בו\u0004 בשר חטאת על גבי האש, \u0003ואחד\u0004 כלי \u0003שעירה לתוכה\u0004 תבשיל \u0003רותח,\u0004 וכן \u0003אחד קדשי הקדשים ואחד קדשים קלים\u0004 שנתבשלו בכלי נחושת \u0003טעונין\u0004 (חייבים) \u0003מריקה ושטיפה. ר' שמעון אומר:\u0004 כלים שבישלו בהם \u0003קדשים קלים אין טעונין מריקה ושטיפה.\u0004","בענין ששנינו במשנתנו, שגם כלי שעירו לתוכו רותח טעון שבירה, מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפרשת החטאת \"וכלי חרס \u0003אשר תבשל בו\u0004 ישבר\" (ויקרא ו, כא) — \u0003אין לי\u0004 שנוהג דין זה \u0003אלא\u0004 בכלי \u0003שבישל בו,\u0004 אם \u0003עירה לתוכו רותח מנין\u0004 לנו? \u0003תלמוד לומר: \"ואשר תבשל בו ישבר\"\u0004 (ויקרא ו, כא), מצירוף המלים \"בו ישבר\" אנו למדים שבכל אופן בו נמצא בו החטאת (\"בו\") הריהו חייב שבירה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 אם \u0003תלאו\u0004 את בשר החטאת \u0003באויר תנור\u0004 (חרס) כדי לצלותו, \u0003מהו\u0004 דין התנור? וצדדי השאלה: האם על \u0003בישול ו\u0004גם \u0003בילוע\u0004 של טעם החטאת בכלי \u0003הוא דקפיד רחמנא\u0004 \u0005[שהקפידה התורה],\u0006 כשהצריכה שבירה בכלי חרס, \u0003או דילמא\u0004 \u0005[שמא]\u0006 על \u0003בישול\u0004 בכלי בלבד, ואפילו \u0003בלא בילוע\u0004 מגוף החטאת הקפידה תורה, ולכן אף חטאת התלויה באויר התנור מחייבת לשוברו, שהרי נתבשל בשר החטאת בחללו?","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו במשנתנו: \u0003אחד שבישל בו ואחד שעירה לתוכו רותח\u0004 טעון שבירה. הרי שהכלי נאסר גם אם לא בושלה בו החטאת, אלא רק נבלע בו טעמה על ידי עירוי. ואם כן, אין צורך בבישול ובילוע גם יחד.","ודוחים: באופן של \u0003בלוע\u0004 בכלי \u0003בלא בישול לא קמיבעיא לן\u0004 \u0005[נשאלה לנו],\u0006 שהוא בוודאי טעון שבירה, שהרי אין כלי חרס פולט לעולם מה שבלע. \u0003כי קמיבעיא לן\u0004 \u0005[כאשר נשאלה לנו\u0006 השאלה\u0005]\u0006 בתלוי באוירו של תנור, הרי זה באופן של \u0003בישול בלא בילוע, מאי\u0004 \u0005[מה]\u0006 יהא הדין?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר רב נחמן אמר רבה בר אבוה: תנור של מקדש, של מתכת היה. ואי סלקא דעתך\u0004 \u0005[ואם עולה בדעתך]\u0006 ש\u0003בישול בלא בלוע לא קפיד\u0004 \u0005[הקפידה]\u0006 התורה, ואין כלי חרס חייב שבירה באופן זה, \u0003ניעביד\u0004 \u0005[נעשה]\u0006 אותו \u0003של חרס!\u0004 ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 גם \u0003שירי מנחות\u0004 הנאכלים לכהנים, ש\u0003אפייתן בתנור ואיכא\u0004 \u0005[ויש\u0006 בהם\u0005]\u0006 \u0003בישול ובילוע,\u0004 שהרי מניחים את השיריים על התנור עצמו, ולא בחללו, ויש בהם שמן הנבלע בו, \u0003עבדינן\u0004 \u0005[עושים אנו]\u0006 \u0003של מתכת.\u0004","מסופר, \u0003ההוא תנורא דאטחו בה טיחייא\u0004 \u0005[תנור אחר\u0006 של חרס \u0005שטחו בו,\u0006 בדפנותיו וקרקעיתו, \u0005שומן בשר],\u0006 ואפו בו לחם, \u0003אסרה רבה בר אהיליי למיכלה לריפתא\u0004 \u0005[לאכול את הפת]\u0006 שאופים בתנור זה \u0003לעולם, ואפילו במילחא\u0004 \u0005[במלח]\u0006 בלבד, גזירה \u0003דילמא אתי למיכלה בכותחא\u0004 \u0005[שמא יבוא לאכול אותה\u0006 יחד \u0005עם כותח]\u0006 שיש בו חלב. שלדעתו אין השומן נפלט מדפנותיו לעולם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003אין לשין את העיסה בחלב, ואם לש עיסה\u0004 בחלב — \u0003כל הפת כולה אסורה, מפני הרגל עבירה,\u0004 שמא יבואו לאכול אותה עם בשר.","\u0003כיוצא בו אין טשין\u0004 (מורחים) \u0003את התנור באליה\u0004 שהיא שומן מן החי, \u0003ואם טש\u0004 — \u0003כל הפת\u0004 שאפה בו \u0003כולה אסורה עד שיסיק את התנור,\u0004 ועל ידי כך יישרף השומן שהיה בלוע בו. על כל פנים הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבה בר אהיליי,\u0004 שלדעתו אין תקנה לתנור כזה בכלל! ומשיבים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: וכי מאחר דאיתותב\u0004 \u0005[שהושב]\u0006 ונדחו דברי \u0003רבה בר אהיליי, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אמר רב: קדירות\u0004 של חמץ \u0003בפסח ישברו?\u0004 מדוע לא יבער את החמץ שבהן על ידי הסקה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003רב מוקי לה\u0004 \u0005[מעמיד אותה]\u0006 את הברייתא \u0003ההיא,\u0004 שיש תקנה לתנור על ידי הסקה, דווקא \u0003ב\u0004תנור \u0003של מתכת,\u0004 שעל ידי ההיסק הוא פולט את השומן.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 אפשר לומר שמדובר גם \u0003בתנור של חרס,\u0004 ומכל מקום אין להכשיר קדרות בדרך זו, שכן \u0003זה,\u0004 תנור — דרך \u0003הסיקו מבפנים,\u0004 והאש שורפת את השומן שבדפנות. \u0003וזה,\u0004 בקדירות — דרך \u0003הסיקו מבחוץ,\u0004 כשהקדירות עומדות על האש, ואין החום מספיק כדי לבער את החמץ שבצד הפנימי.","ושואלים: \u0003ונעביד\u0004 \u0005[ושיעשה]\u0006 בקדירות גם כן \u0003הסקה מבפנים,\u0004 ויתקן אותם על ידי זה! ומשיבים: אין מתירים להכשירם באופן זה, משום שאדם \u0003חייס עלייהו דמתברי\u0004 \u0005[חס עליהם\u0006 שמא \u0005יישברו],\u0006 ויש לחשוש שלא יעשה היסק כראוי מבפנים. ומכאן מסקנה למעשה: \u0003הילכך, האי כוביא\u0004 \u0005[רעף של חרס]\u0006 שמשתמשים בו כתבנית לאפיה, על גבי האש, \u0003הסיקו מבחוץ הוא, ואסיר\u0004 \u0005[ואסור].\u0006"],["ושואלים: \u0003אלא\u0004 לשיטה זו שיש תקנה בהיסק לכלי חרס, \u0003קדירות של מקדש\u0004 שמבשלים בהם בשר חטאת ושאר קדשים \u0003אמאי אמר רחמנא\u0004 \u0005[מדוע אמרה תורה]\u0006 \u0003ישברו? נהדרינהו\u0004 \u0005[נחזיר אותן]\u0006 \u0003לכבשונות\u0004 שעושים בהם כלי חרס, ובחום הגדול של הכבשונות יישרף כל מה שנבלע בתוכם! \u0003אמר ר' זירא:\u0004 אי אפשר לעשות זאת, \u0003לפי שאין עושין כבשונות בירושלים\u0004, בגלל העשן הרב העולה מהם.","\u0003אמר אביי:\u0004 אם מטעם זה, כיצד שוברים את כלי החרס? \u0003וכי עושין אשפתות בעזרה?\u0004 ומעירים: \u0003אישתמיטתיה הא דתני\u0004 \u0005[נשמט\u0006 נשכח \u0005ממנו\u0006 מאביי \u0005מה ששנה]\u0006 \u0003שמעיה בקלנבו\u0004 ש\u0003שברי כלי חרס\u0004 שבמקדש היה בהם נס שהיו \u0003נבלעין במקומן.\u0004","וחוזרים ומקשים: \u0003אלא\u0004 אם היסק מבפנים מועיל לתנור להכשירו, אם כן, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב נחמן אמר רבה בר אבוה: תנור של מקדש של מתכת הוה\u0004 \u0005[היה],\u0006 מדוע לא \u0003נעביד\u0004 \u0005[נעשה\u0006 אותו\u0005]\u0006 של \u0003חרס?\u0004 שהרי \u0003הסיקו\u0004 של תנור \u0003מבפנים הוא!\u0004","ומשיבים: ש\u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003שתי הלחם ולחם הפנים\u0004 שלא רק \u0003אפייתן בתנור\u0004 אלא גם \u0003קדושתן\u0004 הקדשתם להקרבה נעשית \u0003בתנור,\u0004 לפי שאין לישתם נעשית בכלי שרת — \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 התנור \u0003כלי שרת, וכלי שרת\u0004 מ\u0003חרס לא עבדינן\u0004 \u0005[אין אנו עושים].\u0006"],["\u0003ואפילו ר' יוסי בר' יהודה\u0004 שאמר שניתן לעשות כלי שרת מעץ, \u0003לא קאמר\u0004 \u0005[אמר]\u0006 את שיטתו זו \u0003אלא\u0004 בשל \u0003עץ,\u0004 שיש לו חשיבות מסויימת, \u0003אבל\u0004 בכלי שרת שנעשה מ\u0003חרס\u0004 — \u0003לא\u0004 אמר.","בקשר לדין שטיפה ומריקה ששנינו במשנתנו, מסופר, \u0003רב יצחק בר יהודה הוה\u0004 \u0005[היה]\u0006 \u0003רגיל\u0004 בתחילה ללמוד \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רמי בר חמא. שבקיה ואזיל\u0004 \u0005[עזב אותו והלך]\u0006 ללמוד אצל \u0003רב ששת. יומא חד פגע ביה\u0004 \u0005[יום אחד פגש אותו]\u0006 רמי בר חמא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 לפי הפתגם העממי: \u0003אלקפטא נקטן, ריחא אתי לה ליד\u0004 \u0005[השר הגדול אחז בי\u0006 בידי, \u0005והריח\u0006 הטוב שיש בו \u0005בא לה ליד שלי]?\u0006 שכך סבורים אנשים, שאם יתקרבו לגדולים — ידבק בהם מגדולתם. ואף אתה, וכי \u0003משום דאזלת\u0004 \u0005[שהלכת]\u0006 \u0003לך\u0004 ממני כדי ללמוד \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב ששת,\u0004 האם \u0003הוית לך כי\u0004 \u0005[אתה נעשה\u0006 בכך \u0005כמו]\u0006 \u0003רב ששת?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו משום הכי\u0004 \u0005[לא משום כך]\u0006 הלכתי, אלא מטעם אחר: \u0003מר, כי בעינא מילתא\u0004 \u0005[אדוני, כאשר אני שואל\u0006 ממנו \u0005דבר]\u0006 — \u0003פשיט\u0004 \u0005[פותר,\u0006 עונה] \u0003לי\u0004 אותה \u0003מסברא,\u0004 ולכן \u0003כי משכחנא מתניתא\u0004 \u0005[כאשר אני מוצא משנה]\u0006 האומרת שלא כסברה זו, הרי היא \u0003פרכא לה\u0004 \u0005[פורכת,\u0006 שוברת את \u0005אותה\u0006 סברה\u0005].\u0006 ואילו \u0003רב ששת, כי בעינא מילתא מיניה\u0004 \u0005[כאשר אני שואל דבר ממנו]\u0006 — \u0003פשיט\u0004 \u0005[פותר]\u0006 \u0003לי\u0004 אותה \u0003ממתניתא\u0004 \u0005[ממשנה],\u0006 \u0003דכי נמי משכחת מתניתא ופרכא\u0004 \u0005[\u0006כך \u0005שגם\u0006 אם \u0005אתה מוצא משנה\u0006 אחרת \u0005שפורכת\u0006 אותה\u0005],\u0006 מכל מקום \u0003מתניתא ומתניתא\u0004 \u0005[משנה\u0006 מול \u0005משנה]\u0006 \u0003היא,\u0004 ואין דבריו בטלים לגמרי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא לרב יצחק בר יהודה: \u0003בעי מיני מילתא, דאיפשיט לך כי מתניתא\u0004 \u0005[שאל ממני דבר, ואפתור לך כמו\u0006 שנאמר \u0005במשנה].\u0006 \u0003בעא מיניה\u0004 \u0005[שאל אותו]:\u0006 אם \u0003בישל\u0004 חטאת \u0003במקצת כלי,\u0004 האם הכלי כולו \u0003טעון מריקה ושטיפה או אין טעון? אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא: \u0003אינו טעון, מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין] בענין \u0003הזאה,\u0004 ששנינו לעיל (זבחים צג,ב) שאם ניתז מדם החטאת על הבגד אין כולו טעון כיבוס אלא מקום הדם.","אמר לו רב יצחק בר יהודה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא תנא הכי\u0004 \u0005[שנוי כך\u0006 במשנה\u0005]\u0006 לענין מריקה ושטיפה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא: למרות שלא נאמרו הדברים במפורש, \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 הדבר שיהיה דינו של כלי לענין שטיפה ומריקה \u0003כ\u0004דינו של \u0003בגד\u0004 לענין כיבוס ששנינו במשנה (לעיל זבחים צג,ב): \u0003מה בגד\u0004 שניתז עליו מדם חטאת \u0003אינו טעון כיבוס אלא מקום הדם, אף כלי\u0004 שהתבשל בו חטאת \u0003אינו טעון מריקה ושטיפה אלא במקום בישול.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק בר יהודה: \u0003מי דמי\u0004 \u0005[האם\u0006 הדברים \u0005דומים]?\u0006 \u0003דם\u0004 — \u0003לא מפעפע\u0004 וחודר בכל הבגד, אלא רק במקום שנדבק בו, ואילו \u0003בישול\u0004 — טעמו של הבשר \u0003מפעפע\u0004 בכל הכלי! \u0003ועוד, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 מפורשת שלא כדבריך: \u0003חומר\u0004 (חומרה) יש \u0003ב\u0004דין \u0003הזאה\u0004 (דין כיבוס של דם חטאת שהוזה וניתז על בגד) \u0003מ\u0004דין \u0003מריקה ושטיפה\u0004 בכלי נחושת, \u0003וחומר\u0004 יש \u0003במריקה ושטיפה\u0004 יותר \u0003מבהזאה:\u0004","\u0003חומר בהזאה\u0004 — \u0003שהזאה ישנה בחטאות החיצונות\u0004 (הנעשות במזבח החיצון) \u0003ובחטאות הפנימיות\u0004 (שמזים מדמן בהיכל), \u0003וישנה לפני זריקה\u0004 של הדם. \u0003מה שאין כן במריקה ושטיפה,\u0004 שנעשית רק בחטאות החיצונות הנאכלות, שמבשלים את בשרן, ורק לאחר זריקת הדם, כשהותר בשרן לבישול.","ומצד שני, \u0003חומר במריקה ושטיפה\u0004 — \u0003שהמריקה ושטיפה נוהגת בין בקדשי קדשים בין בקדשים קלים,\u0004 ואם \u0003בישל במקצת הכלי\u0004 — \u0003טעון מריקה ושטיפה\u0004 של \u0003כל הכלי, מה שאין כן בהזאה,\u0004 שרק מקום הדם טעון כיבוס!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא: \u0003אי תניא תניא\u0004 \u0005[אם שנויה\u0006 משנה מפורשת, הרי היא \u0005שנויה]\u0006 ואיני יכול להתווכח איתה. ומבררים: \u0003ו\u0004באמת \u0003טעמא מאי\u0004 \u0005[מה הטעם]\u0006 שאם בישל במקצת הכלי טעון כל הכלי מריקה ושטיפה? \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ואם בכלי נחשת בשלה\u0004 ומורק ושוטף במים\" (ויקרא ו, כא), \u0003ו\u0004מן המלה \"בכלי\" אנו מדייקים: \u0003אפילו\u0004 אם בושלה \u0003במקצת כלי\u0004 — ומורק ושוטף הכלי במים.","שנינו במשנה: \u0003אחד קדשי קדשים\u0004 ואחד קדשים קלים טעונים מריקה ושטיפה. ומביאים בענין זה מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 במקרא נאמר דין של מריקה ושטיפה ב\u0003חטאת,\u0004 ולכאורה \u0003אין לי אלא חטאת\u0004 בלבד, \u0003כל קדשים מנין\u0004 שגם בהם נוהג דין זה? תלמוד לומר מיד אחר כך: \"כל זכר בכהנים יאכל אותה, \u0003קדש קדשים היא\"\u0004 (ויקרא ו, כב), ללמדנו שדין זה שייך בכל הקדשים שאוכלים הכהנים.","\u0003יכול שאני מרבה\u0004 גם \u0003את התרומה,\u0004 שאף נקראת קודש ונאכלת רק לכהנים (ראה ויקרא כב, יד)? \u0003תלמוד לומר\u0004 שם \"כל זכר בכהנים יאכל אותה\" (ויקרא ו, כב), ויש בכך הדגשה: \u0003\"אותה\"\u0004 — \u0003פרט לתרומה,\u0004 אלו \u0003דברי ר' יהודה. ר' שמעון אומר: קדשי קדשים\u0004 בלבד \u0003טעונין מריקה ושטיפה, קדשים קלים\u0004 — \u0003אינן טעונין מריקה ושטיפה.\u0004 ומסבירים: טעמו של ר' שמעון הוא ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קדש קדשים\",\u0004 ומכאן אתה למד: \u0003קדשי קדשים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003קדשים קלים\u0004 — \u0003לא.\u0004","ויש לשאול איפוא: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה,\u0004 שאינו למד כך? ומשיבים: \u0003מדאיצטריך\u0004 \u0005[מכיון שהוצרך]\u0006 הכתוב \u0003\"אתה\" למעוטי\u0004 \u0005[למעט]\u0006 \u0003תרומה, מכלל\u0004 הדברים אתה למד ש\u0003קדשים קלים טעונין מריקה ושטיפה.\u0004 שאם אינם טעונים מריקה ושטיפה — כל שכן שתרומה אינה טעונה, ולא היה צורך למיעוט זה. \u0003ר' שמעון אמר\u0004 \u0005[אומר]\u0006 \u0003לך:\u0004 \u0003\"אתה\"\u0004 נצרך \u0003כדאמרינן\u0004 \u0005[כמו שאמרנו]\u0006 — למעט חטאת שנפסלה.","ושואלים: \u0003ו\u0004האם \u0003תרומה\u0004 שהתבשלה בכלי נחושת \u0003לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003שטיפה ומריקה? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003קדרה שבישל בה בשר\u0004 — \u0003לא יבשל בה חלב, ואם בישל\u0004 בה — הרי היא אוסרת את החלב אם יש \u0003ב\u0004בשר הבלוע בקדירה כדי \u0003נותן\u0004 (נתינת) טעם בחלב. וכן קדירה שבישל בה \u0003תרומה\u0004 — \u0003לא יבשל בה חולין, ואם בישל\u0004 — אוסרת \u0003בנותן טעם.\u0004 ומכאן שהקדירה צריכה הגעלה כדי לפלוט את טעם הבשר שבה!","\u0003אמר אביי: לא צריכא\u0004 \u0005[נצרכה]\u0006 מריקה ושטיפה שנאמרה בקדשים \u0003אלא לדאמר מר\u0004 \u0005[לכמו שאמר החכם]\u0006 בברייתא: אם \u0003בישל במקצת כלי\u0004 — \u0003טעון מריקה ושטיפה כל הכלי. הא\u0004 \u0005[אבל]\u0006 \u0003תרומה\u0004 שבישל בה — \u0003לא צריך\u0004 מריקה ושטיפה \u0003אלא מקום בישול.\u0004","\u0003רבא אמר: לא צריכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא לדאמר מר\u0004 \u0005[לכמו שאמר החכם]\u0006 בברייתא, על מה שנאמר בדין מריקה ושטיפה \"ומורק ושוטף במים\" (ויקרא ו, כא): \u0003\"במים\"\u0004 — \u0003ולא ביין, \"במים\"\u0004 — \u0003ולא ב\u0004יין \u0003מזוג\u0004 במים. \u0003הא\u0004 \u0005[אבל]\u0006 תרומה יכול להגעיל את הכלי שבושלה בו \u0003אפילו ביין ואפילו במזוג.\u0004","\u0003רבה בר עולא אמר: לא צריכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא לדאמר מר\u0004 \u0005[לכמו שאמר החכם]\u0006 במשנה להלן: \u0003מריקה ושטיפה\u0004 האמורות בחטאת, שתיהן \u0003בצונן,\u0004 בנוסף להגעלה בחמין, שצריך כדי להוציא את טעם החטאת. \u0003הא\u0004 \u0005[אבל]\u0006 קדירה שבישל בה תרומה — \u0003אפילו\u0004 בהגעלה \u0003בחמין\u0004 לבדה די לה.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003מריקה ושטיפה בצונן, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003מריקה\u0004 היא הגעלה \u0003בחמין ושטיפה בצונן, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 האם מיעט הכתוב תרומה מדין הגעלה בחמין? ומשיבים לדרך זו, לא מיעטה התורה תרומה ממריקה, אלא לענין \u0003שטיפה יתירתא\u0004 \u0005[יתירה]\u0006 שהצריך הכתוב בחטאת לאחר המריקה.","\u0003ר' טרפון אומר: בישל\u0004 חטאת בכלי נחושת \u0003מתחילת הרגל\u0004 — \u0003יבשל בו כל הרגל,\u0004 ואין צריך למרק ולשטוף אותו לאחר כל פעם. \u0003וחכמים אומרים:\u0004 אינו רשאי לעשות כן, אלא \u0003עד\u0004 שיגיע סוף \u0003זמן אכילה\u0004 של הקדשים שבישל צריך לעשות \u0003מריקה ושטיפה.\u0004 ומהם מריקה ושטיפה האמורים בכתוב? \u0003מריקה\u0004 — היא \u0003כמריקת הכוס,\u0004 שרוחצים אותה יפה מבפנים, ששם נדבק היין, \u0003ושטיפה\u0004 — \u0003כשטיפת הכוס\u0004 מבחוץ. \u0003מריקה ושטיפה\u0004 — שניהם \u0003בצונן.\u0004"],["\u0003השפוד\u0004 שתוחבים בבשר כדי לצלותו, \u0003והאסכלא\u0004 שהיא מעין רשת שצולים עליה בשר, אם צלה בהם בשר קדשים — \u0003מגעילן בחמין.\u0004","שנינו במשנה את שיטת ר' טרפון שאם בישל בשר קדשים בכלי בתחילת הרגל, מבשלים בו כל ימי הרגל בלא מריקה ושטיפה, ואין אדם צריך לחשוש שמא הוא אוכל מבשר קדשים שנותר לאחר זמן אכילתו. ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 לשיטתו זו של \u0003ר' טרפון?\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 במצות הפסח: \"ובשלת ואכלת במקום אשר יבחר ה' אלהיך בו \u0003ופנית בבקר והלכת לאהלך\"\u0004 (דברים טז, ז). והרי חג הפסח אינו נגמר בלילה הראשון! אלא מכאן ש\u0003הכתוב עשאו\u0004 (החשיב) \u0003לכולן\u0004 לכל ימי החג, \u0003בקר אחד\u0004 למחרת הרגל, כאילו כולם יום אחד הם.","\u0003מתקיף לה\u0004 \u0005[מקשה על\u0006 הסבר \u0005זה]\u0006 \u0003רב אחדבוי בר אמי:\u0004 וכיצד יכול אתה לומר כן? \u0003וכי אין\u0004 דין \u0003פיגול ברגל,\u0004 שאם חשב הכהן בשעת עבודת הקרבן לאוכלו למחרת לא ייפסל הקרבן משום פיגול, כיון שכל ימי הרגל נחשבים כיום אחד?! \u0003ו\u0004כיוצא בזה, האם \u0003אין\u0004 דין \u0003נותר ב\u0004ימי ה\u0003רגל,\u0004 שאין בשר הקדשים שנותר לאחר זמנו, נפסל בכך?!","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 אכן \u0005כך\u0006 הוא הדין \u0005גם כן]\u0006 שאין דין פיגול ונותר בימי הרגל — \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: לא אמר ר' טרפון\u0004 את דבריו \u0003אלא\u0004 לענין הלכה \u0003זו בלבד,\u0004 של מריקה ושטיפה, ולא לעניינים אחרים, כגון פיגול ונותר!","\u0003אלא\u0004 צריכים לפרש בהסבר שיטת ר' טרפון \u0003כ\u0004דברי \u0003רב נחמן אמר רבה בר אבוה,\u0004 שכן \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 הואיל והשלמים מצויים הרבה ברגל אין הבלוע שבתוך הכלים נעשה נותר, שהרי זמן אכילת השלמים הוא שני ימים, ומה שהוא מבשל \u0003כל יום ויום\u0004 מימי הרגל \u0003נעשה גיעול\u0004 (מפליט) לחבירו שנתבשל ביום הקודם, ולכן רק לאחר הרגל, כאשר יפסיקו לבשל בו, יתחייב בשטיפה ומריקה.","עוד שנינו במשנה: \u0003וחכמים אומרים עד זמן אכילה\u0004 מריקה ושטיפה. ומבררים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 מה פירוש הדברים? \u0003אמר רב נחמן אמר רבה בר אבוה: ממתין לה\u0004 לכלי הנחושת \u0003עד זמן אכילה,\u0004 כל זמן שמותר לאכול מחטאת זו, \u0003והדר עביד\u0004 \u0005[ואז עושה]\u0006 \u0003לה מריקה ושטיפה.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003אבא יוסי בן אבא: כתיב\u0004 \u0005[נאמר]\u0006 בדין כלי נחושת שבושלה בו חטאת: \u0003\"ומרק ושטף\u0004 במים\" (ויקרא ו, כא), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק שלאחריו: \u0003\"כל זכר בכהנים יאכל\u0004 אותה\", \u0003הא\u0004 (הרי) \u0003כיצד?\u0004 והרי ממרקים ושוטפים לאחר אכילה! \u0003ממתין לה\u0004 לכלי הנחושת \u0003עד זמן אכילה, והדר עביד\u0004 \u0005[ו\u0006אז \u0005עושה]\u0006 \u0003לה מריקה ושטיפה.\u0004","שנינו במשנה באופן בו נעשית המריקה והשטיפה, כי ה\u0003מריקה\u0004 — \u0003כמריקת הכוס, שטיפה\u0004 — \u0003כשטיפת הכוס\u0004. מכאן שנינו כי השטיפה והמריקה בצונן. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מריקה ושטיפה\u0004 — \u0003בצונן,\u0004 אלו \u0003דברי רבי. וחכמים אומרים: מריקה\u0004 — \u0003בחמין, ושטיפה\u0004 — \u0003בצונן.\u0004","ומסבירים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה טעמם של חכמים]?\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 לגבי \u0003גיעולי גוים\u0004 שצריכים לעשות הגעלה בחמין לכלי שבישלו בו גוים, כדי לפלוט את האיסור הבלוע בו. \u0003ורבי אמר לך\u0004 \u0005[יכול היה לומר לך]:\u0006 לענין \u0003הגעלה לא קאמינא\u0004 \u0005[איני אומר],\u0006 שודאי יש להגעיל בחמין. \u0003כי קאמינא\u0004 \u0005[כאשר אומר אני]\u0006 הרי זה \u0003ל\u0004מצות \u0003מריקה ושטיפה דבתר\u0004 \u0005[שאחר]\u0006 \u0003הגעלה,\u0004 ששתיהן בצונן.","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 משיבים על כך: \u0003אם כן,\u0004 שהמריקה והשטיפה ענין אחד הן, \u0003לכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 לשון זהה, \u0003או \"מרק מרק\", או \"שטף שטף\", מאי\u0004 \u0005[מה\u0006 ענין\u0005]\u0006 שינוי הלשון \u0003\"ומרק ושטף\"? שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מריקה\u0004 — \u0003בחמין, ושטיפה\u0004 — \u0003בצונן.\u0004","\u0003ורבי,\u0004 מה הוא משיב לטענה זו? \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005כתוב]\u0006 \u0003\"ומרק מרק\",\u0004 או שהיה כתוב \"ושוטף שוטף\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שכוונת הכתוב שיעשה \u0003תרי זימני\u0004 \u0005[שתי פעמים]\u0006 \u0003\"מרק\"\u0004 (מריקה) \u0003או תרי זימני\u0004 \u0005[שתי פעמים]\u0006 \u0003\"שטף\"\u0004 (שטיפה), לכך \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ומרק ושטף\", לומר לך\u0004 שהן שתי פעולות שונות: \u0003מריקה\u0004 — \u0003כמריקת הכוס\u0004 מבפנים, \u0003שטיפה\u0004 — \u0003כשטיפת הכוס\u0004 מבחוץ.","אם \u0003בישל בו\u0004 בכלי אחד בשר \u0003קדשים ו\u0004בשר \u0003חולין, או\u0004 בשר \u0003קדשי קדשים ו\u0004בשר \u0003קדשים קלים, אם יש בהן\u0004 בקדשים (שהתבשלו עם החולין) או בקדשי הקדשים (שהתבשלו עם הקדשים הקלים) שיעור \u0003בנותן\u0004 (נתינת) \u0003טעם\u0004 במה שהתבשל אתם בכלי — \u0003הרי\u0004 דינם של \u0003הקלים\u0004 שבתערובת שיהו \u0003נאכלין כ\u0004דינם של ה\u0003חמורין שבהן,\u0004 בהגבלת הראויים לאכול, וכן זמן ומקום האכילה. \u0003ו\u0004הקלים שבתערובת זו \u0003אינן טעונין\u0004 (חייבים) \u0003מריקה ושטיפה\u0004 של כלי נחושת שנתבשלו בו, \u0003ואינן פוסלים במגע,\u0004 שהנוגע בהם אינו מקבל את דינם של החמורים, ואם פסולים הם — אף הדבר הנוגע נפסל, ואם כשרים הם — הדבר הנוגע צריך להיאכל כדינם.","\u0003רקיק\u0004 כשר \u0003שנגע ברקיק\u0004 פסול, או \u0003חתיכה\u0004 של בשר קדשים שנגעה \u0003בחתיכה\u0004 של בשר פסול — \u0003לא כל הרקיקין\u0004 הכשרים שנגעו נאסרים בנגיעה זו, \u0003ו\u0004כמו כן \u0003לא כל החתיכות אסורין,\u0004 ש\u0003אינו אסור אלא במקום שבלע\u0004 אחד מן השני.","ומבררים את הנאמר בתחילת המשנה, \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 שהרי יש לכאורה סתירה בדברים, שאם יש בקדשי קדשים כדי נתינת טעם בקלים, והקלים נאכלים כחמורים, מדוע אינם טעונים מריקה ושטיפה ואינם פוסלים במגע כמותם? ומשיבים: אכן, צריך להוסיף ולשנות כך את המשנה: \u0003אם יש בהן בנותן טעם\u0004 — \u0003הרי הקלין נאכלין כחמורין, וטעונין מריקה ושטיפה, ופוסלין במגע.\u0004","אם \u0003אין בהן בנותן טעם\u0004 — \u0003אין הקלין נאכלין כחמורים, ואין טעונין מריקה ושטיפה, ואין פוסלין במגע.\u0004 ושואלים: ואם אין בקדשי קדשים כדי נתינת טעם בקדשים קלים, מדוע אין הכלים טעונים מריקה ושטיפה?","\u0003נהי\u0004 \u0005[גם אם אמנם]\u0006 שמדין \u0003קדשי קדשים\u0004 שנתבשלו בהם \u0003לא בעו\u0004 \u0005[צריכים]\u0006 מריקה ושטיפה, אבל \u0003קדשים קלים ניבעי\u0004 \u0005[צריכים]\u0006 מריקה ושטיפה!","\u0003אמר אביי: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין טעונין\" דקאמר\u0004 \u0005[ש\u0006הוא \u0005אמר]?\u0006 \u0003קדשי קדשים\u0004 אין טעונים, \u0003אבל קדשים קלים\u0004 שבושלו בהם \u0003טעונין\u0004 מריקה ושטיפה. \u0003רבא אמר: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: קדשים קלים\u0004 עצמם \u0003אין טעונין מריקה ושטיפה.\u0004","ודנים בדברים, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא, היינו דקתני\u0004 \u0005[זהו ש\u0006הוא \u0005שונה]\u0006 במשנה: בישל בו קדשים וחולין \u0003או קדשי קדשים וקדשים קלים,\u0004 כדי להשמיענו שגם קדשים קלים אינם טעונים מריקה ושטיפה, אם אין בהם בנותן טעם של קדשי קדשים, וכשיטת ר' שמעון. \u0003אלא ל\u0004דעת \u0003אביי, תרתי\u0004 \u0005[שני\u0006 מקרים\u0005],\u0006 גם של קדשים וחולין, וגם של קדשי קדשים וקדשים קלים, \u0003למה לי?\u0004 הרי לכאורה יש להם אותו דין!","ומשיבים: \u0003צריכי\u0004 \u0005[צריכים\u0006 הם\u0005],\u0006 אבל לא לענין מריקה ושטיפה, אלא לעצם דין הבישול, \u0003דאי תנא\u0004 \u0005[שאם היה שונה]\u0006 רק \u0003קדשים וחולין, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003חולין הוא דמבטלי\u0004 \u0005[שמבטלים]\u0006 את ה\u0003קדשים\u0004 אם אין בקדשים כדי לתת בהם טעם, כיון \u0003דלאו מינייהו\u0004 \u0005[שאינם מינם],\u0006 \u0003אבל קדשי קדשים וקדשים קלים אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 כיון שהם נחשבים כמין אחד.","ולהיפך, \u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 רק \u0003קדשי קדשים וקדשים קלים, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003קדשים הוא דאלימי לבטולי\u0004 \u0005[שתקיפים לבטל]\u0006 \u0003קדשים\u0004 אחרים, \u0003אבל חולין אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","שנינו במשנה: \u0003רקיק\u0004 פסול \u0003שהגיע\u0004 (שנגע) \u0003ברקיק\u0004 כשר — אין אסור כל הרקיק הכשר, אלא מקום הבליעה בלבד, וכן לגבי חתיכה שנגעה בחתיכה. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על מה שנאמר בדין החטאת: \u0003\"כל אשר יגע\u0004 בבשרה יקדש\" (ויקרא ו, כ): \u0003יכול\u0004 יהא נוהג דין זה בכל נגיעה שהיא, \u0003אפילו שלא בלע\u0004 כלל? \u0003תלמוד לומר: \"בבשרה\"\u0004 (ויקרא ו, כ) —"],["\u0003עד שיבלע\u0004 ממה ש\u0003בבשרה.\u0004","ומן הצד האחר, \u0003יכול נגע במקצת חתיכה\u0004 ובלע, \u0003יהא כולו פסול? תלמוד לומר:\u0004 \"כל אשר \u0003יגע\u0004 יקדש\" — \u0003הנוגע פסול,\u0004 ולא החלק שלא נגע. \u0003הא כיצד?\u0004 והרי בלע מבשרה! \u0003חותך את מקום שבלע.\u0004 ועוד דורשים: מה שנאמר \u0003\"בבשרה\"\u0004 (ויקרא ו, כ) הרי זה בא למעט: בבשרה דווקא, \u0003ולא בגידין ולא בעצמות ולא בקרנים ולא בטלפים.\u0004","וממשיכה הברייתא: מה שנאמר \"כל אשר יגע בבשרה \u0003יקדש\"\u0004 משמעו שיהיו דיניו \u0003כמוה, הא כיצד? אם פסולה היא,\u0004 כגון שנשחטה חוץ לעזרה — \u0003תפסל\u0004 אף החתיכה שבלעה מן החטאת, ואסורה באכילה כמותה, \u0003ואם כשרה היא\u0004 החטאת — \u0003תאכל\u0004 החתיכה שנגעה בה \u0003כ\u0004דין \u0003חמור שבה,\u0004 וכגון שהיתה זו חתיכת שלמים הנאכלת לשני ימים ולכל אדם, שהיא צריכה להיאכל כדין החטאת הבלועה בה — ליום ולילה ולזכרי כהונה בלבד.","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 כך הוא הדין לגבי בשר קדשים שנגע בחטאת פסולה? \u0003וניתי\u0004 \u0005[ושתבוא]\u0006 מצות \u0003עשה\u0004 של אכילה של החתיכה שנגעה בחטאת הפסולה, \u0003ולידחי\u0004 \u0005[ותדחה]\u0006 \u0003את לא תעשה\u0004 שיש באכילת חטאת שנבלעה בה! \u0003אמר רבא: אין עשה דוחה את לא תעשה שבמקדש.\u0004","שכך שנינו בברייתא על מה \u0003שנאמר\u0004 בקרבן הפסח: \u0003\"ועצם לא תשברו בו\"\u0004 (שמות יב, מו), \u0003ר' שמעון בן מנסיא אומר: אחד עצם שיש בו מוח ואחד עצם שאין בו מוח\u0004 במשמע, שאסור בשבירה. ולכאורה \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הוא כך, \u0003ניתי\u0004 \u0005[שיבוא]\u0006 \u0003עשה\u0004 של אכילת קדשים, ובכלל זה מוח העצם, \u0003ולידחי\u0004 \u0005[וידחה]\u0006 \u0003את לא תעשה\u0004 של \"עצם לא תשברו\"! \u0003אלא\u0004 צריך לומר ש\u0003אין עשה דוחה\u0004 את \u0003לא תעשה שבמקדש.\u0004","\u0003רב אשי אמר\u0004 הסבר אחר: מה שאמר הכתוב \"כל הנוגע בבשרה \u0003יקדש\"\u0004 להיות כמותה — הוא עצמו מצוות \u0003עשה הוא, ו\u0004לפי הכללים של מדרש ההלכה \u0003אין עשה דוחה את לא תעשה ועשה.\u0004","ובהמשך למה שנאמר בחטאת \"כל אשר יגע בבשרה יקדש\" (ויקרא ו, כ), שואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003חטאת\u0004 ש\u0003מתקדש בבלוע, שאר קדשים\u0004 \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שדבר הנוגע בהם יקדש להיות כמותם? \u0003אמר שמואל משום\u0004 (בשם) \u0003ר' אליעזר: נאמר\u0004 \u0003\"זאת התורה לעלה ולמנחה ולחטאת ולאשם ולמלואים ולזבח השלמים\"\u0004 (ויקרא ז, לז), ובפסוק זה הישוותה התורה את הקרבנות אלו לאלו, כך שמן הדין המיוחד שבכל אחד מהם אנו למדים לשאר הקרבנות.","ומפרטים: \u0003\"לעלה\"\u0004 — \u0003כי\u0004 \u0005[כמו]\u0006 \u0003עולה, מה עולה טעונה כלי\u0004 בעשייתה, \u0003אף כל\u0004 בהמת זבחים \u0003טעונה כלי.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003כלי\u0004 זה שלמדנו מעולה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מזרק\u0004 לקבלת הדם, וכפי שלמדנו מן העולות שהוקרבו במעמד הר סיני — הלוא \u0003בשלמי ציבור\u0004 שהקריב משה באותו מעמד \u0003נמי כתיב בהו\u0004 \u0005[גם כן כתוב בהם]\u0006 דין זה: \"ויעלו עולות ויזבחו זבחים... \u0003ויקח משה חצי הדם וישם באגנת\"\u0004 (שמות כד, ה–ו). ואין זה דין מיוחד לעולה!","\u0003אלא\u0004 הכוונה היא ל\u0003סכין\u0004 שאין הזבח נשחט אלא בסכין, ולא באבן חדה או בקנה חד. ושואלים: \u0003ועולה גופה\u0004 \u0005[עצמה]\u0006 \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שצריכה סכין? \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"וישלח אברהם את ידו ויקח את המאכלת\u0004 לשחוט את בנו\" (בראשית כב, י), \u0003והתם\u0004 \u0005[ושם]\u0006 \u0003עולה הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעלהו לעלה תחת בנו\"\u0004 (בראשית כב, יג). וממשיכים בדרשת הפסוק \"זאת התורה\" וכו'.","מה שנאמר שם: \u0003\"מנחה\"\u0004 בא ללמד: \u0003מה מנחה אינה נאכלת אלא לזכרי כהונה\u0004 (כאמור בויקרא ו, ט), \u0003אף כל\u0004 הקרבנות האמורים בפסוק זה \u0003אינם נאכלין אלא לזכרי כהונה.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מהו\u0006 המדובר\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 בא הכתוב ללמדנו לגבי \u0003חטאת ואשם\u0004 — \u0003בהדיא כתיב בהו\u0004 \u0005[במפורש כתוב בהם]\u0006 דין זה, לגבי חטאת — \"כל זכר בכהנים יאכל אותה\" (ויקרא ו, כב), ולגבי אשם — \u0003\"כל זכר בכהנים יאכלנו\"\u0004 (ויקרא ז, ו)!","\u0003ואי\u0004 \u0005[ואם]\u0006 ללמוד מכאן לגבי \u0003שלמי ציבור,\u0004 הבאים בעצרת עם שתי הלחם (ראה ויקרא כג, ט) שלא נאמר בהם דין זה — הלכה זו \u0003מריבוייא דקרא אתי\u0004 \u0005[מריבוי המקרא באה],\u0006 שנאמר: \u0003\"בקדש הקדשים תאכלנו כל זכר יאכל אתו\"\u0004 (במדבר יח, י), ועל כך שנינו בברייתא: \u0003לימד\u0004 כתוב זה \u0003על שלמי ציבור שאינן נאכלין אלא לזכרי כהונה!\u0004","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים\u0006\u0005]\u0006 \u0003היא\u0004 מנין למדים דין זה,"]]};
